update content_bodies set title = '岐阜県関市「あじさいロード」', description = '中部学院大学短期大学の学生がフィールドワークを通じて、関市の観光地を取材しました。彼らは地域の魅力を探求し、観光資源の発掘に努めています。関市は美しいあじさいが咲くことで知られ、訪れる人々に自然の美しさを提供しています。学生たちはこの地域の観光促進に貢献するため、現地の情報を収集し、地域の特性を理解することを目指しています。' where id = 'wDTaFa0NnsYrpaXE13Fr4';
