update content_bodies set title = '岐阜県関市「洞戸観光ヤナ」', description = '中部学院大学短期大学部の学生がフィールドワークを通じて、関市の観光地を取材しました。彼らは地域の魅力を探求し、観光資源の理解を深めることを目的としています。洞戸観光ヤナは、関市の観光名所の一つであり、地域の自然や文化を体験できる場所です。学生たちは、観光地の特徴や訪れる価値についての情報を収集し、地域振興に寄与することを目指しています。' where id = '1cvKtV6H3eiloJaRtYNp1';
