update content_bodies set title = '岐阜県関市「上之保温泉」', description = '中部学院大学短期大学部の学生がフィールドワークを通じて、関市の観光地を取材しました。上之保温泉はその一環として取り上げられ、地域の魅力や観光資源についての理解を深めることを目的としています。学生たちは現地を訪れ、観光地の特徴や訪れる価値についての情報を収集しました。' where id = 'wUuyo3koPk0nUcKZB3Et-';
