update content_bodies set title = '南砺市つくばね森林公園　森の家（もりのいえ）【城端】', description = '南砺市に位置するつくばね森林公園には、森の家という施設があり、訪れる人々が自然と触れ合う機会を提供しています。住所は富山県南砺市理休939-1811で、電話番号は0763-62-1252です。詳細はhttps://www.tabi-nanto.jp/archives/1305で確認できます。' where id = 'ypCjfcCMUkGgunLY7oSdr';
update content_bodies set title = 'Tsukubane Forest Park - Mori no Ie (House of the Forest) in Nanto City', description = 'Located in Nanto City, Toyama Prefecture, Tsukubane Forest Park features Mori no Ie, a facility that offers visitors a chance to connect with nature. The address is 939-1811, Rikyuu, Nanto City, and the contact number is 0763-62-1252. More information can be found at https://www.tabi-nanto.jp/archives/1305.' where id = 'CpHbVdKej4adv7S4qi9Ud';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑪～丸岡城編～', description = '江戸時代以前から残る現存12天守の一つ、丸岡城を特集します。お城の魅力はもちろん、城下町としての魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = 'yLXUxassFyVuZEyNtkJFh';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection ⑪ - Maruoka Castle Edition -', description = 'This edition features Maruoka Castle, one of the twelve existing castles with a keep that has survived since before the Edo period. The charm of the castle itself is highlighted, along with the appeal of the surrounding castle town, as conveyed by the cute bronze character, Kosaburo.' where id = '4632DnyEMXmlDmM_x43Cq';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑫～松本城編～', description = '江戸時代以前から残る現存12天守の一つ、松本城を特集します。お城の魅力はもちろん、城下町としての魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = '3gjvcKDIG7oTGaCjRZbYN';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection No. 12 - Matsumoto Castle Edition', description = 'This edition features Matsumoto Castle, one of the twelve existing castles with original keep structures from before the Edo period. The charm of the castle itself is highlighted, along with the appeal of the surrounding castle town, as conveyed by the character Kosaburo from Cutie Bronze.' where id = '_ERUsG4nvwKqurRDZEWvi';
update content_bodies set title = '神島【ドローン撮影】(鳥羽市)｜観光三重｜三重県の観光・旅行情報', description = '神島は伊勢湾口に浮かぶ小島で、三島由紀夫の小説『潮騒』の舞台となり、恋人の聖地とも呼ばれています。日本で唯一の渡りをする蝶であるアサギマダラや鷹の一種であるサシバが訪れる自然の宝庫で、雄大な海の景観を島時間でのんびり満喫できます。神島は、訪れる人々にとって特別な体験を提供する場所です。' where id = 'Ht5azT-pvyiUDQGMWFFN-';
update content_bodies set title = 'Kamikushima [Drone Photography] (Toba City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Kamikushima is a small island located at the entrance of Ise Bay, known as the setting for Yukio Mishima''s novel ''The Sound of Waves'' and referred to as a ''sacred place for lovers.'' It is a natural treasure trove that attracts the migratory butterfly Asagimadara and the hawk species Sashiba. Visitors can enjoy the magnificent ocean views and relax in the island''s tranquil atmosphere.' where id = 'KxBQliH2XRZ1OrDUHvJgR';
update content_bodies set title = '青山高原【ドローン撮影】(津市・伊賀市)｜観光三重｜三重県の観光・旅行情報', description = '室生赤目青山国定公園の中心に位置する青山高原は、四季折々の自然を楽しむことができる起伏の少ない高原です。高原の北端にある笠取山から青山峠までの約10Kmのワインディングロードは、絶好のドライビングスポットとなっています。頂上付近には、約89基の白い風車がゆったりと羽根を回している壮大な景色が広がっています。' where id = 'ChwBT74ozPBjRUFRG8_lJ';
update content_bodies set title = 'Aoyama Plateau [Drone Photography] (Tsu City, Iga City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Located in the heart of the Muroo Akame Aoyama Quasi-National Park, Aoyama Plateau offers a gentle landscape where visitors can enjoy nature throughout the seasons. The northern end of the plateau features a scenic 10 km winding road from Kasatori Mountain to Aoyama Pass, making it an excellent driving spot. At the summit, approximately 89 white wind turbines gracefully turn, providing a magnificent view.' where id = 'v7vgcW1cktQdJQWkMa9Um';
update content_bodies set title = '鵜倉園地と河村瑞賢公園の河津桜　【ドローン撮影】(度会郡南伊勢町)｜観光三重｜三重県の観光・旅行情報', description = '鵜倉園地にある見江島展望台から見えるかさらぎ池はハートの形をしており、「ハートの入り江」として恋人の聖地に認定されています。また、近くの河村瑞賢公園の南斜面では、河津桜が2月下旬に咲き始め、春の訪れを一足早く知らせてくれます。' where id = 'AeJhHldZIq9gVUd8UPHvQ';
update content_bodies set title = 'Kawazu Cherry Blossoms at Ugura Park and Kawamura Zuiken Park [Drone Footage] (Minamiise Town, Watarai District) | Tourism Mie | Mie Prefecture Travel Information', description = 'The Kasa-ragi Pond, visible from the Mie Island Observatory in Ugura Park, is heart-shaped and recognized as a ''sacred place for lovers.'' Nearby, the Kawazu cherry blossoms bloom in late February, heralding the early arrival of spring.' where id = 'AmkTCPdHifGwTzP1WdUeo';
update content_bodies set title = '高知県・仁淀ブルー 中津渓谷ガイド散策', description = '高知県の仁淀川エリアに位置する中津渓谷は、仁淀ブルーの代表的なスポットの一つです。美しい森や巨岩、滝など多様な風景が広がっており、仁淀ブルーが広く知られる前から人気のある場所でした。ガイドと共に散策することができ、事前の予約が必要です。' where id = 'YnAKcHwdj2tnpCRnNjlBZ';
update content_bodies set title = 'Nakatsu Valley Tour in Kochi JAPAN', description = 'Nakatsu Valley, a representative spot in the Niyodo River area of Kochi Prefecture, offers a diverse landscape featuring beautiful forests, gigantic rocks, and waterfalls. It has been a popular destination even before the Niyodo Blue phenomenon gained recognition. Visitors can explore Nakatsu Valley with a guide, and reservations are required for the tour.' where id = 'FrJ78FKAu0BdIwZOs49Kw';
update content_bodies set title = '高知県　仁淀川エリアPR動画】秋冬みどころ編', description = '仁淀川エリアは、秋も冬も魅力が満載です。秋には味覚狩りや紅葉狩りを楽しむことができ、お遍路旅で心を癒すこともできます。冬にはライトアップや樹氷を楽しむことができ、特別な体験が待っています。仁淀ブルーはいつでも澄んだ青で、皆さんをお迎えしています。この動画では、UFOラインや山荘しらさ、梨狩り、コスモスまつりなど、さまざまなスポットが紹介されています。また、寺院や温泉、美しい自然景観も取り上げられ、地域の魅力が伝わります。' where id = 'HZ-Ua2pZVxWuSYEP9J9Go';
update content_bodies set title = 'Kochi Prefecture Niyodogawa Area PR Video: Autumn and Winter Highlights', description = 'The Niyodogawa area offers plenty of attractions in both autumn and winter. Visitors can enjoy seasonal activities such as fruit picking and viewing autumn leaves, as well as taking a break during their pilgrimage. Winter brings unique experiences like light displays and frost-covered trees. The Niyodo Blue river remains a clear blue, welcoming everyone throughout the year. The video showcases various locations, including UFO Line, Shirasasa Mountain Lodge, pear picking at a local orchard, and the Cosmos Festival, among others. It also features temples, hot springs, and beautiful natural landscapes, highlighting the region''s charm.' where id = '9AdQe0IsMGKJhxFhUrr01';
update content_bodies set title = 'こさぶろうが行く！城街コレクション⑬～エンディング編～', description = '江戸時代以前から残る現存12天守を特集します。お城の魅力はもちろん、城下町としてのまちの魅力も、キューティーブロンズのこさぶろうさんが伝えます。' where id = 'pfU4ctE0fSZEZ_NL7fcKG';
update content_bodies set title = 'Kosaburo Goes! Castle Town Collection Vol. 13 - Ending Edition', description = 'This episode features the existing 12 castle towers that have survived since before the Edo period. Kosaburo from Cutie Bronze conveys the charm of not only the castles themselves but also the appeal of the castle towns.' where id = '6wfHECMwKPajeIGx2t-QD';
update content_bodies set title = '高知県 仁淀川エリアPR動画: 発見の夏旅編 - 高知市Ver', description = 'この動画では、高知県の美しい仁淀川を紹介しています。豊かな水が夏の強い陽射しの下できらめき、流域を潤し、活気ある環境を作り出しています。新しい体験を求めて訪れることを促しています。高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。仁淀川や観光スポットに関する詳細情報は、提供されたリンクをチェックしてください。' where id = '8w6klEudujf7EIoogvuiE';
update content_bodies set title = 'Kochi Prefecture Niyodo River Area PR Video: Summer Travel Edition - Kochi City Version', description = 'This video showcases the beautiful Niyodo River in Kochi Prefecture, where the rich waters shimmer under the strong summer sun. The river nourishes the surrounding area, creating a vibrant environment. It invites travelers to discover new experiences in this picturesque location. With easy access from Kochi City, visitors can enjoy various attractions in Kochi. For more information about the Niyodo River and its tourist spots, check the provided links.' where id = 'x24q1fcwyJCZf330fO7ei';
update content_bodies set title = '沖縄本島の絶景スポット20選', description = '沖縄県への旅行や観光を計画している方に最適なガイドです。豊かな自然に恵まれた沖縄には、景色を妨げるものがなく、数多くの絶景スポットがあります。この記事では、沖縄本島の必見の絶景スポット20か所を紹介します。また、旅行の達人チャンネルでは、旅行をより楽しくするための情報を提供し、旅行を通じて人生を豊かにすることを目指しています。観光業に携わる方々には、地域の観光地や店舗を動画でPRする機会もあります。公式SNSアカウントをフォローして、旅行のヒントや最新情報をチェックしてください。' where id = '6hF5-Zcj4jkZ2MR8bHUFN';
update content_bodies set title = '20 Must-See Scenic Spots in Okinawa Main Island', description = 'This guide is perfect for those planning a trip to Okinawa Prefecture. Blessed with rich natural beauty, Okinawa offers numerous breathtaking scenic spots without any obstructions to the views. In this article, we present 20 must-see scenic locations on Okinawa Main Island. The channel also provides various travel information to enhance your travel experience, aiming to enrich lives through travel. For those in the tourism industry, there are opportunities for promoting local attractions and businesses through video sharing. Follow our official social media accounts for more travel tips and updates.' where id = 'EPDHNfR4PeptRjfoMyd-k';
update content_bodies set title = '岐阜市MICEプロモーションムービー【英語ショートバージョン】', description = 'この動画は岐阜市MICEプロモーションムービーの英語ショートバージョンについて紹介しています。' where id = 'f6oOE9ZX_Ioxd2LUwlEKN';
update content_bodies set title = 'Gifu City MICE Promotion Movie - English Short Version', description = 'This video introduces the English short version of the Gifu City MICE Promotion Movie.' where id = '4Z5NBqyKldTfuWo5sBuWW';
update content_bodies set title = '【高知県 仁淀川エリアPR動画】 ''発見の夏旅編'' 仁淀川町Ver', description = 'この動画では、豊かな水を湛える仁淀川の美しさを紹介しています。夏の陽射しの下で水面がきらめき、流域は潤い豊かに育まれています。高知県の仁淀地域で新しい何かに出会える旅に出ませんか？高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。仁淀川沿いの観光スポットについての詳細は、提供されたリンクを訪れてご覧ください。' where id = 'hb7lj71ytWVUmT4_s5AKO';
update content_bodies set title = 'Kochi Prefecture Niyodo River Area PR Video: ''Summer Travel Edition'' Niyodo Town Version', description = 'This video showcases the beautiful Niyodo River, known for its rich waters and shimmering surface under the summer sun. The river nourishes the surrounding area, creating a lush environment. It invites travelers to discover something new in Kochi Prefecture''s Niyodo region, which is easily accessible from Kochi City. Explore various attractions in Kochi and enjoy the unique experiences it offers. For more information about tourist spots along the Niyodo River, visit the provided link.' where id = 'z1GekcaAa0QtSEMmbFl5D';
update content_bodies set title = '高知県 仁淀川エリアPR動画: 発見の夏旅編 - 日高村Ver', description = 'この動画では、高知県の美しい仁淀川を紹介しています。豊かな水が夏の強い陽射しの下できらめき、流域を潤し、活気ある環境を生み出しています。この絵のように美しい場所で新しい何かを発見する旅に出ませんか？高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。仁淀川エリアの観光情報は、提供されたリンクからご覧いただけます。また、動画内では日高村のSUP体験ができるSUGGOI SPORTSなどのスポットも紹介されています。' where id = 'yIl7pccBCwB2QVfhxPOhM';
update content_bodies set title = 'Kochi Prefecture Niyodo River Area PR Video: Summer Travel Edition - Hidaka Village Version', description = 'This video showcases the beautiful Niyodo River in Kochi Prefecture, where the rich waters shimmer under the strong summer sun. The river nourishes the surrounding area, creating a vibrant environment. It invites travelers to discover something new in this picturesque location. With easy access from Kochi City, visitors can enjoy various attractions in Kochi. For more information about tourism in the Niyodo River area, visit the provided link. The video also features specific spots, including SUGGOI SPORTS for SUP experiences in Hidaka Village.' where id = 'uZ0RR6adDGgT5UPKuoijC';
update content_bodies set title = '【高知県 仁淀川エリアPR動画】 ''発見の夏旅編'' FULL Ver', description = '仁淀川は豊かな水を湛え、夏の陽射しの下で水面がきらめきます。この水は流域を潤し、豊かな自然を育んでいます。新しい発見が待っている高知県・仁淀川へ旅してみませんか？高知市からのアクセスも良好で、様々な高知の魅力を楽しむことができます。動画では桂浜や日曜市、SUP体験、伝統工芸など、仁淀川エリアの観光スポットが紹介されています。仁淀川の美しさと文化をぜひ体験してください。' where id = 'GsxQw3ZgrEc8fR7teCiF-';
update content_bodies set title = 'Kochi Prefecture Niyodo River Area PR Video: ''Summer Travel Edition'' FULL Ver', description = 'The Niyodo River, rich in water, sparkles under the strong summer sun. This water nourishes the surrounding area, fostering a vibrant ecosystem. It is a place where you can encounter something new. Why not travel to Niyodo in Kochi Prefecture? The area is easily accessible from Kochi City, allowing you to enjoy various aspects of Kochi! The video highlights several attractions, including Katsurahama, Sunday Market, and various local experiences such as SUP and traditional crafts. Discover the beauty and culture of the Niyodo River area.' where id = '56b9MFgrBGKCeFS4DCLI5';
update content_bodies set title = '【高知県 仁淀川エリアPR動画】 "究極のブルー編" ダイジェスト版', description = '多忙な日常や将来への不安を抱える人々にとって、仁淀川は心を解き放つ不思議な場所です。ストレスを感じる日々の中で、ふと訪れることで心が軽くなる体験ができると紹介されています。この動画は、仁淀川の「究極のブルー」を自分の目で確かめに訪れることを促しています。美しい自然を体感するために、ぜひ仁淀川を訪れてみてください。' where id = 'ee91-pFHEb1-1Rx8IqaqP';
update content_bodies set title = 'Kochi Prefecture Niyodogawa Area PR Video: ''Ultimate Blue'' Digest Version', description = 'In our busy daily lives, many people experience stress and anxiety due to various constraints and future uncertainties. However, Niyodogawa offers a unique escape where anyone can feel their heart lighten. This area is described as a mysterious place that allows visitors to unwind and find peace. The video invites viewers to experience the ''Ultimate Blue'' of Niyodogawa for themselves, encouraging them to visit and discover its beauty.' where id = 'D8Z6DlgCAgKo-5WRu8MHS';
update content_bodies set title = '仁淀川アウトドアセンターでSUP・クリスタルカヤック体験', description = '高知県仁淀川町の宮崎の河原で、SUPやクリスタルカヤックの体験ができます。心洗われる仁淀川の澄んだ青い水で、アウトドアアクティビティを楽しんでみませんか？忘れられない体験を一緒にしましょう！お問い合せは仁淀川アウトドアセンター、0889-20-9619まで。' where id = 'yBtYd2TM8m8Gj0oPv6dJ_';
update content_bodies set title = 'Experience SUP and Crystal Kayak at Niyodogawa Outdoor Center', description = 'In Niyodogawa Town, Kochi Prefecture, you can enjoy SUP and Crystal Kayak experiences at Miyazaki-no-kawara. The clear blue waters of the Niyodogawa River provide a refreshing environment for outdoor activities. Join us for an unforgettable experience! For inquiries, please contact Niyodogawa Outdoor Center at 0889-20-9619.' where id = '_Aw5vqPdrHDpBHNuZApYT';
update content_bodies set title = 'ニヨドブルーで人気の中津渓谷へ！', description = '仁淀ブルーはどこで見られるのかという問い合わせが多く寄せられています。中津渓谷という人気スポットに行くには、高速道路の伊野I.Cで降り、高知西バイパスを終点まで進み、国道33号線を松山方面にまっすぐ進むと到着します。この情報を参考にすれば、誰でも不安なく訪れることができるでしょう。なお、運転中のながら見は非常に危険ですので、必ず停止してご覧ください。' where id = 'NNP-V6O3nIWYCGCwewvkF';
update content_bodies set title = 'Popular Nakatzu Gorge in Niyodo Blue!', description = 'Many inquiries come in asking where to see Niyodo Blue. To reach the popular spot ''Nakatzu Gorge'', take the expressway and exit at Ino I.C. Continue on the Kochi West Bypass to the end, then head straight on National Route 33 towards Matsuyama. This guide should help anyone visit without anxiety. Please remember that driving while distracted is very dangerous, so stop to read this!' where id = 'RytD51x5WOL78YZ0P_qq7';
update content_bodies set title = '【モデルコース】上町佐川と雨竜の滝を訪れる', description = '高知県佐川町の上町と仁淀川町中津渓谷の雨竜の滝を紹介する動画です。自然の美しさを体験し、癒されに来てください。一般社団法人仁淀ブルー観光協議会が提供しています。' where id = 'KRPCBcTO_hv7S5JL6KOij';
update content_bodies set title = 'Model Course: Visiting Kamimachi Sagawa and Uryu Falls', description = 'This video showcases Kamimachi in Sagawa Town, Kochi Prefecture, and Uryu Falls in Nakatsu Valley, Niyodogawa Town. Come and experience the healing nature of these beautiful locations.' where id = 'TFDslSPzZsMYyCKnCnoSV';
update content_bodies set title = '神秘的な滝壺❝にこ淵❞', description = '「仁淀ブルー」と呼ばれる美しい景観が広がる名所で、一般社団法人仁淀ブルー観光協議会がその魅力を発信しています。訪れる人々は、透き通った青い水と自然の美しさに心を奪われることでしょう。SNSでも情報が発信されており、Twitter、Instagram、Facebookを通じて最新の情報を得ることができます。' where id = 'Gmp3VFWFk9MNCoeuUcbaD';
update content_bodies set title = 'Mysterious Waterfall Pool ''Niko-buchi''', description = '''Niyodo Blue'' is a representative scenic spot.' where id = '1Sjz9XgF0GColKrJ8qFcm';
update content_bodies set title = '上から見てもニヨドブルー❝宮崎の河原キャンプ場❞', description = '仁淀川町の池川大橋の下に位置する宮崎の河原キャンプ場は、水の透明度が非常に高く、美しい景観を楽しむことができるキャンプスポットです。' where id = 'qcJXyDLcwNpJp4RAgXrz0';
update content_bodies set title = 'Niyodo Blue: Miyazaki''s River Campsite from Above', description = 'Located beneath the Ikekawa Ohashi Bridge in Niyodogawa Town, this river campsite in Miyazaki boasts exceptionally high water transparency, making it a picturesque spot for camping.' where id = '_hBvAjFQycdk3sp4UBrEr';
update content_bodies set title = 'ニセコのもう一つの顔', description = 'パウダースノーで知られるニセコは、世界有数のリゾート地です。冬の半分を過ごすニセコの裏には、壮大で緑豊かな自然が広がっています。このチャンネルは、北海道ニセコエリアにある倶知安観光協会が運営しています。' where id = 's2f3bcQJ8M39q1t5wKBBD';
update content_bodies set title = 'THE OTHER SIDE OF NISEKO', description = 'Niseko, renowned for its powder snow, is one of the world''s top resort destinations. While it spends half the year in winter, it is also home to magnificent and lush nature. This channel is operated by the Kutchan Tourism Association, located in the Niseko area of Hokkaido.' where id = 'MhAfmOsiX9Wm-Adju-yW-';
update content_bodies set title = 'ニヨドブルーで人気の安居渓谷へ！', description = '仁淀ブルーはどこで見られるのかという問い合わせが多く寄せられています。安居渓谷に行くには、伊野I.C.を出て、いの町市街を通り、194号線を直進します。途中の分岐路で439号線に入り、その後安居渓谷の看板が見えます。この案内を参考にすれば、誰でも不安なく目的地に到達できるはずです。運転中の確認は危険ですので、必ず停車してご覧ください。' where id = 'Cx62KLeR8NlovW8U-IBqD';
update content_bodies set title = 'Popular Yasui Gorge in Niyodo Blue!', description = 'Many inquiries come in asking where to see Niyodo Blue. To reach Yasui Gorge, exit at Ino I.C., pass through Ino town, and continue straight on Route 194. At a fork in the road, take Route 439, and you will see a sign for Yasui Gorge. This guide should help anyone reach the destination without anxiety. Please remember that distracted driving is very dangerous, so stop to check directions!' where id = 'NJwBT7AIsxKrifBnfVA1D';
update content_bodies set title = '❝奇跡の清流❞ 仁淀川の四季', description = '「奇跡の清流」と称される仁淀川は、西日本最高峰の石鎚山から太平洋へ流れる一級河川です。日本一の水質を誇り、その美しい水の色は「仁淀ブルー」と呼ばれています。この地域には、絶景の渓谷や神秘的な森、山里に住む人々の営みが広がり、日本の原風景が楽しめます。' where id = '5_5RzdVXBIYG7yk3XnsCn';
update content_bodies set title = 'Miraculous Clear Stream: The Four Seasons of Niyodo River', description = 'The Niyodo River, known as the ''Miraculous Clear Stream,'' flows from the highest peak in western Japan, Mount Ishizuchi, to the Pacific Ocean. It is renowned for having the best water quality in Japan, with its beautiful water color referred to as ''Niyodo Blue.'' The area features breathtaking gorges, mystical forests, and the lives of people in the mountain villages, showcasing Japan''s original landscapes.' where id = 'xPSQX3XnlaR6eyo_uRfBf';
update content_bodies set title = 'まつりびと 〜神田際 2023〜', description = '4年ぶりの天下祭である神田際が復活しました。この祭りは日本文化や日本人の脈動感を表現しており、ここでしか味わえない独自の歴史があります。' where id = 'zjNiSRedpJichWGqHWFGo';
update content_bodies set title = 'Matsuribito - Kanda Festival 2023', description = 'The Kanda Festival returns after four years! This revival showcases Japanese culture and the vibrant spirit of the Japanese people. It offers a unique historical experience that can only be found here.' where id = 's_P_fd7BD0Q3NBbGAf5jP';
update content_bodies set title = '神田祭 2023', description = '2023年に4年ぶりに開催された神田祭の3日間を収めた映像です。映像は複数の章に分かれており、オープニング、5月12日の氏子町会による神霊入れ、5月13日の町内渡御、5月14日の神輿渡御、そしてエンディングで構成されています。' where id = 'SvLnx_e82fegHDYCou3GJ';
update content_bodies set title = 'Kanda Festival 2023', description = 'This is a video documenting the Kanda Festival held in 2023, which took place after a four-year hiatus. The video is divided into several chapters: the opening segment, the ritual of placing the deity into the portable shrine on May 12, the neighborhood procession on May 13, and the portable shrine procession on May 14, concluding with an ending segment.' where id = '9iUNMPoK4htzvpeD-p977';
update content_bodies set title = 'ツアー3 東京／浅草', description = 'この映像は、プロデューサー兼監督の藤井きいちによって制作され、日本国際観光映像祭の日本部門と国際部門に入選しました。浅草寺、仲見世商店街、芝浦、東京ゲートブリッジなど、東京の象徴的な場所を紹介しています。尺は2分28秒で、2022年に制作されました。物語は、過去と未来が交差する東京の街を描き、アジアの入り口としての役割を強調しています。旅行中に感じた思い出や感情を大切にし、帰路につく際にそれらを忘れないように促しています。' where id = 'U8FZJ3BVjuiGeaR39WpfN';
update content_bodies set title = 'Tour 3 Tokyo / Asakusa', description = 'This film, produced and directed by Kiichi Fujii, was selected for both the Japanese and international categories of the Japan International Tourism Film Festival. The film showcases iconic locations in Tokyo, including Senso-ji Temple, Nakamise Shopping Street, Shibaura, and the Tokyo Gate Bridge. With a runtime of 2 minutes and 28 seconds, it was produced in 2022. The narrative presents a blend of the past and future in Tokyo, inviting viewers to explore the city as a gateway to Asia. It emphasizes the importance of memories and feelings experienced during the journey, encouraging viewers to cherish these moments as they return home.' where id = 'I71fDzslAcZkMSMTiwVXq';
update content_bodies set title = '❝奇跡の清流❞ 仁淀川の四季（ショートバージョン）', description = '「奇跡の清流」と称される仁淀川は、西日本最高峰の石鎚山から太平洋へ流れる一級河川です。日本一の水質を誇り、その美しい水の色は「仁淀ブルー」と呼ばれています。絶景の渓谷や神秘的な森、山里に住む人々の営みなど、日本の原風景が広がるエリアです。この動画はショートバージョンで、ロングバージョンはリンクからご覧いただけます。' where id = 'ybM8Rmu_5BLXMbtBYJDjW';
update content_bodies set title = 'Miraculous Clear Stream: The Four Seasons of Niyodo River (Short Version)', description = 'The Niyodo River, known as the ''Miraculous Clear Stream,'' flows from Mount Ishizuchi, the highest peak in western Japan, to the Pacific Ocean. It is said to have the best water quality in Japan, with its beautiful water color referred to as ''Niyodo Blue.'' The area features breathtaking gorges, mystical forests, and the lives of people in the mountain villages, showcasing Japan''s original landscapes. This video is a short version, and the long version can be viewed at the provided link.' where id = 'AvagM_JDHCX6YTsRbwFxH';
update content_bodies set title = '英虞湾(夕景)【ドローン撮影】(志摩市)｜観光三重｜三重県の観光・旅行情報', description = '英虞湾は、日本有数のリアス海岸の美しい景観を誇る真珠のふるさとです。数多くの岬や島々、浮かぶ真珠筏があり、特に夕暮れ時には周囲が黄金色に染まり、沈む夕日の美しさに心を奪われます。' where id = 'fBGG-DBQNFvsJXioJZDLD';
update content_bodies set title = 'Ago Bay (Sunset) [Drone Photography] (Shima City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Ago Bay, known as the home of pearls, boasts one of Japan''s most beautiful ria coastlines. The bay is adorned with numerous capes and islands, and the floating pearl rafts are captivating, especially at sunset when the area is bathed in a golden hue, showcasing the stunning beauty of the setting sun.' where id = '7Zk-763ZHI8J-FF14qlY8';
update content_bodies set title = '下風呂温泉郷　湯治のススメ', description = '湯治とは、宿に長期滞在し、温泉の効用で病気治療や療養を行う方法です。下風呂温泉の湯治では、異なる泉質を体験し、海沿いの宿ならではの豊かな食事を楽しむことで、心身ともに健康的な生活を送ります。この温泉は、霊場・恐山と同質の硫黄泉を持ち、古くから切り傷や打撲、神経痛、皮膚病に効果があるとされています。青森県下北郡風間浦村の下北ゆかい村は、観光や温泉、食材のプロモーションを行っており、昭和の雰囲気漂う下風呂温泉郷や新鮮な地元の海産物が魅力です。' where id = 'sPKNgMzQovXRfoza3CP-a';
update content_bodies set title = 'Shimo-Furo Onsen Village: A Recommendation for Healing', description = 'Toji, or hot spring therapy, involves long-term stays at an inn to utilize the healing properties of hot springs for treating illnesses. Shimo-Furo Onsen offers a unique experience with various mineral waters, complemented by rich coastal cuisine, promoting a healthy lifestyle for both body and mind. The onsen features sulfuric waters similar to those found at the sacred Mount Osore, often referred to as the ''ocean bath'' in contrast to the ''mountain bath.'' This revered hot spring is praised for its effectiveness against various ailments, including cuts, bruises, neuralgia, and skin diseases. The Shimokita Yukai Village promotes tourism, hot springs, and local cuisine in Kazamaura, Aomori Prefecture, showcasing the nostalgic charm of Shimo-Furo Onsen and the unique local seafood.' where id = 'OqJaLZ0ksyAR_N_ASEYS1';
update content_bodies set title = '【冬篇】下北ゆかい村 PR動画（青森県風間浦村）', description = '下風呂温泉は幾百年もの間、湯治場として親しまれてきました。津軽海峡を望む本州の北端を巡る旅情を体験し、硫黄の香りに包まれながら湯の街を歩き、新鮮な海の幸を楽しむことができます。「湯」と「海」で、身も心も解きほぐす「ゆかい村」。また食べたくなる海の幸、また会いたくなる温かな人々、また行きたくなる心のふるさとがここにあります。そんな「ゆかい」の村、風間浦村があなたを待っています。' where id = 'D0YbOu-xIPreO37mbVSx_';
update content_bodies set title = 'Winter Edition: Shimokita Yukai Village PR Video (Kazamaura, Aomori Prefecture)', description = 'Shimokita Yukai Village has been cherished as a hot spring resort for centuries. Experience the journey around the northern tip of Honshu, overlooking the Tsugaru Strait. Stroll through the hot spring town enveloped in the scent of sulfur and indulge in fresh seafood. ''Yukai Village'' offers a place to unwind both body and soul with its ''hot springs'' and ''sea.'' You will crave the fresh seafood, long to meet the warm-hearted locals, and yearn to return to this beloved hometown. Kazamaura Village, a place of ''yukai,'' is waiting for you.' where id = 'pwmuS6tqIhksgqdiJGBZ5';
update content_bodies set title = '三重県初上陸🚃！観光列車「はなあかり」が3日間限定で走行🛤', description = '2025年11月12日、26日、12月3日の3日間、観光列車「はなあかり」が三重県に初上陸しました。この列車は「地域の華を列車に集め、お客様と地域の縁を結ぶ」をコンセプトに、JR関西線で実証運行されます。みえ旅アンバサダーのキャスターマミが伊賀上野駅から乗車し、素敵な車内や車窓からの自然豊かな三重の景色をレポートしました。関駅で下車後は、関宿のおすすめモデルコースを紹介。訪れたスポットには、グルメのcafeウーノボーノやお土産の関見世吉右衛門、景観スポットの百六里庭・眺関亭があります。皆さんもJR関西線に乗って、魅力あふれる三重県を訪れてみてください。' where id = 'dxxOy-R7RnPOeMMeqRRgy';
update content_bodies set title = 'First Arrival in Mie Prefecture! Limited-Time Sightseeing Train ''Hanaakari'' Runs for Three Days', description = 'The sightseeing train ''Hanaakari'' made its debut in Mie Prefecture on November 12, 26, and December 3, 2025. This train operates under the concept of ''gathering the region''s flowers and connecting customers with the local community.'' The train runs on the JR Kansai Line. Mie Travel Ambassador, Caster Mami, boarded the train from Iga Ueno Station and reported on the beautiful interior and the rich natural scenery of Mie visible from the windows. After disembarking at Seki Station, she introduced a recommended model course in Seki-juku, including spots like cafe Uno Buono for gourmet food, Sekimise Kichiemon for souvenirs, and scenic spots like Hyakuroku Garden and Chokantei. Everyone is encouraged to take the JR Kansai Line and explore the attractions of Mie Prefecture.' where id = '110rxfAigZED213tJf61J';
update content_bodies set title = '【夏篇】下北ゆかい村 PR動画（青森県風間浦村）', description = '下風呂温泉は幾百年もの間、湯治場として親しまれてきました。津軽海峡を望む本州の北端を巡る旅情を感じながら、硫黄の香りに包まれた湯の街を歩き、新鮮な海の幸を楽しむことができます。「湯」と「海」で、心も体も解きほぐす「ゆかい村」。また食べたくなる海の幸、また会いたくなる温かな人々、また行きたくなる心のふるさとがここにあります。そんな「ゆかい」の村、風間浦村があなたを待っています。' where id = 'wyHuzCCVMc9kFL2QXBx29';
update content_bodies set title = 'Summer Edition: Shimokita Yukai Village PR Video (Kazamaura, Aomori Prefecture)', description = 'Shimokita Yukai Village has been cherished as a hot spring resort for centuries. Experience the journey around the northern tip of Honshu, overlooking the Tsugaru Strait. Stroll through the hot spring town enveloped in the scent of sulfur and indulge in fresh seafood. ''Yukai Village'' offers a place to unwind both body and soul with its ''hot springs'' and ''sea.'' You will crave the fresh seafood, long to meet the warm-hearted locals, and yearn to return to this beloved hometown. Kazamaura Village, a place of ''yukai,'' is waiting for you.' where id = 'i4H3abqG_y6CrBoc9-Mot';
update content_bodies set title = '伊賀の里モクモク手づくりファームの隠れた逸品！肉厚ジューシーな「原木椎茸」の摘み取り体験🍄🍂', description = 'モクモク手づくりファームでは、ソーセージやパンの手づくり体験教室、工房で作られたソーセージやパン、地ビールを楽しめるレストラン・カフェ、動物と触れ合える学習牧場など、多彩な施設が揃っています。その中でも、少し地味な存在のきのこ農園は、知る人ぞ知る穴場スポットです。この記事では、浜辺チーフが推奨する「原木椎茸」の摘み取り体験を紹介します。自分で収穫した原木椎茸を炭火で焼くと、驚くほど香り高く、噛むと旨味があふれ出すジューシーさが楽しめます。シリーズ「みえの推し活！」ならではの視点で、その魅力をお届けします。' where id = 'SOU0vtdgnSNGyK1wyWJp3';
update content_bodies set title = 'Hidden Gem of Iga''s Moku Moku Handmade Farm: Juicy ''Shiitake Mushrooms'' Picking Experience 🍄🍂', description = 'Moku Moku Handmade Farm offers a variety of enjoyable facilities, including hands-on workshops for making sausages and bread, a restaurant and café serving homemade sausages, bread, and local beer, as well as a learning farm where visitors can interact with animals. Among these attractions, the mushroom farm is a lesser-known gem. This article highlights the shiitake mushroom picking experience, passionately recommended by Chief Hamabe of Moku Moku. The freshly harvested shiitake mushrooms, grilled over charcoal, are incredibly aromatic and bursting with flavor, providing a unique culinary experience. Discover the charm of this activity through the ''Mie no Oshi Katsu!'' series perspective.' where id = '0aLtidYz2fjkHA4lejM6R';
update content_bodies set title = '伊勢・二見浦で長年愛される老舗餅屋が手がける天然水のかき氷をご紹介🍧', description = '三重県伊勢市の名物餅「お福餅」を味わえる甘味処が、2024年春に二見興玉神社へ続く夫婦岩表参道の賓日館隣にオープンしました。伝統のお福餅から新しいスイーツまで楽しめるほか、様々なお餅やあんみつ、ドリンクも揃っています。暑い季節のおすすめは、ふわふわ食感の天然水のかき氷で、自家製の濃厚抹茶ととろけるお餅が入った黒蜜きなこが楽しめます。この二種類は通年で味わえ、8月1日からは「季節の果実 みかん」が期間限定で販売される予定です。山梨南アルプスの貴重な天然氷を使用した絶品のかき氷です。' where id = 'uwafH5VdIZJiYKmDX26SD';
update content_bodies set title = 'Introducing Natural Water Shaved Ice from a Long-Standing Mochi Shop Loved for Years in Ise and Futamiura 🍧', description = 'A traditional sweet shop in Ise City, Mie Prefecture, known for its famous ''Ofuku Mochi,'' has opened next to Hinjitsukan along the path to Futami Okitama Shrine in spring 2024. Visitors can enjoy a variety of traditional and new sweets, including mochi, anmitsu, and drinks. A highlight during the hot season is the fluffy natural water shaved ice, featuring rich homemade matcha with anko sauce and black honey kinako with melting mochi. These two flavors are available year-round, while a seasonal mandarin flavor will be offered from August 1. The shaved ice is made using precious natural ice from Yamanashi''s Southern Alps, crafted by a long-established mochi shop. The shop is located at 568-1 Chaya, Futami-cho, Ise City, with operating hours from 9:00 AM to 5:00 PM (last order at 4:30 PM).' where id = 'cwqDsuU-Iy1ieJ0WlOZXk';
update content_bodies set title = '【８月３日までOPEN！】志摩市観光農園のひまわりを見に行こう🌻', description = '三重県志摩市の「道の駅伊勢志摩」に併設された志摩市観光農園のひまわりがオープンしました。2025年の開園期間は7月19日から8月3日までです。オープン初日に訪れたみえ旅アンバサダーの動画では、ひまわりの開花状況はまだ3割程度でしたが、月末には満開になる見込みです。2つのフォトスポットもあり、ひまわりと一緒に素敵な写真を撮ることができます。開園時間は9:00～17:00、入場料は300円（中学生以下は無料）です。駐車場は約160台分の無料スペースがあります。詳細は志摩市役所農林課（0599-44-0288）までお問い合わせください。' where id = '8UH6vtHxW4tuUBYfyAZM-';
update content_bodies set title = 'Visit the Sunflowers at Shima City Tourist Farm Until August 3rd! 🌻', description = 'The sunflower garden at Shima City Tourist Farm, located at the entrance of Shima City in Mie Prefecture, is now open for the season! The opening period for the sunflowers in 2025 is from July 19 (Saturday) to August 3 (Sunday). A video showcases the opening day visit by Mie Travel Ambassador @castermami, where only about 30% of the sunflowers were in bloom, suggesting they will be in full bloom by the end of the month. There are also two photo spots available, allowing visitors to capture beautiful summer memories with the sunflowers. The farm is open from 9:00 AM to 5:00 PM, with an entrance fee of 300 yen (free for middle school students and younger). Free parking is available for approximately 160 cars. For more information, contact the Shima City Agricultural and Forestry Division at 0599-44-0288.' where id = '02etsN94gZZbJF6Ez38LI';
update content_bodies set title = 'GENERATIONS小森隼が三重県の新たな魅力を巡る　便石山・尾鷲海鮮編', description = '三重県出身のGENERATIONS小森隼さんが、三重ならではの絶景や食、文化を楽しみながら、ふるさとの魅力を熱く語ります。世界遺産「熊野古道伊勢路」の近くにある便石山の山頂には「象の背」という絶景ポイントがあり、素晴らしい眺めを楽しんだ後は新鮮な海鮮を味わい、熊野古道の歴史を学びます。三重県の新たな魅力を求める旅は、ぜひ皆さんも体験してみてください！' where id = 'JajEzRJVUG4qNkTcKsONf';
update content_bodies set title = 'GENERATIONS'' Hayato Komori Explores the New Attractions of Mie Prefecture: Benishiyama and Owase Seafood', description = 'Hayato Komori from GENERATIONS, hailing from Mie Prefecture, enjoys the unique scenic views, food, and culture of his hometown, passionately sharing its charm. Near the World Heritage site ''Kumano Kodo Iseji,'' the summit of Benishiyama features a breathtaking viewpoint known as ''Elephant''s Back.'' After soaking in the stunning views, he indulges in fresh seafood and learns about the history of the Kumano Kodo. This journey to discover the new attractions of Mie Prefecture is one that everyone should experience!' where id = '5DMwoOb9znuwuDxDdOynH';
update content_bodies set title = 'ふるさと味工房アグリ', description = '玉城豚の特徴は、その鮮度の良さにあります。新鮮なため、臭みがなく、甘みのある脂身が際立っています。この魅力を最もシンプルに味わえる料理がしゃぶしゃぶであり、ジューシーで甘みのある玉城豚を贅沢に楽しむことができるおすすめの料理です。' where id = 'Y54jcQ8HlsvbZNgrslxdW';
update content_bodies set title = 'Furusato Taste Workshop Agri', description = 'The standout feature of Tamaki pork is its exceptional freshness. This freshness results in a lack of unpleasant odors and a characteristic sweet fat. One of the best ways to enjoy this charm is through shabu-shabu, where you can indulge in the juicy and sweet Tamaki pork in a luxurious manner.' where id = 'OaXUpRMyoLVSsJSvIafiZ';
update content_bodies set title = '鳥羽水族館🐠飼育係「森滝さん」イチ推しの「へんな生きもの」に会いに行こう🪼！', description = '今年、開館70週年を迎えた鳥羽水族館は、日本で唯一飼育されているラッコやジュゴン、アシカやセイウチのショーが人気です。しかし、鳥羽水族館の魅力はそれだけではありません。実は、飼育種類数が「日本一」を誇る水族館なのです。飼育係の森滝さんが案内する「へんな生きもの研究所」は、特にディープなエリアで、鳥羽水族館の奥深い世界を体験できる貴重な機会です。' where id = 'kgUYasXQl24tHV4leIf9f';
update content_bodies set title = 'Visit the ''Weird Creatures'' at Toba Aquarium with Caretaker Moritaki!', description = 'Toba Aquarium, celebrating its 70th anniversary this year, is home to Japan''s only sea otters, dugongs, and popular shows featuring sea lions and walruses. However, the aquarium''s charm extends beyond these attractions. It boasts the highest number of species in Japan. Caretaker Moritaki will guide you through the ''Weird Creatures Research Institute,'' one of the most intriguing areas, allowing you to explore the deep and fascinating world of Toba Aquarium.' where id = 'a_yxasqlEsQunDk0N8TRv';
update content_bodies set title = '暑い夏にひんやり絶品！期間限定でお茶のかき氷が登場🍵！', description = '三重県松阪市の「茶工房かはだ」では、7月から9月の期間限定でお茶のかき氷が楽しめます。この深蒸し茶専門店は、地元のお茶農家が運営しており、緑茶氷やほうじ茶氷などのユニークなフレーバーを提供しています。かき氷には、濃厚な自家製お茶シロップ、甘さ控えめの手作りあん、ミルク、白玉だんごがトッピングされており、夏にぴったりの絶品です。営業時間は物販が9:00～17:30、喫茶が10:00～16:00で、水曜日は定休日です。詳細は059-46-8100まで。' where id = 'TuQBbTnh9CFAsMCieyAjd';
update content_bodies set title = 'Cool and Delicious! Limited-Time Matcha Shaved Ice Available This Summer 🍵!', description = 'From July to September, ''Tea Workshop Kahada'' in Matsusaka City, Mie Prefecture, offers a special matcha shaved ice treat. This deep-steamed tea specialty shop, run by a local tea farmer, features unique flavors like green tea and hojicha. The shaved ice is topped with rich homemade tea syrup, lightly sweetened handmade red bean paste, milk, and shiratama dumplings, making it a must-try for summer. The shop is open from 9:00 AM to 5:30 PM for retail and 10:00 AM to 4:00 PM for café services, closed on Wednesdays. For more information, call 059-46-8100.' where id = 'rajtsjnZXCINrcFQaNyTd';
update content_bodies set title = '国の天然記念物指定💜全国的にも珍しい斎宮のハナショウブ群落', description = '三重県明和町には、国の天然記念物に指定された全国的にも珍しいハナショウブの群落があります。野生のハナショウブは「ノハナショウブ」と呼ばれ、栽培されているハナショウブの原種です。見頃は6月上旬のノハナショウブと、6月下旬から7月のノカンゾウです。広がる可憐なハナショウブを楽しむことができます。場所は多気郡明和町斎宮蛭ノ沢1817で、駐車場は3台程度。詳細は明和町文化観光課にお問い合わせください。' where id = 'yjKhZQGg_50bv3GC9HTIU';
update content_bodies set title = 'National Natural Monument: Rare Iris Flowers in Saiku', description = 'In Meiwa Town, Mie Prefecture, there is a rare cluster of wild iris flowers, designated as a national natural monument. Known scientifically as ''Nohanasyo-bu'', these wild irises are the original species from which cultivated varieties are derived. The best time to see the Nohanasyo-bu is early June, while the No-Kanzou blooms from late June to July. Visitors are encouraged to enjoy the delicate beauty of these irises in the expansive plains. The location is at 1817 Hironosawa, Saiku, Taki District, with limited parking available. For more information, contact the Meiwa Town Cultural Tourism Division.' where id = 'oqa0AWDVI9VKZW_98XjcC';
update content_bodies set title = '夏休み前に要チェック！「おやつタウン」2025年最新情報📢', description = '夏休み前に、ベビースターラーメンのテーマパーク「おやつタウン」の2025年春の最新情報をチェックすることが重要です。新しいアトラクションやグルメ情報、期間限定の「泡あわ噴水ウォーターショー」が登場します。また、ベビースターを使った“つくる”体験もあり、事前予約が必要です。観光三重のレポートでは、最新情報やスタッフおすすめの人気お土産が紹介されています。「おやつタウン」は三重県に位置し、さまざまなチケットオプションが用意されています。詳細は公式サイトをご覧ください。' where id = '92Oi2CJzoODAuljPxdYPD';
update content_bodies set title = 'Check Out the Latest Information on ''Oyatsu Town'' Before Summer Vacation 2025! 📢', description = 'Before summer vacation, it''s essential to check out the latest information on ''Oyatsu Town,'' the theme park dedicated to Baby Star Ramen, set to open in spring 2025. The park will feature new attractions, gourmet offerings, and a limited-time ''Bubble Fountain Water Show.'' Visitors can also enjoy a hands-on experience of creating with Baby Star, which requires advance reservations. The report from Kankomie provides insights into the latest updates and popular souvenirs recommended by the staff. Oyatsu Town is located in Mie Prefecture, with various ticket options available. For more details, visit the official website.' where id = 'HQqX21TMYIUp5rQyJHZ6H';
update content_bodies set title = '三重のうどん・そば・ラーメンを食べて楽しく巡ろう🍜御“麺”印巡りが6月1日スタート', description = '三重県内のうどん、そば、ラーメンを楽しむ「御麺印（ごめんいん）巡り」が2025年6月1日から始まります。このイベントでは、参加者が「🍜」とコメントすることで参加意欲を示すことができます。紹介されている店舗の一つは、津市にある「うどん・そば処 きのさき」で、平日は11:00～14:00、土日は11:00～14:00と17:00～20:00に営業しています。売り切れ次第終了となり、定休日は毎週月曜と第1・第3・第5火曜です。詳細は観光三重トピックスでの発表をお楽しみに。投稿が面白いと思ったら、ぜひ「いいね＆保存」をお願いします！' where id = 'NTDWeKVLfRYLRwtB1QOzO';
update content_bodies set title = 'Enjoy a Fun Tour of Udon, Soba, and Ramen in Mie: ''Gomen-in'' Tour Starts June 1', description = 'Starting June 1, 2025, Mie Prefecture will launch the ''Gomen-in'' tour, inviting visitors to enjoy a delightful journey through local udon, soba, and ramen shops. The tour encourages participants to comment ''🍜'' when they feel inspired to join. One of the featured locations is ''Udon and Soba Kinosaki'' in Tsu City, which operates on weekdays from 11:00 AM to 2:00 PM and on weekends from 11:00 AM to 2:00 PM and 5:00 PM to 8:00 PM, closing when sold out. The restaurant is closed on Mondays and the first, third, and fifth Tuesdays of the month. For more details, stay tuned for updates from the Mie Tourism Topics. If you find this post interesting, please like and save it!' where id = 'OBLkEfN9YPZbFER-Fvd8q';
update content_bodies set title = '「観光三重おすすめスポットでみえ旅アンバサダーと一緒に写活したい！」三重であなたがしたいことをかなえます！3組目当選者の夢をかなえる“みえ旅”レポート', description = '三重県には食、自然、歴史、文化、絶景、テーマパークなど、旅行やお出かけに適した多様な観光スポットがあります。2024年秋、これらの観光スポットで実現したい夢を募集したところ、3組の当選者が決まりました。応募者のアイデアをもとに、三重県観光連盟が体験や旅行企画を作成し、プレゼントします。3組目の当選者は、三重県内から応募した20代の女性「みみみ。」ちゃんで、カメラ愛好家の友人に影響されて1年前にカメラを手に入れました。観光三重を普段からチェックしており、素敵な写真をたくさん撮りたいという夢を持っています。みえ旅アンバサダーのキャスターマミさんとさんぺいさんの案内で、その夢を実現していきます。' where id = 'dCip5k-3OvfXEuzSlYFqv';
update content_bodies set title = 'Experience Photography with Mie Travel Ambassadors at Recommended Spots in Mie!', description = 'Mie Prefecture offers a variety of attractions suitable for travel and outings, including food, nature, history, culture, stunning views, and theme parks. In the fall of 2024, a call for dreams to be fulfilled at these tourist spots was made, resulting in three lucky winners. Based on the applicants'' ideas, the Mie Tourism Federation created travel experiences as gifts. The third winner, a woman in her 20s nicknamed ''Mimimi.'', was inspired by a photography-loving friend and acquired a camera a year ago. She regularly checks Mie tourism and dreams of capturing beautiful photos like those featured on the site. With the guidance of Mie Travel Ambassadors, Castor Mami and Sanpei, her dream will come true.' where id = 'M_5c9Umaeg7CSmju0DuzP';
update content_bodies set title = '三重であなたがしたいことをかなえます！レポート記事＆動画配信中！', description = '三重県には食・自然・歴史・文化・絶景・テーマパークなど、旅やお出かけにふさわしい観光スポットが豊富にあります。2024年秋、三重県の観光スポットでかなえたい夢を募集し、3組の当選者が選ばれました。応募者のアイデアをもとに、三重県観光連盟が体験・旅行企画を作成し、プレゼントしました。当選者の夢は、1組目が釣りをして鳥羽水族館の仲間にエサやり、2組目が伊勢志摩・熊野のパワーでプロポーズ、3組目が観光三重のおすすめスポットでみえ旅アンバサダーと写活することです。これらの体験レポート記事と動画は、観光三重のホームページでご覧いただけます。' where id = 'Jf1I5xB8Q0Z9E6JhaQPCh';
update content_bodies set title = 'Fulfill Your Wishes in Mie! Report Articles & Videos Now Available!', description = 'Mie Prefecture offers a variety of attractions suitable for travel and outings, including food, nature, history, culture, stunning views, and theme parks. In the fall of 2024, we invited people to share their dreams related to Mie''s tourist spots, and three winners were selected! Based on the ideas submitted, the Mie Tourism Federation created travel experiences as gifts. The dreams that were fulfilled include: 1) Fishing and feeding the creatures at Toba Aquarium, 2) Proposing to a girlfriend with the power of Ise-Shima and Kumano, and 3) Taking photos with the Mie Travel Ambassador at recommended spots. You can view the reports and videos of these experiences on the Mie Tourism website.' where id = 'gPMOV3c1QbIQua6qLUTxp';
update content_bodies set title = '「伊勢志摩・熊野のパワーをもらって彼女にプロポーズしたい！」三重であなたがしたいことをかなえます！2組目当選者の夢をかなえる“みえ旅”レポート', description = '三重県には、食、自然、歴史、文化、絶景、テーマパークなど、旅やお出かけに適した多様な観光スポットがあります。2024年秋、これらの観光地で実現したい夢を募集したところ、3組の当選者が選ばれました。応募者のアイデアをもとに、三重県観光連盟が体験や旅行企画を作成し、プレゼントしました。2組目の当選者は神奈川県から応募した航さんで、彼女の唯さんと共に三重県を訪れました。歴史ある伊勢志摩と熊野のパワーを受けて、素敵なプロポーズをサポートする1泊2日の旅が行われ、絶景やパワースポット、志摩地中海村でのサプライズプロポーズプランが用意されました。' where id = 'FYRQpL4JW58akZzlqgikr';
update content_bodies set title = 'I Want to Propose to My Girlfriend with the Power of Ise-Shima and Kumano! Making Your Dreams Come True in Mie! Report on the Second Winner of the ''Mie Travel'' Project', description = 'Mie Prefecture offers a variety of attractions suitable for travel and outings, including food, nature, history, culture, stunning views, and theme parks. In the fall of 2024, a call for dreams to be fulfilled at these tourist spots in Mie was made, resulting in three winners. Based on the applicants'' ideas, the Mie Tourism Federation created travel experiences as gifts. The second winner, a man named Kō from Kanagawa Prefecture, visited Mie with his girlfriend, Yui, who was experiencing it for the first time. Their journey included a one-night, two-day trip to receive the power of the historic Ise-Shima and Kumano, featuring breathtaking views and a surprise proposal plan at Shima Mediterranean Village.' where id = 'qn8MODbVhZ9EMk0YdwVPU';
update content_bodies set title = '「釣りをして、鳥羽水族館の仲間たちにエサやりしたい！」三重であなたがしたいことをかなえます！', description = '三重県には食・自然・歴史・文化・絶景・テーマパークなど、旅やお出かけにふさわしい観光スポットが豊富にあります。2024年秋、三重県観光連盟は、これらの観光スポットでかなえたい夢を募集し、3組の当選者が選ばれました。1組目の当選者は、釣りと水族館巡りが趣味のはまださんファミリー。パパ、ママ、3歳のすみれちゃん、0歳7ヶ月のけい君の4人家族です。彼らは鳥羽の離島で釣りやワークショップを体験し、鳥羽水族館の「うら側探検隊！」に参加しました。大好きな海の仲間たちにエサやりはできたのでしょうか。夢をかなえた一日をレポートします。' where id = 'ApIWFiXSx4fcO8NBA8251';
update content_bodies set title = 'Fishing and Feeding Friends at Toba Aquarium! Fulfilling Your Dreams in Mie!', description = 'Mie Prefecture offers a variety of attractions suitable for travel and outings, including food, nature, history, culture, stunning views, and theme parks. In the fall of 2024, the Mie Prefectural Tourism Federation invited people to submit their dreams to be fulfilled at these attractions, resulting in three lucky winners. The first winner is the energetic Hamada family, who enjoy fishing and visiting aquariums. The family includes a fishing-loving dad, a cheerful mom, their 3-year-old daughter Sumire, who adores the creatures at Toba Aquarium, and their 7-month-old son Kei. They experienced fishing and workshops on a remote island in Toba and participated in the aquarium''s ''Behind the Scenes Exploration Team.'' Did they get to feed their beloved sea friends? This report covers their dream-fulfilling day.' where id = 'u72xnX189vJVy_YPeKnO6';
update content_bodies set title = 'ありすえ', description = 'ありすえでは、伊勢まぐろを刺身、血合のフライ、赤身のユッケ、心臓の佃煮など、さまざまな食べ方で楽しむことができます。特に、心臓のような地元ならではの珍しい食材を味わえるのは嬉しいポイントです。南伊勢ブランドの伊勢まぐろの多様な食感や味わいを堪能できる貴重な体験です。' where id = 'QX9MD3EX5pGrWVApRR47h';
update content_bodies set title = 'Arisue', description = 'At Arisue, you can enjoy the unique flavors and textures of Ise tuna through various dishes such as sashimi, fried bloodline, red meat yukhoe, and heart tsukudani. It''s a delight to encounter local specialties like the heart, which are not commonly available elsewhere.' where id = 'V_eJWN_4THvuyYgb0-Vr6';
update content_bodies set title = '【桜スポット2選🌸】早咲きの桜、枝垂れ桜スポットをご紹介', description = '奥伊勢エリア大紀町の早咲きの桜と枝垂れ桜のスポットを2つ紹介します。これらの桜は、ソメイヨシノより約1週間早く、3月下旬に見頃を迎えます。最初のスポットは笠木渓谷の忠五郎桜で、赤いレトロなアーチ橋が魅力的です。三重県に位置し、駐車場は約20台分あり、紀勢大内山ICから車で10分の距離です。次のスポットは大紀町役場柏崎支所の巨大な枝垂れ桜で、駐車場は約10台分あり、同じく紀勢大内山ICから車で5分です。この投稿が面白いと思ったら、ぜひ「いいね＆保存」をお願いします！' where id = 'lDO_PwG7MbwjkUlziY8E2';
update content_bodies set title = 'Two Cherry Blossom Spots 🌸: Early Blooming and Weeping Cherry Trees', description = 'This post introduces two cherry blossom spots in the Oku-Ise area of Daiki Town, featuring early blooming cherry trees and weeping cherry trees. The blossoms typically reach their peak around late March, about a week earlier than the famous Somei Yoshino variety. The first spot is Chugo Sakura at Kasakigawa Valley, known for its charming red retro arch bridge, located in Mie Prefecture. It has parking for about 20 cars and is a 10-minute drive from Kisei Ouchiyama IC. The second spot is a massive weeping cherry tree at the Daiki Town Hall Kashiwazaki Branch, with parking for about 10 cars, just a 5-minute drive from the same IC. If you find this post interesting, please like and save it!' where id = 'o3-xJ32p9rnhFI0rsX7kO';
update content_bodies set title = '魅惑のお花リレー🌼この春行きたいNo.1スポットをご紹介✨', description = 'この記事では、なばなの里での魅惑のお花リレーを紹介し、春のNo.1スポットを特集しています。2月の梅から始まり、桜、チューリップ、ネモフィラと続くお花リレー。4月5日現在、チューリップが満開を迎え、桜との競演が楽しめます。チューリップの見頃は4月中旬まで続くため、この絶景を見逃さないようにしましょう。また、ネモフィラの開花も始まっており、色とりどりのチューリップ畑が次第にネモフィラブルーに変わる幻想的な景色が楽しめます。チューリップまつりは3月中旬から4月中旬まで開催され、現在の開花情報は満開です。訪れる際の場所、営業時間、入園料、アクセス情報も記載されています。' where id = 'fseQD54xMACRqI43OEJne';
update content_bodies set title = 'Charming Flower Relay 🌼 Introducing the No.1 Spot to Visit This Spring ✨', description = 'This article highlights the enchanting flower relay at Nabana no Sato, showcasing the top spring destination. Starting with plum blossoms in February, the relay continues with cherry blossoms, tulips, and nemophila. As of April 5, the tulips are in full bloom, providing a stunning view alongside the cherry blossoms. The tulip season lasts until mid-April, so visitors are encouraged not to miss this breathtaking sight. Additionally, the nemophila flowers are beginning to bloom, promising a beautiful transition from the colorful tulip fields to a sea of nemophila blue. The Tulip Festival runs from mid-March to mid-April, with current blooming information indicating full bloom. The location, hours, entrance fee, and access details are provided for visitors planning their trip.' where id = 'fLhtBe6f5NC-yO4B7tuPV';
update content_bodies set title = '三重の花 ～ 夏 ～', description = 'この文章では、三重県の夏の花の名所を紹介しています。具体的には、津市のかざはやの里の紫陽花、伊賀市のメナード青山リゾートハーブガーデンのカモミール、志摩市観光農園の向日葵の3つの場所が挙げられています。また、三重県のあじさいとひまわりの名所特集が「観光三重」ウェブサイトに掲載されていることも紹介されています。' where id = 'm1LMXZ01YNnaeBODOzF-m';
update content_bodies set title = 'Flowers of Mie - Summer', description = 'This text highlights summer flower spots in Mie Prefecture, Japan. It mentions three specific locations: the hydrangeas at Kazahaya no Sato in Tsu City, chamomile at Menard Aoyama Resort Herb Garden in Iga City, and sunflowers at Shima City Tourist Farm. Additionally, it points to the ''Kankomie'' website, which features special articles on hydrangea and sunflower spots in Mie Prefecture.' where id = 'HYs-mkMKBf1nG1wzBJGwI';
update content_bodies set title = '三重の花 ～ 春 ～', description = 'この文章では、三重県の春の花々を紹介しています。鳥羽市の城山公園の桜、大紀町の野原農村公園の藤、桑名市のなばなの里のチューリップとネモフィラ、美杉町の三多気の桜（ヤマザクラ）とミツマタ群生地のミツマタなど、美しい花が咲く名所が挙げられています。また、「観光三重」ウェブサイトで、桜、藤、チューリップ、ネモフィラ、早春のミツマタスポットに関する特集記事が公開されていることも言及されています。' where id = 'rWqsOljV4Xa4BI71Q4PXE';
update content_bodies set title = 'Flowers of Mie - Spring', description = 'This text introduces various spring flowers in Mie Prefecture, Japan. It highlights several locations known for their beautiful blooms, including cherry blossoms at Shiroyama Park in Toba City, wisteria at Nohara Rural Park in Daiki Town, tulips and nemophila at Nabana no Sato in Kuwana City, and yamazakura cherry blossoms and mitsumata at Santaki in Misugi Town. The text also mentions a collection of articles available on the ''Kankomie'' website, featuring special highlights on cherry blossoms, wisteria, tulips, nemophila, and early spring mitsumata spots in northern and central Mie.' where id = 'dh5CDsAd3rWjST4fO35hp';
update content_bodies set title = '三重の花 ～ 秋・冬 ～', description = 'この文章では、三重県の秋・冬の花の名所を紹介しています。具体的には、芸濃町の北神山花街道の彼岸花、桑名市のなばなの里のベコニアガーデン、名張市の積田神社と松阪市の泰運寺の紅葉、笠松町の笠松河津桜ロードの河津桜、鈴鹿市の鈴鹿の森庭園のしだれ梅が挙げられています。また、三重県の観光サイトでは、これらの季節の名所に関する特集ページへのリンクも提供されています。' where id = 'z8b-SkLVdJiYUO-CuSZnv';
update content_bodies set title = 'Flowers of Mie - Autumn and Winter', description = 'This text highlights various flower viewing spots in Mie Prefecture during the autumn and winter seasons. It mentions specific locations such as the Higanbana (cluster amaryllis) at Kitakami Mountain Flower Road in Geino Town, the Begonia Garden at Nabana no Sato in Kuwana City, and the autumn leaves at Sekita Shrine in Nabari City and Taiunji Temple in Matsusaka City. Additionally, it features the Kawazu cherry blossoms along the Kasamatsu Kawazu Sakura Road in Kasamatsu Town and the weeping plums at Suzuka no Mori Garden in Suzuka City. The text also provides links to special features on the Mie tourism website for more information on these seasonal attractions.' where id = '3uiGFEYzjiQKbb-LwoLZH';
update content_bodies set title = '三重の花 ～ 夏 ～', description = 'この文章では、三重県の夏の花の名所を紹介しています。具体的には、津市のかざはやの里の紫陽花、伊賀市のメナード青山リゾートハーブガーデンのカモミール、志摩市観光農園の向日葵の三つの場所が挙げられています。また、三重県のあじさいやひまわりの名所特集が「観光三重」ウェブサイトに掲載されていることも紹介されています。' where id = 'bp2e-4vUbVqrE8A3SpgNQ';
update content_bodies set title = 'Flowers of Mie - Summer', description = 'This text highlights summer flower spots in Mie Prefecture, Japan. It mentions three specific locations: the hydrangeas at Kazahaya no Sato in Tsu City, chamomile at Menard Aoyama Resort Herb Garden in Iga City, and sunflowers at Shima City Tourist Farm. Additionally, it points to the ''Kankomie'' website, which features special articles on hydrangea and sunflower spots in Mie Prefecture.' where id = 'EOztM18VAe31HhIrnRbib';
update content_bodies set title = '三重の花 ～ 春 ～', description = 'この動画では、三重県の春の花々を紹介しています。オープニングの後、鳥羽市の城山公園の桜、大紀町の野原農村公園の藤、桑名市のなばなの里のチューリップとネモフィラ、美杉町の三多気の桜（ヤマザクラ）、そして美杉町のミツマタ群生地が登場します。さらに、観光三重のウェブサイトでは、桜、藤、チューリップ、ネモフィラ、早春のミツマタスポットに関する特集ページが公開されています。' where id = 'U9XBpQGIUdw5nJVGQQD89';
update content_bodies set title = 'Flowers of Mie - Spring', description = 'This video showcases various spring flowers in Mie Prefecture, Japan. It begins with an opening segment and then features several locations: cherry blossoms at Shiroyama Park in Toba City, wisteria at Nohara Rural Park in Daiki Town, tulips and nemophila at Nabana no Sato in Kuwana City, and yamazakura cherry blossoms at Santaki in Misugi Town. Additionally, it highlights a cluster of mitsumata in Misugi. For more information, the ''Kankomie'' website offers dedicated pages on cherry blossoms, wisteria, tulips, nemophila, and early spring mitsumata spots in northern and central Mie.' where id = 'C2zV1NJ_Pcg-sptJWHIBu';
update content_bodies set title = '三重の花 ～ 四季折々の美を巡る旅 ～', description = 'この旅行ガイドは、三重県の四季折々の花の名所を紹介しています。津市のかざはやの里では紫陽花や藤が楽しめ、鳥羽市の城山公園では桜が見られます。芸濃町の北神山花街道では彼岸花、名張市の積田神社では紅葉が美しいです。また、桑名市のなばなの里ではベコニアガーデンやチューリップが、笠松町の河津桜ロードでは河津桜が楽しめます。美杉町のミツマタ群生地や、伊賀市のメナード青山リゾートのカモミール、鈴鹿市のしだれ梅、志摩市の向日葵など、様々な花が紹介されています。最後に、季節ごとの花の名所が「観光三重」ウェブサイトで紹介されていることが触れられています。' where id = 'rNmrmK18G8T25GbLeA9UQ';
update content_bodies set title = 'Mie Flowers: A Journey Through Seasonal Beauty', description = 'This travel guide highlights various seasonal flower spots in Mie Prefecture, Japan. It features locations such as Kaza-haya no Sato in Tsu City, known for hydrangeas and wisteria, and Shiroyama Park in Toba City, famous for cherry blossoms. Other notable sites include the Higanbana at Kitakami Flower Road in Geino Town, autumn leaves at Sekita Shrine in Nabari City, and the Begonia Garden at Nabana no Sato in Kuwana City. The guide also mentions the Kawazu cherry blossoms along the Kasamatsu Kawazu Sakura Road, Mitsumata in Misugi Town, and various other flowers like chamomile and tulips in Iga City and Kuwana City, respectively. The journey concludes with a mention of seasonal flower attractions available on the ''Kankou Mie'' website.' where id = 'nkgelnViH7VUk95-i33xs';
update content_bodies set title = '大地のパワーみなぎる「owase岩ヨガ体験」', description = '「大地のパワーみなぎるowase岩ヨガ体験」は、自然と一体になる特別な体験で、1日1組限定です。運動が苦手な方や自然の中でリフレッシュしたい方に最適で、地元の健康ウォーキングインストラクターが八畳岩まで案内します。初心者でも安心のゆっくりしたペースで、片道約30分のトレッキングを楽しんだ後、巨岩の上でプライベート岩ヨガを体験します。リラックスを目的とした簡単なポーズを教えてくれる素敵なヨガインストラクターがいます。ヨガの後は、天狗倉山の麓にある霊場「岩屋堂」で本尊と三十三体の観音様にお参りします。地元ガイドとの会話も魅力的です。料金はおひとり¥6,800で、集合場所はJR尾鷲駅です。名古屋からのアクセスも便利です。' where id = 'uz2LzykLTMm8MB05o-k1S';
update content_bodies set title = 'Experience the Power of the Earth with ''Owase Rock Yoga''', description = 'The ''Owase Rock Yoga Experience'' offers a unique opportunity to connect with nature, limited to one group per day. Ideal for those who want to enjoy an active getaway or refresh in nature, this experience includes a guided health walk by a local therapist to the Yajo Rock, featuring a gentle 30-minute trek. Participants can enjoy private rock yoga on the giant boulder, led by a friendly local yoga instructor who teaches simple poses aimed at relaxation. After yoga, attendees can visit the sacred site ''Iwayado'' at the foot of Tengu Mountain to pay respects to the main deity and thirty-three Kannon statues. Engaging conversations with local guides and yoga instructors enhance the experience. The cost is ¥6,800 per person, with the meeting point at Owase Station. Access is convenient from Nagoya by train or car.' where id = 'exdxepxbCwldbBh9U9kix';
update content_bodies set title = 'VISON発着！幻の「特産 松阪牛」スキヤキサイクリング', description = 'このサイクリングプログラムはホテルヴィソンから出発し、宿泊者におすすめです。オシャレな電動自転車で楽に坂道を走り、cazacleのガイドが同行します。すき焼きに使う新鮮な野菜はマルシェヴィソンで調達し、多気町の美しい里山を自転車で駆け抜けます。特産松阪牛の畜産農家が営む「cafeまつもと」で、流通がわずか4％の幻の松阪牛をすき焼きで味わい、生産者から和牛の解説を受けます。食事後はサイクリングせず、車でヴィソンへ送迎されます。料金はおひとり¥16,500で、集合場所は三重県のホテルヴィソンです。' where id = 'pl6gDo9PUDVyNpQ_yUdIj';
update content_bodies set title = 'VISON Departure! The Illusive ''Special Matsusaka Beef'' Sukiyaki Cycling', description = 'This cycling program starts from Hotel VISON and is recommended for guests staying there. Participants will enjoy an easy ride on stylish electric bicycles, guided by cazacle cycling tours. Fresh vegetables for the sukiyaki will be sourced from the VISON market. The route takes cyclists through the scenic rural landscapes of Taki Town, leading to ''Cafe Matsumoto,'' run by a Matsusaka beef farmer. Participants will savor the rare ''Special Matsusaka Beef,'' which only 4% of the market distributes, prepared as sukiyaki, while learning about this premium wagyu from the producer. After the meal, guests will be transported back to VISON by car instead of cycling. The program costs ¥16,500 per person, and the meeting point is Hotel VISON in Mie Prefecture.' where id = 'E9S9ZTqzBW8fF-tUP4ERW';
update content_bodies set title = '興奮する関西のダイジェスト', description = '関西は、日本の精神性と文化を深く広く体験できる場所です。1800年以上前の古代文明から、修験道や禅、京都を代表する華やかな平安貴族文化、さらには城や武士道、忍者に至るまで、関西は日本文化の全ての側面を体現しています。' where id = 'ujQyJpiXcWzsqXWGkfI8T';
update content_bodies set title = 'THE EXCITING KANSAI, Digest', description = 'Kansai is a region rich in Japanese spirituality and culture, offering a deep exploration of its historical and cultural aspects. With a civilization that dates back over 1,800 years, Kansai showcases various cultural elements, including Shugendo, Zen, and the opulent Heian aristocratic culture epitomized by Kyoto. Additionally, it is home to significant historical sites such as castles, and embodies the traditions of bushido and ninja, making it a comprehensive representation of Japanese culture.' where id = 'Nqf6hARdgBexnlFGytQEZ';
update content_bodies set title = '民宿 勇助（ゆうすけ）【五箇山】', description = '民宿 勇助は、富山県南砺市の五箇山に位置しています。住所は、富山県南砺市相倉591、郵便番号は939-1915です。お問い合わせは、電話番号0763-66-2555までどうぞ。詳細は公式ウェブサイト（https://yusuke-gokayama.com/）をご覧ください。' where id = 'pNKg6OTP1yYnvVFao6obH';
update content_bodies set title = 'Yusuke Inn (Yusuke) - Gokayama', description = 'Yusuke Inn is located in Gokayama, Toyama Prefecture, Japan. The address is 591 Aikura, Nanto City, Toyama 939-1915. For inquiries, you can reach them at 0763-66-2555. More information can be found on their website: https://yusuke-gokayama.com/' where id = 'eFfdBoeyaFMNRQMVrz12Q';
update content_bodies set title = '鳥羽・白瀧の森で体験できる「かまど焚きごはん＆食養生」', description = '新鮮な海の幸を味わい、心と体を整える時間を求める方に最適なのが、鳥羽・白瀧の森での「かまど焚きごはん＆食養生」の体験です。かつて修験者が修行した神聖な森にある古民家で、牡蠣や伊勢海老、あおさ、わかめなどの旬の食材を楽しみながら、体を内側から整えるひとときを過ごします。東洋医学の知恵である「食養生」を学び、心と体をリセットする贅沢な時間を体験できます。プログラムには、かまど焚き体験や食事、食養生ワークショップ、エクササイズが含まれています。料金はおひとり¥6,800で、二人から申し込むことができます。集合場所は白瀧大明神駐車場で、近鉄「船津駅」から徒歩約10分、伊勢自動車道「鳥羽IC」から約15分の距離です。' where id = '3UnC7fYsWTImHDEIw_m-x';
update content_bodies set title = 'Experience ''Kama-do Cooked Rice & Dietary Therapy'' in Toba''s Shirataki Forest', description = 'If you''re looking to savor fresh seafood and take time to rejuvenate your mind and body, the ''Kama-do Cooked Rice & Dietary Therapy'' experience in Toba''s Shirataki Forest is perfect for you. Set in a sacred forest where ascetics once trained, this experience allows you to enjoy seasonal ingredients from Toba, such as oysters, Ise lobster, and seaweed, while focusing on inner wellness. You will learn about the Eastern medical wisdom of dietary therapy and spend a luxurious time resetting your mind and body. The program includes a cooking experience, meals, and workshops on dietary therapy and exercises. The cost is ¥6,800 per person, with a minimum of two participants. The meeting point is at Shirataki Daimyojin parking lot, about a 10-minute walk from Kintetsu Funatsu Station or a 15-minute drive from Toba IC. This initiative is part of ''Mie no Imakoko Tabi,'' which offers unique experiences in Mie.' where id = 'GFR7hEGnYVqdXz1SYKY53';
update content_bodies set title = '御在所岳(紅葉)　【ドローン撮影】(菰野町)｜観光三重｜三重県の観光・旅行情報', description = '御在所岳は鈴鹿山脈の主峰で、標高1,212mの山です。山麓には湯の山温泉があり、世界的に有名なロープウエイが山頂へと通じており、素晴らしい空中散歩を楽しむことができます。紅葉は10月中旬ごろから山頂で始まり、中腹を経て、約1ヶ月かけて麓の湯の山温泉まで降りていきます。' where id = 'K5NuUznJRnprBC3cnqaJQ';
update content_bodies set title = 'Gozaisho Mountain (Autumn Leaves) - Drone Photography (Komono Town) | Tourism Mie | Mie Prefecture Travel Information', description = 'Gozaisho Mountain, the main peak of the Suzuka Mountains, stands at an elevation of 1,212 meters. At the foot of the mountain lies Yunoyama Onsen, and a world-class ropeway connects to the summit, offering a wonderful aerial experience. The autumn leaves begin to change color around mid-October at the summit, gradually descending to the mid-slope and finally to Yunoyama Onsen over the course of about a month.' where id = 'e5aHLfcQEEBBJ3tJ3ALfs';
update content_bodies set title = '3.1ニューオープン！「白山ストロベリーファーム」', description = '白山ストロベリーファームが3月1日にオープンしました。三重県でのみ栽培されている希少ないちご「うた乃」を使ったいちご狩りが楽しめます。食べ放題と量り売りの両方があり、特に甘い苺は他の品種には戻れなくなるかもしれません。土日祝日のみ営業で、3部制の時間帯が設定されています。食べ放題は40分制で、料金は大人2800円、小人2400円、未就学児は無料です。予約は電話で受け付けており、入園時にはシューズカバーの着用が必要です。また、2025年3月にはキャンプ場もオープン予定です。詳細は公式Instagramや観光三重レポートを確認してください。' where id = 'VbhLlASDoS1mQaZr-2khu';
update content_bodies set title = 'New Opening! Hakusan Strawberry Farm', description = 'Hakusan Strawberry Farm has opened on March 1st, offering unique strawberry picking experiences with the rare ''Utano'' variety, exclusively grown in Mie Prefecture. Visitors can enjoy both all-you-can-eat and weight-based purchasing options. The strawberries are exceptionally sweet, making it hard to return to other varieties. The farm operates on weekends and holidays in three time slots, with a 40-minute limit for all-you-can-eat. Pricing is set at 2800 yen for adults, 2400 yen for children, and free for preschoolers. Reservations can be made via phone, and a shoe cover is required for entry to prevent microbial intrusion. A camping site is also set to open in March 2025. For more details, check the official Instagram or the Mie tourism report.' where id = 'w5VEFzIcCs1BodsZ862oU';
update content_bodies set title = 'EXILE 橘ケンチ 五感で愉しむ三重の旅 - 湯の山 素粋居 編', description = 'この記事では、EXILE／EXILE THE SECONDの橘ケンチさんが紹介する、自然に囲まれた三重県菰野町の湯の山温泉の麓にある宿「湯の山 素粋居」を取り上げています。各棟は異なる雰囲気や内装、間取りを持ち、まるで居心地の良い美術館のようです。さらに、各部屋には源泉かけ流しの温泉露天風呂が付いています。食事は、炭や薪を使った直火料理が楽しめるレストラン「HINOMORI」で提供され、厳選された熟成牛が目の前でじっくりと火入れされる様子を楽しむことができます。ぜひ、五感で三重の旅を楽しんでください。' where id = 'WbW1uGMuC5xD-9O45Vt_R';
update content_bodies set title = 'EXILE Kenchi Tachibana''s Sensory Journey in Mie - Yunoyama Suisui Edition', description = 'This article introduces ''Yunoyama Suisui,'' a lodging located at the foot of Yunoyama Onsen in Komono Town, Mie Prefecture, surrounded by nature, featuring EXILE/EXILE THE SECOND''s Kenchi Tachibana. Each room has a unique atmosphere, interior, and layout, resembling a comfortable art museum, and includes an open-air hot spring bath with natural hot spring water. Dining is offered at the restaurant ''HINOMORI,'' where guests can enjoy dishes cooked over direct flames using charcoal and firewood. The experience is enhanced as guests can watch the meticulous cooking of selected aged beef right in front of them. Visitors are encouraged to enjoy a sensory journey in Mie!' where id = '7DFeU2hqHwhAjReXnMGmK';
update content_bodies set title = '志摩スペイン村「スプリング フィエスタ」開催中♪', description = '志摩スペイン村では「スプリング フィエスタ」が開催中で、大人も楽しめるリニューアルが盛りだくさんです。新キャラクターミュージカル「ドンキホーテのグラン・ガラ・デ・オペラ～帰ってきたテアトロ・ラ・マンチャ～」、新フラメンコショー「カンデラ」、新アトラクション「アリス イン ダークランド」が登場しています。さらに、新しいフォトスポットやグッズ、いちご祭り、おすすめグルメ、チケットをお得にゲットする裏ワザ5選も紹介されており、大人にこそ楽しんでほしい志摩スペイン村の魅力が満載です。' where id = 'X7xL7cj3umeCk89p-nL0W';
update content_bodies set title = 'Shima Spain Village ''Spring Fiesta'' Now Happening♪', description = 'Shima Spain Village is currently hosting the ''Spring Fiesta,'' featuring numerous renovations aimed at adult visitors. Highlights include a new character musical titled ''Don Quixote''s Grand Gala of Opera - The Return of Teatro La Mancha,'' a fresh flamenco show called ''Candela,'' and a new attraction named ''Alice in Darkland.'' Additionally, there are new photo spots, merchandise, a strawberry festival, recommended gourmet options, and five tips for getting tickets at a discount. The report emphasizes the new attractions and experiences that adults can enjoy at Shima Spain Village.' where id = 'fHk4QfyGW1cC8URybgKNy';
update content_bodies set title = '工場夜景の聖地✨「四日市コンビナート夜景クルーズ」', description = '四日市コンビナートは工場夜景の聖地と呼ばれています。かつてはマイナスイメージが強かったコンビナートですが、今では地域の伝統として受け入れられています。この夜景を海から楽しむ「四日市コンビナート夜景クルーズ」は、陸から見るのとは異なる景色を提供し、ガイドの解説もついています。長年住んでいる方にも初めての方にもおすすめの体験です。クルージングだけでなく、夕食や宿泊のオプションもあり、工業だけではない四日市の魅力を発見できます。詳細は観光三重のウェブサイトをご覧ください。' where id = '2CnLhytscL369Y1M8eoWk';
update content_bodies set title = 'Yokkaichi Night View Cruise: A Sacred Place for Factory Nightscapes', description = 'Did you know that Yokkaichi Complex is known as a sacred place for factory nightscapes? Once associated with negative images, it is now becoming a local tradition. The Yokkaichi Night View Cruise offers a unique opportunity to see these nightscapes from the sea, providing a different perspective compared to land views, complete with a guide''s commentary. This experience is recommended for both long-time residents and first-time visitors. In addition to the cruise, options for dinner and accommodation are available, allowing you to explore a different side of Yokkaichi beyond its industrial image. For more details, visit the Mie Tourism website.' where id = 'NxLfd4HzmCel3drEnbgxE';
update content_bodies set title = '国の有形文化財に登録されている老舗料亭で味わえる茶筅で点てる絶品珈琲「伝七邸」', description = '四日市に約130年の歴史を持つ老舗料亭「伝七邸」があります。敷居が高そうに見えますが、珈琲を飲むだけでも大歓迎です。特に、茶筅で点てる珈琲は独特で、香りがフレグランスのように漂います。美味しい珈琲と歴史ある建物、美しい庭園が心を癒してくれる素敵なお店です。ランチやディナーも提供しており、祝い事や接待にも最適です。また、ヨガ教室や講演会も開催されています。ぜひ訪れてみてはいかがでしょうか。' where id = 'AAGuVmKmGT3BsMYq_oDWq';
update content_bodies set title = 'Experience Exquisite Coffee Whipped with a Tea Whisk at the Historic Restaurant Registered as a Cultural Asset', description = 'Did you know there is a historic restaurant in Yokkaichi with about 130 years of history? Although it may seem exclusive, you can enjoy coffee here! The unique aspect is that the coffee is whipped using a tea whisk. The aroma of the coffee is fragrant, and the combination of its delightful taste, the historical building, and the beautiful garden creates a soothing atmosphere. ''Denshichitei'' also offers lunch and dinner, making it suitable for celebrations and business meetings. Additionally, it hosts yoga classes and lectures. Why not visit this charming place?' where id = 'q73CoCX9lN8N-pEb9d77b';
update content_bodies set title = '国内で現役最古の鉄道可動橋が見られるのはここだけ「四日市みなとまち歩き」', description = '「鉄道可動橋」という名前を聞くだけでワクワクしますよね。四日市には、全国で最も古い現役の鉄道可動橋があります！可動橋だけでなく、四日市港には他にもたくさんの見どころがあります。この地域は賑わう交流拠点として整備される計画があり、今だけの風景かもしれません。新年からダイエットを始めた方には、じっくり歩けるコースを紹介していますので、ぜひ挑戦してみてください。休憩には美味しい珈琲が楽しめる老舗旅館もおすすめです。詳しくは観光三重トピックスをご覧ください。' where id = 'qMZbtPa7lciakTN_fx6D9';
update content_bodies set title = 'The Only Place to See Japan''s Oldest Active Railway Movable Bridge: ''Yokkaichi Minato Town Walk''', description = 'Are you excited just hearing the name ''railway movable bridge''? 😊 Yokkaichi is home to the oldest active railway movable bridge in Japan! In addition to the movable bridge, there are many other attractions in Yokkaichi Port. Plans are underway to develop this area as a bustling hub, so this scenery might only be seen for a limited time! When will you visit? Now is the time! We introduce a walking course for those who have started a diet in the new year, so be sure to give it a try! We also recommend a long-established inn where you can enjoy delicious coffee during your break. For more details, check out the Mie Tourism Topics.' where id = 'ubB9_7hLYlYAWnaJOyNIf';
update content_bodies set title = '【みえのイマココ旅】蔵仕事の見学＆紅くるりドレッシングづくり体験', description = '三重県伊賀市にある福岡醤油店で、歴史ある醤油蔵の見学とドレッシング作りを体験しました。この醤油店は明治時代から続くもので、現役の蔵人による丁寧な説明で醤油作りのこだわりを学びます。人の背よりも大きな木桶が並ぶ醸造蔵や、登録有形文化財の「キリン式圧搾機」の迫力も圧巻です。冬から春にかけては貴重な麹づくりも見られ、自家栽培の「紅くるり大根」を使ったオリジナルドレッシング作りも体験できます。料金はおひとり¥3,000で、島ケ原駅から徒歩約25分の場所にあります。' where id = 'ZfXV4HKv21eDL9lCt7y_h';
update content_bodies set title = 'Mie no Imakoko Travel: Soy Sauce Brewery Tour & Red Kururi Dressing Experience', description = 'The Fukuoka Soy Sauce Shop in Iga City, designated as a registered tangible cultural property, offers a unique experience of touring a historic soy sauce brewery and making dressing. Visitors can learn about the traditional soy sauce production process, which has been in practice since the Meiji era, through detailed explanations from skilled brewers. The impressive brewing facility features large wooden barrels and a powerful ''Kirin-style pressing machine.'' During winter to spring, guests can observe the rare process of koji-making. Additionally, participants can create their own original dressing using homegrown ''Red Kururi'' radishes and taste different types of soy sauce to discover their unique flavors. The experience is priced at ¥3,000 per person and is located approximately 25 minutes on foot from Shimagahara Station.' where id = 'Tbd65X5WWYpobDEk4-515';
update content_bodies set title = '合掌民宿 なかや（なかや）【五箇山】', description = '合掌民宿なかやは、富山県南砺市相倉231に位置しています。郵便番号は939-1915です。お問い合わせは0763-66-2457までどうぞ。詳細は公式ウェブサイト（http://www1.tst.ne.jp/snakaya/）をご覧ください。' where id = 'mylb75U5NZDrGa-LCjkbt';
update content_bodies set title = 'Gassho Minpaku Nakaya (Nakaya) [Gokayama]', description = 'Gassho Minpaku Nakaya is located at 231 Aikura, Nanto City, Toyama Prefecture, 939-1915, Japan. For inquiries, you can reach them at 0763-66-2457. More information can be found on their website: http://www1.tst.ne.jp/snakaya/' where id = 'DJuazZ-B9a2caiqA0zjiW';
update content_bodies set title = '斎宮で平安時代にタイムスリップ！', description = '現在、「さいくう平安の杜」では土曜・日曜に平安時代の貴族の一日を体験できるイベントを開催中です。平安装束体験ができ、服の上から着られるため、気軽に参加できます。美しい仮名文字を筆で書くお仕事体験や、源氏物語にも登場する平安時代のお菓子「粉熟（ふずく）」も楽しめます。体験の合間には、神社に奉納される「祭祀舞」を目の前で楽しむことができますが、祭祀舞が行われない日もあります。詳しくは観光三重の記事をご覧ください。場所は斎宮、アクセスは近鉄「斎宮駅」から徒歩約5分。開催日は1月・2月の土曜・日曜と2月24日（月）で、1月12日（日）と2月16日（日）は開催されません。開催時間は13:00〜15:00で、出入り自由、料金は無料です。' where id = 'pnOGfbTwTzME8xCEeUdNz';
update content_bodies set title = 'Time Travel to the Heian Period at Saiku!', description = 'Currently, ''Saiku Heian no Mori'' is hosting an event on Saturdays and Sundays where you can experience a day in the life of a Heian aristocrat! You can try on Heian period clothing, which is easy to wear over your clothes, suitable for anyone from about 120 cm tall to adults. Experience writing beautiful kana characters with a brush, and enjoy traditional Heian sweets, including ''Fuzuku,'' mentioned in ''The Tale of Genji.'' In between activities, you can enjoy the ''Saishi Mai'' dance performed in front of you, although it may not be available every day. For more details, check the article on Kankomie. Location: Saiku Heian no Mori, Address: 2800 Saiku, Meiwa-cho, Taki-gun, Mie Prefecture. Access: About a 5-minute walk from Kintetsu ''Saiku Station.'' Event days: Saturdays and Sundays in January and February, and February 24 (Monday). Note: No events on January 12 and February 16. Time: 1:00 PM to 3:00 PM, free entry. No reservation required.' where id = 'gydlyERmvr0ZnF7n2qJYZ';
update content_bodies set title = '＼2か月限定の足湯列車！湯の山施設割引の特典付き／', description = '足湯列車が2025年1月11日から2月16日までの土日限定で運行します。温かい足湯に浸かりながら、バーカウンターで地酒を楽しむことができます。運行区間は近鉄名古屋駅から湯の山温泉駅で、特典として記念乗車券と湯の山温泉周辺施設で使える割引手形がもらえます。大人510円、子供260円に加え、足湯利用には100円が必要です。詳しくは観光三重の公式サイトをご覧ください。' where id = 'hWvWon7D17aXD_tHX8CNk';
update content_bodies set title = 'Limited-Time Foot Bath Train with Discounts for Yunoyama Facilities!', description = 'Experience the unique foot bath train running for just eight days on weekends from January 11 to February 16, 2025. Enjoy a warm foot bath while sipping local sake at the onboard bar. The train operates between Kintetsu Nagoya Station and Yunoyama Onsen Station, with special discounts available for nearby facilities. Tickets are priced at 510 yen for adults and 260 yen for children, plus an additional 100 yen for the foot bath. Passengers will receive a commemorative ticket and a discount voucher for various attractions, including the Gozaisho Ropeway and the Yunoyama Onsen day-use bath. For more details, visit the official tourism site.' where id = 'Sk6tEbK8v7cZnVPnJcPli';
update content_bodies set title = '【みえのイマココ旅】きもも堂', description = '関宿で伊勢木綿の着物を着て散策できる「きもも堂」がオープンしました。江戸時代の街並みを楽しみながら、心地よい肌触りのカラフルな着物をレンタルできます。友達やカップルでお揃いの着物を着ることも可能で、足袋や草履、バッグもレンタルできるため、手ぶらで体験できます。暑い季節にはレトロ浴衣のレンタルもあり、体験時間は無制限で、16時までに返却すれば大丈夫です。着物を着たまま飲食も楽しめるので、関宿観光を存分に満喫できます。料金はおひとり¥5,500で、アクセスも良好です。' where id = 'aQTOEVFBFBtjSLSUV0Yba';
update content_bodies set title = 'Mie no Imakoko Travel: Kimomo-do', description = 'Explore the historic town of Sekijuku while wearing traditional Ise cotton kimonos at Kimomo-do. This experience allows visitors to stroll through the Edo-period streets in comfortable, colorful kimonos suitable for all ages. You can reserve matching outfits with friends or couples, and the rental includes tabi socks, sandals, and bags, making it hassle-free. During hot seasons, retro yukata rentals are also available. The rental time is unlimited until the store closes at 4 PM, allowing for leisurely exploration and dining in the area. The experience costs ¥5,500 per person and is easily accessible from Sekieki Station or nearby highways. Kimomo-do offers a unique way to enjoy Mie''s rich culture and heritage.' where id = 'k5Y-tSFuBAtUhbl_hAytW';
update content_bodies set title = 'JR関西線12駅途中下車の旅', description = '俳優の松田昇大さんが案内役となり、JR関西線の「関駅」と「伊賀上野駅」を途中下車し、観光名所や地域のスポット、おいしいお菓子や食事を紹介するショートムービーです。令和6年11月1日から、JR関西線の12駅（亀山駅～加茂駅）で途中下車でき、沿線のお店で使えるクーポンがセットになった企画きっぷが販売されます。チケットは日本旅行の予約サイトで購入可能です。' where id = 'MHtl_r6IPuFfv4HmZQ5XH';
update content_bodies set title = 'Journey of Getting Off at 12 Stations on the JR Kansai Line', description = 'Actor Shodai Matsuda serves as the guide for a leisurely town walk along the JR Kansai Line. The short film features stops at ''Seki Station'' and ''Iga Ueno Station'' among the 12 stations, showcasing local attractions, regional spots, and delicious snacks and meals. Starting November 1, 2024, a special ticket will be available, allowing travelers to get off at any of the 12 stations (from Kameyama Station to Kamo Station) and includes coupons for use at shops along the line. The tickets will be sold on Japan Travel''s reservation site.' where id = 'V9KdVMJJ9eryh3sUPBIP1';
update content_bodies set title = '丸山千枚田（三重県熊野市）～“日本の棚田百選”にも選ばれた息をのむ曲線美', description = '三重県熊野市にある丸山千枚田は、日本ユネスコ協会連盟の“プロジェクト未来遺産”に登録されており、“日本の棚田百選”にも選ばれています。この美しい景観は、復元と保存に携わる人々によって支えられています。記事では、丸山千枚田の美しさと、その保存に尽力する人々の活動について紹介しています。息をのむような曲線美を持つ棚田は、自然の驚異であり、世代を超えて守り継がれてきた絶景です。' where id = 'jtv5b_ypoNOM_DyyfPRqu';
update content_bodies set title = 'Maruyama Senmaida (Kumano City, Mie Prefecture) - A Breathtaking Curvilinear Beauty Selected as One of Japan''s Top 100 Terraced Rice Fields', description = 'Maruyama Senmaida, located in Kumano City, Mie Prefecture, is registered as a ''Future Heritage'' by the Japan UNESCO Association and has been selected as one of Japan''s Top 100 Terraced Rice Fields. This stunning landscape is supported by the people who work to restore and preserve it. The article explores the beauty of Maruyama Senmaida and the efforts of those involved in its conservation. The breathtaking curves of the terraced fields are a natural wonder that has been maintained and passed down through generations.' where id = 'hBssPUsd_VHbv06c9Ic_2';
update content_bodies set title = '無料サービス充実！ 子連れ極楽宿', description = '今回は、無料サービスが充実した子連れ向けの宿を紹介します。おすすめポイントは、アルコールを含むドリンクやアイスキャンディーが食べ飲み放題のプレミアムラウンジ、英虞湾を見渡せる大浴場、赤ちゃん連れに配慮したベビーチェアやベッドの完備です。豪華なバイキングでは、特に美味しい海鮮や無料の離乳食が提供されます。また、カラオケルームは19時まで無料で利用可能です。伊勢志摩観光にも便利な立地で、周辺の観光地へのアクセスも良好です。詳細は公式観光サイトをご覧ください。' where id = 'ZBROpjLhasYmiA3IH0ylG';
update content_bodies set title = 'Free Services Galore! Family-Friendly Paradise Inn', description = 'This article introduces a family-friendly inn with abundant free services. Key highlights include a premium lounge offering unlimited drinks and ice pops, a spacious public bath with stunning views of Ago Bay, and amenities for infants like baby chairs and beds. The buffet features freshly prepared dishes, especially seafood, and complimentary baby food for young children. Entertainment options include a karaoke room available for free until 7 PM. The inn is conveniently located for sightseeing in Ise-Shima, with attractions like Shima Green Adventure and Toba Aquarium within a short drive. For more details, visit the official tourism site.' where id = 'l59K7OmixK0O0BEqQDk_o';
update content_bodies set title = '斎王のみち～斎宮紹介動画（三重県明和町）', description = '一般社団法人明和観光商社が自治体や大学と協力して展開するアニメ「斎王のみち」を紹介します。このアニメは、令和の時代に新たな「斎王」が選ばれたらという歴史上の「もしも」を題材にしたファンタジーストーリーで、伊勢・明和の地が舞台です。観光スポットやグルメ、お土産商品など、アニメを活用した様々な展開が期待されています。明和町の魅力を伝える取材レポートもあり、歴史や美味しいものを楽しむ旅が提案されています。' where id = 'q3WLyxTdWLauTZ2SCrr6R';
update content_bodies set title = 'The Path of the Saiō - Introduction Video of the Saiō Palace (Meiwa Town, Mie Prefecture)', description = 'This video introduces the anime ''The Path of the Saiō,'' developed by the Meiwa Tourism Association in collaboration with local governments and universities. The story is a fantasy based on the historical premise of what if a new ''Saiō'' were chosen in the Reiwa era, set in the Ise and Meiwa region. Various developments utilizing the anime are expected, including tourist spots, gourmet food, and souvenir products.' where id = 'bJFptLEsI-6tX4fqdKh8-';
update content_bodies set title = '親子大橋　バイク×ドローン映像（三重県南伊勢町）｜観光三重', description = '親子大橋は、二つの橋が手を取り合っているように見えることから名付けられました。大きい方は南島大橋、小さい方は阿曽浦大橋です。入り組んだ地形のため、通常は一方の橋しか見ることができませんが、「鵜倉園地」の「あけぼの展望台」からは両方の橋を同時に見ることができます。この映像は、大台町地域おこし協力隊の井坂治氏によって提供されています。' where id = 'tjLtc6u2jTpal5zq4lhIB';
update content_bodies set title = 'Oya Ko Bridge: Bike and Drone Footage (Minamiise Town, Mie Prefecture) | Kankomie', description = 'The Oya Ko Bridge, named for its appearance of two bridges holding hands, consists of the larger Minamishima Bridge and the smaller Asoura Bridge. Due to the complex terrain, typically only one bridge is visible at a time. However, both bridges can be viewed simultaneously from the Akebono Observatory in Ugura Park. The video is provided by Haru Isaka from the Oda Town Regional Revitalization Cooperation Team.' where id = 'MbavekcWkglEwekt0KKE4';
update content_bodies set title = '三重みかん狩り2選🍊', description = '三重県の中心、津市と多気町で楽しめるみかん狩りのスポットを2つ紹介します。秋の味覚であるみかんをたっぷり味わえ、さらにお土産も付いてきます。名古屋から1時間、大阪から1時間半の距離にあり、自然に囲まれた環境でみかん狩りを楽しむことができます。

📍津市観光みかん狩り園
場所：三重県津市大里窪田町7
電話番号：059-232-6963（期間中のみ）
開催期間：2024年10月20日～11月30日
営業時間：9：00～16：00（最終受付15：30）
料金：大人（中学生以上）1,300円、小人（4歳～小学生）1,100円、幼児（～3歳）600円。
駐車場：完備
アクセス：伊勢自動車道「津IC」から車16分、「芸濃IC」から車10分。

📍ごかつら池ふるさと村みかん狩り
場所：三重県多気郡多気町五桂956
電話番号：0598-67-6196
開催期間：10月上旬～11月30日
営業時間：10：00～15：00
料金：大人（中学生以上）1,200円、小人（3歳～小学生）1,000円。
駐車場：完備
アクセス：伊勢自動車道「勢和多気IC」から車10分。' where id = '4hZWr6YhQ9-uxzJVFcf11';
update content_bodies set title = 'Two Mikan Picking Spots in Mie 🍊', description = 'Discover two convenient mikan picking locations in Mie Prefecture, located in the heart of the region, in Tsu and Taki. Enjoy the autumn flavor of mikan to your heart''s content, with souvenirs included! Just an hour from Nagoya and an hour and a half from Osaka, you can relish mikan picking surrounded by nature. 

📍 Tsu City Mikan Picking Garden
Location: 7 Osato Kubota-cho, Tsu City, Mie Prefecture
Phone: 059-232-6963 (during the season)
Period: October 20, 2024 - November 30, 2024
Hours: 9:00 AM - 4:00 PM (last entry at 3:30 PM)
Fees: Adults (middle school and above) 1,300 yen, Children (4 years to elementary school) 1,100 yen, Toddlers (up to 3 years) 600 yen.
Parking: Available
Access: 16 minutes by car from Ise Expressway ''Tsu IC'', 10 minutes from ''Geino IC''.

📍 Gokatsura Pond Hometown Village Mikan Picking
Location: 956 Gokai, Taki Town, Taki District, Mie Prefecture
Phone: 0598-67-6196
Period: Early October - November 30
Hours: 10:00 AM - 3:00 PM
Fees: Adults (middle school and above) 1,200 yen, Children (3 years to elementary school) 1,000 yen.
Parking: Available
Access: 10 minutes by car from Ise Expressway ''Seiwa Taki IC''.' where id = 'kT5zVQ7sU1zV9cy9zol04';
update content_bodies set title = '愛犬と特別なひとときを！プライベートドッグラン付きの温泉宿「野寛」', description = '2024年3月に鳥羽市にオープンした「野寛」は、愛犬と宿泊できる全室プライベートドッグラン付きの温泉宿です。料理は三重県産の食材をふんだんに使った美しいフルコースで、部屋食なので滞在中は愛犬と一緒に過ごせます。さらに、愛犬用の無添加メニューやデザート、アメニティも豊富で、飼い主だけでなく愛犬にも極上のおもてなしを提供しています。愛犬のお誕生日や特別な日に訪れるのにぴったりの場所です。' where id = 'wbUf4FUrdZXSCGpryqt8k';
update content_bodies set title = 'Special Moments with Your Dog! Private Dog Run Hot Spring Inn ''Nokan''', description = 'Opened in March 2024 in Toba City, ''Nokan'' is a hot spring inn where you can stay with your dog, featuring private dog runs in all rooms. The cuisine showcases abundant local ingredients from Mie Prefecture, presented beautifully in a full-course meal. Guests can enjoy their meals in their rooms, allowing them to spend quality time with their dogs throughout their stay. Additionally, the inn offers a variety of additive-free menus, desserts, and amenities for dogs, ensuring a luxurious experience for both owners and their pets. It''s a perfect place to celebrate your dog''s birthday or special occasions!' where id = 'A4DXrnLtbSpDEmjCYO7q5';
update content_bodies set title = '志摩市観光農園のネモフィラが見頃です💙', description = '可憐なシルバーブルーのネモフィラの花が一面に咲き広がり、春の花絶景を楽しめます。緩やかな丘陵地に植えられたネモフィラは、どこを切り取っても美しい景色を提供します。赤い電話ボックスやベンチなどのフォトスポットもあり、訪れる人々を楽しませます。また、一部には芝桜も植えられており、青空に映えるブルー、薄紫、ピンクの色合いが美しいです。志摩市観光農園はGWまで楽しむことができ、開園日は4月6日から5月6日までの予定です。利用料金は大人300円、中学生以下は無料です。4月14日現在、見頃を迎えています。' where id = 'LZFMuqDR8zo_qHNEFhNLF';
update content_bodies set title = 'Nemophila in Shima City Tourist Farm is in Full Bloom 💙', description = 'The delicate silver-blue nemophila flowers are in full bloom, creating a breathtaking spring landscape. Planted on gentle hills, the flowers provide picturesque views from every angle. Cute photo spots, including a red telephone box and benches, enhance the experience. Additionally, some areas feature moss phlox, with blue, light purple, and pink colors beautifully contrasting against the blue sky. Visitors can enjoy the Shima City Tourist Farm until the Golden Week. 

Opening dates: April 6 (Sat) to May 6 (Mon, holiday), subject to change based on blooming conditions. Admission fee: Adults 300 yen, free for middle school students and younger. As of April 14, the flowers are at their peak. 

Location: 511-5 Anagawa, Isobe-cho, Shima City (near Ise-Shima Road Station). Approximately 30 minutes from Ise Expressway ''Ise Nishi IC'' along Route 167. Free parking available. Open from 9:00 AM to 5:00 PM. Pets allowed (leash required).' where id = 'LgFZRW_BsVzCBI8FUB1xY';
update content_bodies set title = '野原農村公園の藤棚(みえ旅アンバサダー：キャスターマミ)', description = 'VISONから最も近い「野原農村公園」の約60ｍの藤棚が見頃を迎えています。2024年4月25日現在、全体の8割が開花しており、ゴールデンウイーク期間中が一番の見頃となる見込みです。公園はVISONから車で10分、松阪・伊勢方面からも30分でアクセス可能です。広場や遊具もあり、ファミリーにもおすすめのスポットです。公園の住所は三重県度会郡大紀町野原649-1で、駐車場は30台分あります。観光三重トピックスではさらに詳しい情報が紹介されているので、ぜひご覧ください。この投稿が面白いと思ったら、「いいね＆保存」をお願いします！' where id = 'RMp0LBzbL5gfdvFRE8C3I';
update content_bodies set title = 'Wisteria Trellis at Nohara Rural Park (Mie Travel Ambassador: Caster Mami)', description = 'The approximately 60-meter wisteria trellis at Nohara Rural Park, the closest park to VISON, is currently in full bloom, with 80% of the flowers open as of April 25, 2024. The peak bloom is expected during the Golden Week holiday. The park is just a 10-minute drive from VISON and can be reached in 30 minutes from Matsusaka and Ise. It features open spaces and playground equipment, making it a great spot for families. The park is located at 649-1 Nohara, Taiki-cho, Watarai-gun, Mie Prefecture, with parking available for 30 cars. For more details, check out the Mie Tourism Topics. If you find this post interesting, please like and save it!' where id = 'kd3Bp3XMIFUitbETKuVjM';
update content_bodies set title = '丸山公園ドウダンツツジ(みえ旅アンバサダー：キャスターマミ)', description = '2023年秋、三重県の紅葉スポット「丸山公園ドウダンツツジのトンネル」が大ヒットしました。2024年には春のお花の季節も楽しんでほしいと呼びかけています。花が終わった後も「トトロの森」の新緑のトンネルが待っています。ドウダンツツジの見頃はGW前までと予想されています。丸山公園は三重県多気郡大台町に位置し、駐車場は公園内に約10台分あります。紀勢自動車道の大宮大台ICから車で9分のアクセスです。観光三重トピックスではさらに詳しい情報が紹介されているので、ぜひチェックしてみてください。この投稿が面白いと思ったら、「いいね＆保存」をお願いします！' where id = '402cYBvsNLrQpCYfrA2RE';
update content_bodies set title = 'Maruyama Park''s Enkianthus (Mie Travel Ambassador: Caster Mami)', description = 'In the autumn of 2023, Maruyama Park''s ''Enkianthus Tunnel'' became a popular spot for viewing fall foliage in Mie Prefecture. Visitors are encouraged to also enjoy the spring flowers in 2024. Even after the flowers bloom, the lush greenery of the ''Totoro Forest'' awaits. The best time to see the Enkianthus flowers is expected to be before Golden Week. Maruyama Park is located in Odaicho, Taki District, Mie Prefecture, with parking available for about 10 cars. Access is a 9-minute drive from the Kisei Expressway''s Omiya Oda IC. For more details, check the Mie Tourism Topics. If you find this post interesting, please like and save it!' where id = '_furxHCQqbt47Dg2qX7ix';
update content_bodies set title = 'BOUQUET IITAKA（みえ旅アンバサダー：キャスターマミ）', description = '2024年4月23日にオープンするBOUQUET IITAKAは、道の駅のイメージを一新するオシャレなドーナツ店です。温泉で人気の「飯高駅」の一部が改装され、大台町に一号店が誕生しました。セルフスタイルでドーナツを選ぶテイクアウト専門店で、しっとり・もっちり・ふんわりの「熟生ドーナツ」は厳選された国産小麦粉と発酵バターを使用し、米油で揚げられています。また、持ち帰り不可の「揚げたて超熟生オリジナル」も楽しめます。オープン初日の様子は、みえ旅アンバサダーの@castermamiが伝えます。詳しくは公式Instagramをご覧ください。' where id = 'MHegEbtud7mln6pERt6oO';
update content_bodies set title = 'BOUQUET IITAKA (Mie Travel Ambassador: Caster Mami)', description = 'Opening on April 23, 2024, BOUQUET IITAKA is a stylish donut shop that redefines the image of roadside stations. Located within the popular ''Iitaka Station'' known for its hot springs, this is the first store in Odaicho. The shop features a self-service style for selecting donuts, focusing on takeout. Their ''Jukusei Donuts'' are made with carefully selected domestic wheat flour and fermented butter, fried in rice oil for a unique texture. Additionally, customers can enjoy the limited ''Freshly Fried Super Jukusei Original'' which is not available for takeout. Mie Travel Ambassador @castermami will share the opening day''s experience. For more details, check the official Instagram.' where id = 'JFLXItyFctqsVdBhgh1H4';
update content_bodies set title = 'クレープのお店パルティ(みえ旅アンバサダー：キャスターマミ)', description = '2023年秋、三重県松阪市にオープンしたクレープ店「パルティ」は、猫好きにはたまらない可愛いにゃんこクレープが特徴です。オーナーはイラストも得意で、写真を撮りたくなるような「にゃんこデコ」のクレープを提供しています。また、猫モチーフの焼き菓子も販売しています。地産地消にこだわり、子供たちにも安心して食べてもらえる手作りスイーツを提供。詳細は公式Instagramで確認できます。店舗は三重県松阪市小津町377-4にあり、平日は14時から18時、土曜日は11時から17時まで営業。木曜日、日曜日、祝日は定休日で、駐車場は4台分あります。車や公共交通機関でのアクセスも便利です。' where id = 'TrOqpCUv6TXEmu2qonWvb';
update content_bodies set title = 'Crepe Shop Partir (Mie Travel Ambassador: Caster Mami)', description = 'A new crepe shop called Partir opened in Matsusaka City, Mie Prefecture, in the fall of 2023, attracting cat lovers with its adorable cat-themed crepes. The owner, who is also an illustrator, creates photogenic ''nyanko deco'' crepes that are too cute to resist. The shop also offers cat-themed baked goods. Committed to local production for local consumption, the handmade sweets are safe for children to enjoy. For more details, check the official Instagram. The shop is located at 377-4 Ozu-cho, Matsusaka City, and is open from 2 PM to 6 PM on weekdays and 11 AM to 5 PM on Saturdays, closed on Thursdays, Sundays, and holidays. Parking is available for four cars. Access is convenient by car or public transport.' where id = 'OndwMjlP6aA6v8n4K34ha';
update content_bodies set title = 'ハートあふれる ロマンチックの聖地❤ #鵜倉園地', description = '鵜倉園地は、ハート型の入り江や展望台が特徴のロマンチックな聖地です。カップルに人気のスポットで、ブランコや美しい海の景色を楽しむことができます。ここから見る星空や日の出は特別で、訪れる人々を魅了します。三重県は絶景が豊富で、観光名所がたくさんあります。三重の美しい観光地についてもっと知りたい方は、ぜひフォローしてください。' where id = 'XkZZEqFqwHK5RMFM1Yvmn';
update content_bodies set title = 'A Romantic Sacred Place Full of Heart❤ #Ukuragarden', description = 'Ukuragarden is a romantic sanctuary known for its heart-shaped cove and observation deck. It is a popular spot for couples, featuring swings and breathtaking views of the sea. Visitors can enjoy exceptional starry skies and sunrises from this location. Mie Prefecture is celebrated for its stunning landscapes, making it a treasure trove for sightseeing. Follow for more insights into Mie''s beautiful attractions.' where id = 'I4q0Q2jQ42wo9FLtGJ_wT';
update content_bodies set title = '季節の花に囲まれる癒しの神社', description = '都波岐奈加等神社は、手水舎を花で彩る「花手水」と、季節の花をあしらった「御朱印」が楽しめる神社です。三重県鈴鹿市に位置し、パワースポットとしても知られています。美しい絶景が広がるこの場所は、観光客にとって魅力的なスポットです。三重県は絶景の宝庫であり、訪れる価値があります。最新情報は@tsubakinakatojinjaをフォローしてチェックしてください。' where id = 'GWG6uD-rmTAsRS22rdpAH';
update content_bodies set title = 'Healing Shrine Surrounded by Seasonal Flowers', description = 'Tsubakinakato Shrine is a must-visit for its unique ''Hana Chozu,'' where the water basin is beautifully decorated with seasonal flowers, and the ''Goshuin'' stamps that feature floral designs. Located in Suzuka City, Mie Prefecture, this shrine is not only a spiritual power spot but also offers breathtaking views. Mie Prefecture is known for its stunning scenery, making it a treasure trove for tourists. Follow @tsubakinakatojinja for more updates and insights into this enchanting location.' where id = 'THUaNrgqAjduwS8mhz5du';
update content_bodies set title = 'ヤシの木に囲まれ南国リゾート気分', description = 'マリーナ河芸は、ヤシの木に囲まれた南国リゾートの雰囲気を楽しめる場所です。美しいビーチや絶景を眺めながら、海からの朝日やカフェでのひとときを堪能できます。三重県に位置し、素晴らしい景色が広がるこの場所は、海外旅行気分を味わいたい方にぴったりのスポットです。ぜひ@marinakawageをフォローして、さらに魅力的な情報をチェックしてください。' where id = 'CqSlx2JvWvTj3OwysgPoP';
update content_bodies set title = 'Feeling like a tropical resort surrounded by palm trees', description = 'Marina Kawage offers a tropical resort atmosphere surrounded by palm trees, stunning views, and a beautiful beach. Visitors can enjoy the breathtaking sunrise over the sea and relax at the cafe while taking in the sunset. Located in Mie Prefecture, known for its spectacular scenery, Marina Kawage is a perfect destination for those seeking a getaway that feels like an overseas vacation. Follow @marinakawage to explore more about this picturesque location.' where id = '4Ozf7vRq3WMUbAf7UouXk';
update content_bodies set title = 'まるで絵画の世界 花の楽園', description = '三重県にあるなばなの里のベゴニアガーデンでは、1年中満開の花々が楽しめます。この美しい場所は絶景の宝庫であり、花好きや観光客にとって理想的な目的地です。訪れる人々は、季節ごとのイルミネーションやいちご狩り、桜の観賞など、さまざまなアトラクションを楽しむことができます。最新情報は@nagashimaresort_officialをフォローして、三重県の美しさをぜひ探訪してください。' where id = 'dxO-mvRdDmfY0ioZHV0lB';
update content_bodies set title = 'A World Like a Painting: A Paradise of Flowers', description = 'In Mie Prefecture, the Begonia Garden at Nabananosato offers a stunning display of flowers that bloom year-round. This picturesque location is a treasure trove of spectacular views, making it a perfect destination for flower lovers and tourists alike. Visitors can enjoy various attractions, including seasonal illuminations, strawberry picking, and cherry blossom viewing. Follow @nagashimaresort_official for more updates and explore the beauty of Mie Prefecture.' where id = 'H1Lje4y4U26OsXYMTUzMo';
update content_bodies set title = '季節を楽しむ 米粉100%クレープ', description = 'この説明では、Ricca Riccaが提供する米粉100%のクレープについて紹介しています。地元の食材を使用した優しい甘さが特徴で、特にいちごスイーツが注目されています。三重県に位置し、絶景や観光名所である伊勢神宮があることが強調されています。フォロワーにこの地域の魅力や料理を楽しむよう促しています。' where id = 'lx-cogyvfGjcXz8dNaS0u';
update content_bodies set title = 'Enjoy the Season with 100% Rice Flour Crepes', description = 'This description highlights the 100% rice flour crepes offered by Ricca Ricca, emphasizing their gentle sweetness made from local ingredients. The crepes are associated with seasonal enjoyment and are particularly noted for their strawberry sweets. The location is Mie Prefecture, known for its beautiful views and attractions, including the famous Ise Shrine. The post encourages followers to explore the region and its culinary delights.' where id = 'feUVB4DzeYUVDImL-3SPi';
update content_bodies set title = '伊勢神宮参道の甘い誘惑', description = 'ダンデライオンチョコレートでは、地元の食材を使用したカヌレやスモア、ホットチョコレートなどの甘いメニューを提供しています。三重県の伊勢神宮近くに位置し、絶景が広がる地域として知られています。店舗限定メニューの情報を得るために@dandelion_chocolate_iseをフォローし、三重の美しい景色を楽しむことをお勧めします。' where id = 'uxLc-K9umPQsEPNVStxyR';
update content_bodies set title = 'Sweet Temptations on the Ise Grand Shrine Path', description = 'Dandelion Chocolate offers a variety of sweet treats including canelé, s''mores, and hot chocolate, all made with local ingredients. The shop is located near the Ise Grand Shrine in Mie Prefecture, which is known for its stunning views. Visitors are encouraged to follow @dandelion_chocolate_ise for exclusive store-limited menus and to explore the beautiful sights of Mie.' where id = 'tjpXcAgcuZd1L_yxFymGC';
update content_bodies set title = '女性の願いが叶うパワースポット', description = '神明神社は、女性の願いが叶うとされる有名なパワースポットです。特に満月の夜には「神あかり」と呼ばれる特別なお参りが行われ、訪れる人々に独特のスピリチュアルな体験を提供しています。三重県に位置し、絶景が広がるこの地域は、御守りを通じて祝福や守護を求める多くの観光客を惹きつけています。自然の美しさに恵まれたこの場所は、精神性と観光を融合させたい人々にとって理想的な目的地です。' where id = 'svDTHjSjxakbHM_RG2ubX';
update content_bodies set title = 'Power spot where women''s wishes come true', description = 'Shinmei Shrine, also known as Ishigami-san, is a renowned power spot where women''s wishes are believed to be fulfilled. A special prayer service called ''kami akari'' takes place on full moon nights, adding a unique spiritual experience for visitors. Located in Mie Prefecture, which is famous for its breathtaking views, the shrine attracts many tourists seeking blessings and protection through talismans. The area is rich in natural beauty, making it a perfect destination for those looking to combine spirituality with sightseeing.' where id = 'SG4XIlbPCBr9xqk8EqcxW';
update content_bodies set title = '花で清める 祈りの空間', description = '竹神社では、花を使って心を清める特別な体験が提供されています。毎月の満月の日には特別なお参りが行われ、神聖な雰囲気が一層高まります。三重県に位置する竹神社は、絶景が広がる場所として知られており、訪れる人々は花手水や御朱印、絵馬の奉納などの伝統的な行事に参加できます。@_takejinjaをフォローして、三重県の魅力を発見してください。' where id = 'yXTBoWgSdWrxNhyqoxo17';
update content_bodies set title = 'A Space of Prayer that Purifies with Flowers', description = 'Take Shrine offers a unique experience where visitors can purify their spirits with flowers. Special visits are held every month on the full moon day, enhancing the spiritual atmosphere. Located in Mie Prefecture, known for its breathtaking views, Take Shrine invites you to explore its beauty and participate in traditional practices such as flower washing, receiving goshuin (temple stamps), and writing ema (votive tablets). Follow @_takejinja for updates and discover the charm of Mie Prefecture, a true treasure for travelers.' where id = 'dH4n2XxUxn8NEbQYIsBiT';
update content_bodies set title = '忍者の聖地で体験　憧れの必殺技！', description = '伊賀流忍者博物館では、本物の手裏剣打ち体験ができ、伊賀忍者の発祥地で忍者の世界に浸ることができます。本物の手裏剣を手にすると、そのずっしりとした重みを感じることができます。この体験は子供だけでなく、海外からの観光客にも大人気です。あなたも忍者になってみませんか？詳しくはリンクをチェックしてください。' where id = 'WD6x2P5kZS5tseFYJF9Of';
update content_bodies set title = 'Experience the Sacred Place of Ninjas: Dream Techniques!', description = 'At the Iga-ryu Ninja Museum, you can experience real shuriken throwing, immersing yourself in the world of ninjas at the birthplace of Iga ninjas. Holding a real shuriken allows you to feel its substantial weight. This experience is not only popular among children but also attracts many tourists from abroad. Are you ready to become a ninja? For more details, visit the provided link.' where id = 'BMhB4jtAHG5ayOc0TmcEj';
update content_bodies set title = '三重県で2泊3日の卒業旅行❤1日目', description = '国内の卒業旅行にぴったりな伊勢志摩。地元の大学生が伊勢志摩のグルメや人気スポットを紹介します。1日目のスケジュールは、しまかぜに乗車し、かつおの天ぱくを楽しみ、大王埼灯台を訪れ、志摩地中海村を探索します。2日目は志摩スペイン村と賢島宝生苑、3日目は横山展望台、伊勢神宮、おかげ横丁を訪れる予定です。詳細は観光三重のサイトをご覧ください。' where id = 'RNa6O8ux1DjwGyWv83j1w';
update content_bodies set title = 'Graduation Trip in Mie Prefecture: Day 1', description = 'For domestic graduation trips, Ise-Shima is the perfect choice! Local university students introduce the gourmet food and popular spots in Ise-Shima. The schedule for Day 1 includes riding the Shimakaze train, enjoying Katsuobushi Tempura, visiting the Daiōzaki Lighthouse, and exploring the Shima Mediterranean Village. The following days feature visits to Shima Spain Village, Kashikojima Hojoen, Yokoyama Observatory, Ise Jingu Shrine, and Okage Yokocho. For more details, visit Kankomie!' where id = 'O-gOBc_TUF7z_W0OGwQH4';
update content_bodies set title = '合掌民宿 長ョ門（ちょうよもん）【五箇山】', description = '合掌民宿長ョ門は、富山県南砺市相倉418に位置しています。郵便番号は939-1915です。お問い合わせは0763-66-2755までどうぞ。詳細は公式ウェブサイト（https://www.tabi-nanto.jp/archives/5045）をご覧ください。' where id = 'UyqoTrz2wh5g-BIxUI7Pa';
update content_bodies set title = 'Gassho Minpaku Choyomon (Gokayama)', description = 'Gassho Minpaku Choyomon is located at 418 Aikura, Nanto City, Toyama Prefecture, 939-1915, Japan. For inquiries, you can contact them at 0763-66-2755. More information can be found on their website: https://www.tabi-nanto.jp/archives/5045.' where id = '1xYmJrBdVJCbcNrr8XeVm';
update content_bodies set title = '絶対行くべき！伊勢神宮すぐそこ おしゃれ和みカフェ', description = '伊勢神宮を訪れた際には、ぜひ立ち寄りたいカフェ「参道TERRACE」。ここでは、本格的でおいしいコーヒーや地元の素材を使ったスイーツが楽しめます。特に、ハンドドリップで淹れる「炭焼焙煎珈琲」や、時間をかけて抽出する「水出し珈琲」が人気です。また、伊勢・志摩の素材を使ったしっとりとしたカステラも好評です。開放感のある店内でリラックスしながら、お伊勢参りの休憩にぴったりの場所です。詳しくは公式サイトをご覧ください。' where id = '21zHSL5ouaNPk0GywtKjR';
update content_bodies set title = 'A Must-Visit! Stylish Japanese Cafe Right Next to Ise Shrine', description = 'When visiting Ise Jingu, you should definitely stop by Sando TERRACE! This cafe offers authentic and delicious coffee, along with sweets made from local ingredients. They serve ''charcoal-grilled roasted coffee'' brewed by hand for each cup and ''cold brew coffee'' that takes time to extract. The moist castella, made with ingredients from Ise and Shima, is particularly popular. The spacious interior provides a relaxing atmosphere, making it a perfect spot to take a break during your pilgrimage. For more details, visit their website.' where id = '8vfQhwZ0-zNCFZG0Ty3hM';
update content_bodies set title = '死ぬまでに行きたい絶景スポット', description = '三重県は絶景の宝庫であり、訪れるべきスポットがたくさんあります。特におすすめの場所には、びん玉ロード、金井神社、なばなの里、うみてらす14があります。これらの場所は、自然の美しさや独特の景観を楽しむことができる絶好のスポットです。さらに多くの素晴らしい場所があるので、ぜひフォローして最新情報をチェックしてください。' where id = 'HZ_oAsgeU4Roe-X-qYMhW';
update content_bodies set title = 'Breathtaking Spots to Visit Before You Die', description = 'Mie Prefecture is a treasure trove of stunning views. Recommended locations include Bin-tama Road, Kanai Shrine, Nabana no Sato, and Umiterasu 14. There are many more amazing places to explore! Follow for more updates.' where id = 'tA9fiYXThnOWd4aX9xDqQ';
update content_bodies set title = '大丹倉【ドローン撮影】(熊野市)｜観光三重｜三重県の観光・旅行情報', description = '熊野市の指定文化財である大丹倉は、断崖上にそそり立つ高さ300ｍ、幅500ｍの大岩塊です。古来より修験道の行者たちが厳しい修行を重ねた聖地として知られています。岩肌の一部が赤みを帯びているのは、岩に含まれる鉄分が風化により酸化したためです。頂上からは紀伊山地の雄大な光景が広がり、訪れる人々を圧倒します。' where id = 'MFZYEUIZX8pTDOozp32lV';
update content_bodies set title = 'Oonigura (Drone Photography) | Kumano City | Mie Prefecture Tourism Information', description = 'Oonigura, a designated cultural property in Kumano City, is a massive rock formation standing 300 meters high and 500 meters wide on a cliff. It has been known as a sacred site where ascetics have practiced rigorous training since ancient times. The reddish hue on some parts of the rock surface is due to the oxidation of iron contained in the rock, caused by weathering. Standing at the top, one is overwhelmed by the magnificent view of the Kii Mountains that unfolds before them.' where id = 'W-cKrhX4FH56pwLHKxkYj';
update content_bodies set title = '宮川堤の桜【ドローン撮影】(伊勢市)｜観光三重｜三重県の観光・旅行情報', description = '「日本さくら名所100選」に選ばれている宮川堤の桜並木をドローンで撮影しました。宮川堤公園の南北にわたって続く「一目千本」と呼ばれる桜並木は、約1キロメートルにわたり美しい桜が楽しめる名所です。' where id = 'ZvyBuumW3Yk8zwopMPik1';
update content_bodies set title = 'Cherry Blossoms at Miyagawa Tsutsumi [Drone Footage] (Ise City) | Mie Prefecture Tourism', description = 'The cherry blossom trees along Miyagawa Tsutsumi, selected as one of Japan''s 100 Famous Cherry Blossom Spots, were captured using drone footage. The cherry blossom avenue, known as ''Ichimoku Senbon,'' stretches for one kilometer north and south through Miyagawa Tsutsumi Park, making it a renowned cherry blossom viewing location.' where id = '-lqoh_jXBVQxdOm4ak0XI';
update content_bodies set title = '女子会にピッタリ！大正ロマン漂うおいしい伝統体験', description = '大正時代に建てられた建物の喫茶スペースで、自分で点てるお抹茶セットを楽しむことができます。初めての方でも気軽にできるため、人気の体験です。癒しのレトロ庭園「六華苑」で、憧れの抹茶体験を味わえます。また、創業明治7年の老舗和菓子店「花乃舎」の和菓子がセットになっているのも嬉しいポイントです。この特別な体験を通じて、思い出に残るお出かけを楽しんでください。' where id = 'UDNPvg8Rf-8MH63XgEO-x';
update content_bodies set title = 'Perfect for Girls'' Night Out! Delicious Traditional Experience with Taisho Romance', description = 'Experience a delightful matcha-making session in a Taisho-era building''s cafe space. This popular activity is easy for beginners, allowing everyone to enjoy the dream of making their own matcha. The serene retro garden of Rokkaen adds to the charm. Additionally, the experience includes traditional Japanese sweets from Hananoya, a well-established confectionery shop founded in 1897. This combination makes for a memorable outing. Don''t miss the chance to create special memories during your visit!' where id = 'HtnuhunYLN50w5gl8VpQB';
update content_bodies set title = 'また行きたいが止まらない!!絶景４選', description = 'この絶景は実はすべて三重県にあります！おすすめの場所には金井神社、鵜倉園地、ビン玉ロード、なばなの里が含まれています。他にもたくさんの素晴らしいスポットがありますので、ぜひフォローしてチェックしてみてください！' where id = 'bWs2GNTH7tA8EX3EZU395';
update content_bodies set title = 'Four Breathtaking Spots You Can''t Stop Wanting to Visit Again!', description = 'All of these stunning views are actually located in Mie Prefecture! The recommended places include Kanai Shrine, Ukura Park, Bin-dama Road, and Nabana no Sato. There are many more great spots to explore! Follow for more updates!' where id = 'RhRzpRMx69XBBNl2jw_WK';
update content_bodies set title = '参拝客が絶えない！●●パワーが宿る 開運スポット', description = '安産や子育て、子授けの祈願をするなら子安観音寺が最適です。全国各地から参拝客が訪れるこの寺院では、白衣観世音菩薩が御本尊として祀られており、安産や子育てにご利益があるとされています。また、学業成就を願うための純木造三重の塔「智慧の塔」や、四季を通じて葉や花が絶えず、真冬にも花を咲かせる「不断桜」など、見どころが豊富です。詳細は公式ウェブサイトをご覧ください。' where id = 'GkSnCXVyyjMK9K1qk0uHP';
update content_bodies set title = 'A Never-Ending Stream of Worshipers! A Power Spot for Good Fortune', description = 'Koyasu Kannonji is a temple that attracts visitors from all over Japan, especially for prayers related to safe childbirth, child-rearing, and conceiving. The temple enshrines the white-robed Kanzeon Bodhisattva, known for its blessings in these areas. Additionally, visitors can explore the Tower of Wisdom, a pure wooden three-story pagoda dedicated to academic success, and the Fudanzakura, a cherry blossom tree that blooms throughout the seasons, even in winter. There are many attractions to see at this temple. For more details, visit their website.' where id = 'FlYhZ0XKKNuaTg3UPFH0s';
update content_bodies set title = '極上の休息を。三重県（短編）', description = '三重を訪れると、心は感動と安らぎで満たされます。歴史や文化が織りなす豊かな背景と、自然の恵みを活かした美食が揃っています。三重には多様な魅力があり、あなたを癒してくれることでしょう。心の求めに応じて、それぞれの特色ある地域を訪れてみてください。' where id = 'iQRx4Z0uDCnvdjsOUsrWi';
update content_bodies set title = 'Ultimate Relaxation in Mie Prefecture (Short Story)', description = 'Visiting Mie will fill your heart with emotion and tranquility. The region boasts a rich tapestry of history and culture, alongside abundant nature and exquisite cuisine that utilizes its blessings. Mie offers a variety of attractions that are sure to heal you. I encourage you to explore the distinct regions that cater to your heart''s desires.' where id = 'ovJaZODGTbmnsdSqrubdS';
update content_bodies set title = 'みえのイマココ旅　「自然」×「食」vol.2', description = '「みえのイマココ旅」は、三重の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。「自然」「歴史・文化」「伝統」「ものづくり」「食」「ナイト＆モーニング」「サスティナブル」をテーマに、50以上の体験プランを紹介し、予約が可能です。「自然」×「食」vol.2では、大紀町の大内山川での鮎友釣り体験や、紀北町の幻の牡蠣ツアーなど、三重県の自然と食を楽しむ特別な体験が紹介されています。動画では、熊野灘の海辺を巡るE-bikeツアーや、鮎釣り体験、桑名海苔を使った寿司作りのワークショップなどが登場します。' where id = 'ZJ5Bh6iD-qgVMrVWICCYZ';
update content_bodies set title = 'Mie Imakoko Travel: ''Nature'' x ''Food'' Vol.2', description = 'Mie Imakoko Travel invites visitors to experience unique aspects of Mie Prefecture, focusing on ''nature,'' ''history and culture,'' ''tradition,'' ''craftsmanship,'' ''food,'' ''night and morning,'' and ''sustainability.'' The special site features over 50 experiential plans that can be reserved, showcasing a new form of travel. The ''Nature'' x ''Food'' Vol.2 highlights special experiences such as a tour for fishing and eating sweetfish in the Ouchiyama River in Daiki Town and a tour to enjoy the legendary oysters grown in Kihoku Town. The video includes various spots like an E-bike tour along the Kumano-nada coast, a sweetfish fishing experience, and a sushi-making workshop using Kuwana nori.' where id = 'c19N0b4DGlz8Xhg16k-k9';
update content_bodies set title = '合掌民宿 与茂四郎', description = '合掌民宿与茂四郎は、富山県南砺市相倉395に位置しています。郵便番号は939-1915です。お問い合わせは0763-66-2377までどうぞ。詳細は公式ウェブサイトhttp://yomosirou.com/をご覧ください。' where id = '707gsxP96qMSKYcEb8kti';
update content_bodies set title = 'Gassho Minpaku Yomoshiro', description = 'Gassho Minpaku Yomoshiro is located at 395 Aikura, Nanto City, Toyama Prefecture, 939-1915, Japan. For inquiries, you can reach them at 0763-66-2377. More information can be found on their website: http://yomosirou.com/' where id = 'hQomtbdO9ziBBkcNBxi-X';
update content_bodies set title = '夜デートにオススメ！　#諏訪公園', description = '冬になると、四日市市の諏訪公園が約5万個の電球で美しく彩られ、幻想的な空間が広がります。公園中央の噴水に光が反射し、奥には国の登録有形文化財に指定された歴史的なレンガ造りの建物があります。近鉄四日市駅から徒歩5分の距離にあり、イルミネーションは無料で楽しめるのも魅力です。2024年の開催はバレンタインデーの2月14日までです。詳細はリンクをチェックしてください。' where id = 'RLEPfLBlhxZjE7hDo2-Gb';
update content_bodies set title = 'Recommended for a night date! Winter limited light park that you can enjoy for free', description = 'Suwa Park transforms into a winter wonderland with approximately 50,000 light bulbs illuminating the entire area. This popular winter attraction features a central fountain that reflects the lights, and a historic brick building designated as a nationally registered tangible cultural property adds to the enchanting atmosphere. Located just a 5-minute walk from Kintetsu Yokkaichi Station, visitors can enjoy the illuminations for free. The event runs until February 14, 2024, Valentine''s Day. For more details, visit the provided link.' where id = 'DvnvV6ev3BzrhBGFZBUFW';
update content_bodies set title = 'イベント情報紙「観光三重」96号特集　三重の美食', description = '三重県観光連盟が発行するイベント情報紙「観光三重」の96号では、三重県の美食に焦点を当てた特集が組まれています。この号では、三重の美味しい料理や飲食スポットが紹介されており、地域の魅力を伝える内容となっています。詳細については、観光三重の公式ウェブサイトをご覧ください。' where id = 'i_WebvaReh9zoRiKiFE5j';
update content_bodies set title = 'Event Information Paper ''Kankou Mie'' Special Issue 96: Mie''s Gourmet', description = 'The 96th issue of the event information paper ''Kankou Mie'', published by the Mie Prefectural Tourism Federation, features various spots that highlight the gourmet offerings of Mie Prefecture. For more details, please visit the Kankou Mie website.' where id = '9yCUNnk645eYAAlg48ah0';
update content_bodies set title = '一度は見たい！大迫力パノラマ　工場夜景の聖地', description = '三重県四日市市にある「うみてらす14」は、日本の5大工場夜景の一つで、最大の迫力を誇ります。高さ100mの四日市港ポートビルの最上階から、四日市コンビナートの工場夜景を一望できる展望展示室です。鈴鹿山脈や中部国際空港、臨海工業地帯も見渡せ、特に四日市コンビナートの夜景は「聖地」と称されています。おすすめの時間帯は、夕景から夜景へと移り変わるマジックアワーで、空の変化と工場の光が織りなす幻想的な景色を楽しめます。大切なひとときに訪れてみてはいかがでしょうか。' where id = 'DgyZPDp6EDM0RZnnS9TVL';
update content_bodies set title = 'A Must-See! Impressive Panorama - Sacred Place of Factory Night View', description = 'Umiterasu 14, located on the 14th floor of the Yokkaichi Port Building, offers one of Japan''s five major and most impressive factory night views. At a height of 100 meters, visitors can enjoy a panoramic view of the Yokkaichi Industrial Complex, which is often referred to as a ''sacred place.'' The observation room provides stunning views of the Suzuka Mountains, Chubu Centrair International Airport, and the coastal industrial area. The best time to visit is during the magic hour, when the sky transitions from sunset to night, creating a fantastic scene with the shimmering lights of the factories. It''s a perfect spot for a memorable moment.' where id = '0W3T49TPM-Z5EO9UtZJG2';
update content_bodies set title = 'レトロモダンなスイーツ店　#ニノマチストリートクッキー', description = 'ニノマチストリートクッキーは、築100年以上の町家をリノベーションしたスイーツテイクアウト専門店です。週3日だけの営業で、オシャレでモダンな空間が広がる店内では、おいしい焼き菓子やスイーツを楽しむことができます。情緒あふれる城下町にひっそりと佇むこの店は、約10cmのビッグサイズのクッキーが特徴で、伊賀の町を散策する際のお供にぴったりです。詳しくは公式ウェブサイトをご覧ください。' where id = 'SanVejNqL7-Z4-Rvu3Yt-';
update content_bodies set title = 'Retro-Modern Sweets Store - Ninomachi Street Cookie', description = 'Ninomachi Street Cookie is a takeout specialty store located in a renovated townhouse over 100 years old. Open only three days a week, this stylish and modern shop offers delicious baked goods and sweets. Nestled in a charming castle town, the store provides a unique atmosphere for visitors. The highlight is their large cookies, approximately 10cm in diameter, perfect for enjoying while exploring Iga town. For more details, visit their website.' where id = '0WbvailNZAP1n-wZCCS4J';
update content_bodies set title = '癒やしのレトロ庭園　#六華苑', description = '六華苑は、大正時代にタイムスリップしたかのような人気スポットです。華やかな洋館と重厚な和館が目を引き、豊かな自然に囲まれた庭園が広がっています。数々のドラマや映画のロケ地としても知られ、見どころがたくさんあります。国の重要文化財に指定されている洋館は、まさにハイカラな空間で、隠れたハートのモチーフを探す楽しみもあります。詳しくは公式サイトをご覧ください。' where id = 'nSii55tL2mvdewe04Hrdh';
update content_bodies set title = 'Healing Retro Garden - Rokkaen', description = 'Rokkaen is a popular spot that feels like a time travel back to the Taisho era. The garden features a stunning Western-style building and a grand Japanese-style building, surrounded by rich nature. Known as a filming location for various dramas and movies, Rokkaen offers many sights to explore. The Western-style building is designated as a national important cultural property and is a stylish space. A hidden heart motif can be found within, inviting visitors to search for it. For more details, visit their website.' where id = 'nW8eKddgzyaEH_5x-c1VP';
update content_bodies set title = 'ミシュランガイドも認めた！ヘルシー炭火田楽', description = '「田楽座 わかや」は創業200年以上の老舗で、ヘルシーな炭火田楽が楽しめるお店です。自家製豆腐に約1000日間熟成された味噌を塗り、炭火でじっくりと焼き上げることで、香ばしい香りが食欲をそそります。店内は高い天井と大きな梁があり、落ち着いた雰囲気が漂っています。豆腐田楽は朱塗りの木箱に並べられ、一口サイズで食べやすく、あっという間に食べられます。ご飯の上に乗せて食べるのがオススメです。詳しくはInstagramをチェックしてください。' where id = 'qN-vLUFE5dmMbeJ0I0J7N';
update content_bodies set title = 'Even the Michelin Guide recognized it! Healthy charcoal grilled dengaku', description = 'Dengakuza Wakaya is a historic restaurant with over 200 years of tradition, known for its healthy charcoal-grilled dengaku. The homemade tofu is coated with miso that has been aged for approximately 1000 days and grilled slowly over charcoal, creating a fragrant aroma that enhances the dining experience. The restaurant features a stylish interior with high ceilings and large beams, contributing to a cozy atmosphere. The tofu dengaku is served in bite-sized pieces in vermilion wooden boxes, making it easy to enjoy. The restaurant recommends placing the dengaku on rice for an enhanced flavor experience. For more details, visit their Instagram.' where id = 'Df11ZsHw8GndBMGd8HifF';
update content_bodies set title = '新フォトスポット！カラフルなお花の神社', description = '三重県にある新しいフォトスポット、カラフルなお花が浮かぶ花手水は、写真映えすること間違いなしです。広い境内には全部で5か所の花手水があり、毎月花の入れ替えが行われます。また、月替わりの伊勢型紙を使った御朱印も楽しめるポイントです。カメラを持って参拝するのにぴったりの場所です。なお、クリスマスバージョンの花手水はまもなく終了します。彌都加伎神社は三重県鈴鹿市東玉垣町1412に位置しています。' where id = 'mfW1DcqznvKY2q7S3eghL';
update content_bodies set title = 'New photo spot! Colorful flower shrine', description = 'This new photo spot in Mie Prefecture features a stunning flower hand washing area with colorful flowers floating on water, guaranteed to look great in photos. The shrine has five locations within its expansive grounds, and the flower arrangements change monthly. Visitors can also enjoy unique goshuin stamps made with Ise katagami paper, which are updated each month. It''s a perfect opportunity to visit the shrine with a camera in hand. Note that the Christmas version of the flower hand washing will be ending soon. The shrine is located at Mizugaki Shrine, 1412 Higashi Tamagakicho, Suzuka City, Mie Prefecture.' where id = '0ykeVEqv3eJY0LmchFxG1';
update content_bodies set title = '口の中でとろける松阪牛寿司', description = '伊勢市のおはらい町にある「ゑびや商人館」では、伊勢神宮参拝後に楽しめる松阪牛の肉寿司を提供しています。上質な脂が口の中でとろけるこの寿司は、トッピングを自由に組み合わせることができ、贅沢な食体験を楽しめます。三重県の美味しさと歴史を感じながら、特別な大人の旅を満喫してください。' where id = 'qx9VqGiEseSqLuDYCJ5bG';
update content_bodies set title = 'Matsusaka Beef Sushi that Melts in Your Mouth', description = 'Located in Oharai Town, Ise City, ''Ebiya Merchant Hall'' offers a delightful experience after visiting the Ise Grand Shrine. This restaurant features Matsusaka beef sushi, known for its high-quality fat that melts in your mouth. Guests can customize their sushi with various toppings, enhancing the luxurious dining experience. Enjoy the rich flavors and historical ambiance of Mie Prefecture while indulging in this gourmet treat.' where id = 'CcL5s-QAR9BtceLdAUCF5';
update content_bodies set title = 'レトロでフォトジェニックな街並み #東海道関宿', description = '三重県亀山市にある「東海道関宿」は、レトロでフォトジェニックな観光スポットです。かつては東海道五十三次の47番目の宿場町として栄え、現在は古民家をリノベーションしたお店が立ち並んでいます。ここでは、ランチやカフェでのんびり過ごしたり、街道まつりの賑わいを楽しんだりと、さまざまな楽しみ方ができます。カメラを片手に、タイムスリップしたようなひとときを楽しんでみてはいかがでしょうか。' where id = '3mkj1UskEhLdDCZXS5CYx';
update content_bodies set title = 'Retro and Photogenic Streetscape: Tokaido Sekijuku', description = 'Tokaido Sekijuku, located in Sekicho, Kameyama City, is a popular sightseeing spot in Mie Prefecture. Once a thriving post town on the Tokaido route, it now features shops housed in renovated old buildings. Visitors can enjoy various activities, such as leisurely lunches or relaxing at cafes, and experiencing the vibrant atmosphere during local festivals. This charming area offers a nostalgic journey, perfect for those looking to capture beautiful moments with their cameras. Explore the retro streets and immerse yourself in the history and culture of this unique destination.' where id = 'HCEF8cjkoLyfLm8mliJnU';
update content_bodies set title = 'ニセコサマーステイ', description = 'ニセコでのサマーステイの魅力を紹介します。美しい自然やアウトドアアクティビティが楽しめるニセコは、夏の訪問に最適な場所です。ニセコサマーステイの楽しさをぎゅっと詰め込んだ内容です。' where id = 'dV7dtvv8lGTOy22QhRSO_';
update content_bodies set title = 'NISEKO Summerstay', description = 'Experience the charm of NISEKO Summerstay! This description highlights the appeal of spending summer in Niseko, a popular destination known for its beautiful landscapes and outdoor activities.' where id = 'Q0N69RR3RO3YxE_vo8jRP';
update content_bodies set title = '神奈川の隠れた名所を巡る旅８選', description = 'この動画は神奈川県を訪れる際の参考として、さまざまな名所を紹介しています。動画に紹介されていないおすすめスポットがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を探求することを促しています。動画では、ヴェルニー公園、北鎌倉古民家ミュージアム、岩海岸、神奈川県立生命の星・地球博物館、日本民家園、箱根関所、瑞泉寺、洒水の滝の8つの隠れた名所が紹介されています。訪れる前に公式サイトで最新情報を確認することをお勧めします。' where id = 'rN_9WSd9lrE7L4fu4oWey';
update content_bodies set title = 'Hidden Gems of Kanagawa: 8 Must-Visit Spots', description = 'This video serves as a guide for those planning to travel to Kanagawa Prefecture, showcasing various notable attractions. If you have any recommendations that are not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. The video highlights eight hidden gems, including Verny Park, Kitakamakura Folk House Museum, Iwa Coast, Kanagawa Prefectural Museum of Natural History, Japan Open-Air Folk House Museum, Hakone Checkpoint, Zuiseiji Temple, and Shasui Falls. Viewers are advised to check official websites for the latest information before visiting.' where id = 'ExVa1FK8iO736WikS2-xC';
update content_bodies set title = '伊賀忍者になれるのは日本でココだけ！ #伊賀流忍者博物館', description = '伊賀市上野にある「伊賀流忍者博物館」は、日本で唯一、伊賀忍者になれる場所です。子供から大人まで大人気で、特に【からくり忍者屋敷】では隠し階段やどんでん返しなどの仕掛けがあり、忍者やくノ一が目の前で実演してくれます。お子様連れのご家族はもちろん、デートスポットとしてもおすすめです。三重県で憧れの忍者体験をしてみませんか？' where id = 'cLytSibrCGxykcUP1ahzw';
update content_bodies set title = 'Become an Iga Ninja Only Here in Japan! #IgaRyuNinjaMuseum', description = 'The Iga-ryu Ninja Museum in Ueno, Iga City, is the only place in Japan where you can become an Iga ninja. It is very popular among both children and adults. The Karakuri Ninja House features hidden stairs and trick doors, showcasing various tricks performed by ninjas and kunoichi right in front of you. This attraction is not only recommended for families with children but also serves as a great date spot. Experience your dream of becoming a ninja in Mie Prefecture!' where id = 'ZoHXome3oPDZkDGCSz-3E';
update content_bodies set title = '2025年度森の京都文化観光サポーターラジオ 第1回「盆踊り＆福知山踊振興会」', description = '京都FM丹波のラジオ番組「森の京都presents どぅゆの～？伝統文化 in 福知山」の放送音声です。前シリーズから2年を経て、アイルランド出身のカハルさんをレギュラーゲストに迎え、福知山市の無形文化財や伝統文化を取り上げます。第1回では、前半にカハルさんと福知山踊振興会会長の田村さんが世界の踊りと日本の踊りの違いについて語り、後半では田村会長が福知山踊りとの出会いや振興会での活動、今後の想いを語ります。' where id = 'cJbbjAx1Ziy575mYvNJLS';
update content_bodies set title = '2025 Forest Kyoto Cultural Tourism Supporter Radio Episode 1: Bon Odori & Fukuchiyama Dance Promotion Association', description = 'This is the audio broadcast of the radio program "Forest Kyoto presents Do You Know? Traditional Culture in Fukuchiyama" on Kyoto FM Tanba. Two years after the previous series "Do You Know? Traditional Culture in Fukuchiyama," this series features regular guest Cahill, originally from Ireland and now living in Fukuchiyama, who will discuss the city''s intangible cultural assets and traditional culture. In the first episode, the differences between world dances and Japanese dances are explored with Cahill and Mr. Tamura, the president of the Fukuchiyama Dance Promotion Association. The latter part of the episode features Mr. Tamura sharing his lifelong experiences with Fukuchiyama dance, his encounters with it, activities within the promotion association, and his future aspirations.' where id = 'ZUE2-ZdflD9GP1U06-ksu';
update content_bodies set title = '大杉谷渓谷：堂倉滝　ドローン映像（三重県大台町）｜観光三重｜三重県の観光・旅行情報', description = '大杉谷は日本三大渓谷の一つで、エメラルドグリーンの美しい秘境が多くの人々に人気を集めています。この映像は、堂倉滝をドローンで撮影したもので、動画は大台町地域おこし協力隊の井坂治氏が提供しています。大杉渓谷の詳細や三重県内の観光スポットについては、観光三重の公式サイトを訪れてください。' where id = 'SKEoecz-gCr3H__li3A49';
update content_bodies set title = 'Osugidani Valley: Doukurataki Waterfall Drone Footage (Odaicho, Mie Prefecture) | Kankomie | Mie Prefecture Tourism and Travel Information', description = 'Osugidani Valley is one of Japan''s three major valleys, known for its stunning emerald green scenery. This video showcases Doukurataki Waterfall captured by drone. The footage is provided by Haru Isaka, a member of the Odaicho Regional Revitalization Cooperation Team. For more information about Osugidani Valley and other tourist spots in Mie Prefecture, visit the official Kankomie website.' where id = 'SOTmRDJBQv2ZSjrj1eppx';
update content_bodies set title = '心・KAGAWA', description = 'この動画では、香川県のさまざまな個人や場所の協力を紹介しています。主なスポットには、総本山善通寺、特別名勝栗林公園、津田の松原、丸亀城、金刀比羅宮が含まれています。また、三木町の獅子舞やちょうさ祭りも取り上げられ、三木町と株式会社四国遍路の協力を得ています。動画の書道は、書道家の郷祥氏によって「真」「深」「心」「新」「浸」の文字が揮毫されました。各スポットのリンクと郷祥氏のSNSも紹介されています。' where id = 'p_l-4hF9mvjJNMV6jSldg';
update content_bodies set title = 'Heart of Kagawa', description = 'This video showcases the contributions of various individuals and locations in Kagawa Prefecture. Key sites featured include the Great Zen Temple Zentsuji, the Special Scenic Spot Ritsurin Garden, Tsuda no Matsubara, Marugame Castle, and Konpira Shrine. Additionally, the Shishimai dance from Miki Town and the Chousa Festival are highlighted, with support from Miki Town and Shikoku Henro Co., Ltd. The calligraphy for the video, featuring the characters ''Shin'', ''Deep'', ''Heart'', ''New'', and ''Immerse'', was created by calligrapher Goshow. Links to the respective sites and Goshow''s social media are provided.' where id = 'IjMoUQleZxp5TJJD6cX6U';
update content_bodies set title = '18 最後に', description = 'この動画は「18 最後に」というテーマについて紹介しています。' where id = 'EQkTtm34yTruQE6g9PG2A';
update content_bodies set title = '18 Finally', description = 'This video introduces the topic of ''18 Finally''.' where id = 'L2KbGlkxY_vBVTTONa-hS';
update content_bodies set title = '2024 第38回 NAHAマラソン', description = 'この動画では、沖縄の各地をのんびりと散歩しながら紹介しています。' where id = 'H7KXsRpwRsceMNQFopQCA';
update content_bodies set title = '2024 38th NAHA Marathon', description = 'This video introduces various locations in Okinawa while leisurely walking around.' where id = 'nYGdqKsYOhd47khvbtEIo';
update content_bodies set title = '沖縄観光 JAおきなわファーマーズマーケット『ゆんた市場』でお土産・弁当・惣菜・お菓子！ 読谷村 ♯316', description = '沖縄を訪れることは、県外・県内問わず難しいことがあります。この動画では、沖縄の美しい風景を楽しみながら、のんびりと散歩する気分を味わえます。ゆんた市場では、お土産や弁当、惣菜、お菓子などが揃っており、沖縄の魅力を紹介しています。ゆんた市場の公式ウェブサイトも掲載されており、詳細情報を得ることができます。沖縄の散策を通じて、その魅力を一緒に探求しましょう。' where id = 'koBAQmzb32GmYQyHUbIY_';
update content_bodies set title = 'Okinawa Tourism: JA Okinawa Farmers Market ''Yunta Market'' for Souvenirs, Bento, Side Dishes, and Snacks! Yomitan Village #316', description = 'Visiting Okinawa can be challenging for both locals and tourists. This video allows you to enjoy a leisurely stroll through the beautiful scenery of Okinawa. It introduces various parts of Okinawa while showcasing the Yunta Market, where you can find souvenirs, bento, side dishes, and snacks. The official website for Yunta Market is provided for more information. Join us in exploring Okinawa''s charm through this walking tour.' where id = 'otmVH5Yo8vEmJz-HR43O0';
update content_bodies set title = '大牧温泉観光旅館', description = '大牧温泉観光旅館は、富山県南砺市利賀村大牧44に位置しています。郵便番号は932-0371です。問い合わせは0763-82-5229までどうぞ。詳細は公式ウェブサイト（http://www.oomaki.jp/）をご覧ください。' where id = 'xbPMkzn67FUPnYtlauPgP';
update content_bodies set title = 'Oomaki Onsen Tourist Inn', description = 'Oomaki Onsen Tourist Inn is located at 44 Oomaki, Toga Village, Nanto City, Toyama Prefecture, 932-0371, Japan. For inquiries, you can contact them at 0763-82-5229. More information can be found on their website: http://www.oomaki.jp/' where id = '85488lL2l9qvbvsjzk5Mm';
update content_bodies set title = '料亭みや川（みやがわ）【福光】', description = '料亭みや川は、富山県南砺市福光1376に位置する日本料理店です。郵便番号は939-1610で、電話番号は0763-52-1072です。詳細については、公式ウェブサイト（http://ryoteimiyagawa.com/）をご覧ください。' where id = 'inilV_1pk1Dq7AW2CBLkZ';
update content_bodies set title = 'Miyagawa Restaurant (Miyagawa) [Fukumitsu]', description = 'Miyagawa Restaurant is located at 1376 Fukumitsu, Nanto City, Toyama Prefecture, 939-1610, Japan. For inquiries, you can reach them at 0763-52-1072. More information can be found on their website: http://ryoteimiyagawa.com/' where id = '53LaTS7gWodjnUBxXlHxo';
update content_bodies set title = '五箇山温泉 赤尾館', description = '五箇山温泉 赤尾館は、富山県南砺市西赤尾町396-1に位置しています。郵便番号は939-1977です。お問い合わせは0763-67-3321までどうぞ。詳細は公式ウェブサイト（https://akaokan.com/）をご覧ください。' where id = 'zPK3mc5uAr72-MjGGI41E';
update content_bodies set title = 'Gokayama Onsen Akaokan', description = 'Gokayama Onsen Akaokan is located at 396-1 Nishiakaomachi, Nanto City, Toyama Prefecture, 939-1977, Japan. For inquiries, you can contact them at 0763-67-3321. More information can be found on their website: https://akaokan.com/' where id = 'WOyYZ-g9vOC90e4zsnMTH';
update content_bodies set title = '合掌民宿 弥次兵衛（やじべえ）【五箇山】', description = '合掌民宿弥次兵衛は、富山県南砺市上梨592に位置しています。郵便番号は939-1914です。お問い合わせは0763-66-2639までどうぞ。詳細は公式ウェブサイト（https://yajibe-gokayama.amebaownd.com/）をご覧ください。' where id = 'DhM8oQdVNqT9y9j3Eu5FJ';
