update content_bodies set title = '#42 民宿 瑞峯（ずいほう）【利賀村】', description = '民宿 瑞峯は、富山県南砺市利賀村上百瀬748に位置しています。郵便番号は939-2513です。お問い合わせは0763-68-2458までどうぞ。詳細は公式ウェブサイト（http://www1.tst.ne.jp/toga3784/）をご覧ください。' where id = 'M7WKfVnORSX35xxUmIlu5';
update content_bodies set title = '#42 Minpaku Zuiho (Zuiho) [Toga Village]', description = 'Minpaku Zuiho is located at 748 Kamihyakuse, Toga Village, Nanto City, Toyama Prefecture, 939-2513, Japan. For inquiries, you can contact them at 0763-68-2458. More information can be found on their website: http://www1.tst.ne.jp/toga3784/' where id = 'XOyFQZSrDnEyr0HUcAGDv';
update content_bodies set title = '民宿 茂兵衛【利賀村】', description = '民宿 茂兵衛は、富山県南砺市利賀村長崎212に位置しています。郵便番号は932-0371です。お問い合わせは0763-82-5230までどうぞ。詳細は公式ウェブサイト（http://www.shokoren-toyama.or.jp/~toga/stay17.html）をご覧ください。' where id = 'oIwGkVnMTXvg3_s-CjILk';
