update content_bodies set title = '古民家の宿 おかべ', description = '古民家の宿おかべは、富山県南砺市利賀村長崎に位置する宿泊施設です。郵便番号は932-0371で、電話番号は0763-82-5229です。詳細については、公式ウェブサイト（http://okabe.main.jp/）をご覧ください。' where id = 'ta9WNeVX31doOOo_UIfnW';
update content_bodies set title = 'Okabe - Traditional Japanese Inn', description = 'Okabe is a traditional Japanese inn located in Nagasaki, Toga Village, Nanto City, Toyama Prefecture, with the postal code 932-0371. For inquiries, you can reach them at 0763-82-5229. More information can be found on their website at http://okabe.main.jp/' where id = 'miJj1zFyfOpD_KB9-62c6';
update content_bodies set title = '庄川峡の秘境 北原荘', description = '庄川峡に位置する北原荘は、富山県南砺市利賀村にある隠れた名所です。住所は〒932-0371 富山県南砺市利賀村北原1-17で、電話番号は0763-82-3741です。詳細については、公式ウェブサイト https://www.kitaharasou.com/ をご覧ください。' where id = '4aEo6c_IUGDR_ADdnbs8Z';
update content_bodies set title = 'Secret Spot of Shogawa Gorge: Kitahara-so', description = 'Kitahara-so is a hidden gem located in the Shogawa Gorge area of Toyama Prefecture, specifically in the village of Toga. The address is 1-17 Kitahara, Nanto City, Toyama 932-0371, and you can contact them at 0763-82-3741. For more information, visit their website at https://www.kitaharasou.com/' where id = 'GixrBMOxzSD5ihLzt1W2M';
update content_bodies set title = '城端別院善徳寺で腕輪念珠づくり　～仏様からの贈り物を身につけ疫病除け～　富山県南砺市', description = '越中の小京都・城端で、女子旅に最適な腕輪念珠づくり体験が楽しめるのが城端別院善徳寺です。この古刹は地域の人々の拠り所であり、疫病除けのための特別な腕輪念珠を作ることができます。さらに、豪商の土蔵群や縦格子の町並みを散策することで、日常の喧騒から離れ、心と身体を癒す時間を過ごせます。体験には本堂や加賀藩ゆかりの部屋の拝観も含まれており、文化的な体験ができます。詳細や予約は、提供されたリンクから確認できます。' where id = 'sQTlarWlC9hk6EEc9wlPA';
update content_bodies set title = 'Bracelet Bead Making at Jōban Betsuin Zentoku-ji: A Gift from Buddha to Ward Off Epidemics - Nanto City, Toyama Prefecture', description = 'Experience a unique women''s trip in Jōban, a small Kyoto in Etchu, by participating in the bracelet bead making experience at Jōban Betsuin Zentoku-ji, a historic temple that serves as a refuge for the local community. This one-of-a-kind experience allows you to create a protective bracelet bead, believed to ward off epidemics. In addition to this, visitors can explore the town''s charming old streets, featuring traditional merchant storehouses and lattice-patterned buildings, providing a perfect escape from daily hustle and bustle. The temple offers guided tours of its main hall and rooms associated with the Kaga clan, enhancing the cultural experience. For more details and reservations, visit the provided links.' where id = 'zxi6i1tgDcScKjyYDKhI5';
update content_bodies set title = '天空ミュージック10周年PV　音楽：小倉博和　映像：中野裕之', description = '「天空ミュージック」の10周年プロモーションビデオは、香川県高松市の屋島山上で2012年に始まりました。音楽は小倉博和が担当し、映像は中野裕之が手掛けています。小倉は多才なアーティストであり、ドキュメンタリーやミュージックビデオなど多くのプロジェクトに関わってきました。彼の作品には、べプ国際旗映画祭でグランプリを受賞した「SFSAMURAIFICTION」や「FLYING BODIES」が含まれています。また、ソロアルバム「GOLDEN TIME」や「Summer Guitars」をリリースし、FM COCOLOでラジオ番組も担当しています。このビデオは、音楽の美しさと四国の風景を祝うことを目的としています。' where id = '-TEdqEGxHjHuCBuUABlWm';
update content_bodies set title = '10th Anniversary PV of Sky Music - Music by Hirokazu Ogura, Video by Hiroyuki Nakano', description = 'The 10th anniversary promotional video for ''Sky Music'' features music by Hirokazu Ogura and visuals by Hiroyuki Nakano. The project began in 2012 atop Yashima Mountain in Takamatsu City, Kagawa Prefecture. Ogura, a versatile artist, has worked on various projects including documentaries and music videos, collaborating with notable Japanese musicians. His works include ''SFSAMURAIFICTION,'' which won the Grand Prix at the Beppu International Flag Film Festival, and ''FLYING BODIES,'' which also received accolades. Ogura has released several solo albums, including ''GOLDEN TIME'' and ''Summer Guitars,'' and has hosted a radio show on FM COCOLO. The video aims to celebrate the beauty of music and the scenic landscapes of Shikoku, Japan.' where id = 'lTxUcKvCMrkC_HYvL1akw';
update content_bodies set title = 'わかやま観光Short　～聖地リゾート！和歌山～', description = '和歌山は自然の美しさと文化的な重要性が融合した観光地です。聖地やリゾートが豊富で、リラックスと精神的な体験を求める旅行者を惹きつけます。ハッシュタグは、和歌山の観光に焦点を当てており、旅行先としての魅力を強調しています。' where id = '93yJFWiC0rSmUPZuWyhR8';
update content_bodies set title = 'Wakayama Tourism Short - Sacred Resort! Wakayama', description = 'Wakayama is a destination that offers a unique blend of natural beauty and cultural significance. Known for its sacred sites and resorts, it attracts travelers looking for both relaxation and spiritual experiences. The hashtags suggest a focus on tourism in Wakayama, highlighting its appeal as a travel destination.' where id = 'iYg8TGpT-Q_dZqmGMAvwC';
update content_bodies set title = 'ラベンダーフェスタかみふらの2022  ライティングアップ＆花火と牧野由依', description = '上富良野の夏を彩る新たなイベント「ラベンダーフェスタかみふらの2022」が開催されます。ラベンダーが上富良野町の花になってから41年が経ち、町民や日本全国、さらには海外の人々にも親しまれています。今年も夜間にラベンダーを楽しむことができる期間限定のイベントです。7月17日（日）には、上富良野産のホップや大麦を使用したビールを楽しむブースが1日限定で開設されます。幻想的なライティングで彩られたラベンダーの大パノラマを楽しむことができます。ただし、特任PR大使の牧野由依さんは都合によりミニライブに参加できないことが報告されています。' where id = 'UqFmYq0OQrjp6TL4APSFB';
update content_bodies set title = 'Lavender Festa Kamifurano 2022: Lighting up & Fireworks with Yui Makino', description = 'The Lavender Festa Kamifurano 2022 is a new summer event that celebrates the lavender flower, which has been the symbol of Kamifurano for 41 years. This event allows both locals and visitors from across Japan and abroad to enjoy the beauty of lavender at night for a limited time. On July 17th, a special booth will be set up for one day only, featuring beer made from locally sourced hops and barley. Attendees can experience a stunning panorama of lavender illuminated by enchanting lights. However, it has been announced that the special PR ambassador, Yui Makino, will not be able to attend her mini live performance due to scheduling conflicts.' where id = 'S3Tki5O_mt5Q4DZkQteJ_';
