update content_bodies set title = '神戸で平和を見つける', description = 'このプロジェクトは、関西国際空港、山陽電気鉄道、生田神社、まやビューラインなど、さまざまな貢献者への感謝を表現しています。キャストメンバーは、YouTubeやFacebookなどのソーシャルメディアを通じて神戸での体験を共有しています。特に蔡祥（ソニア・タイ）さんとユウジさんが、日本、特に神戸や兵庫での生活や冒険を記録しています。提供されたリンクは、彼らのプロフィールや紹介された組織に繋がり、神戸の美しさと文化を紹介しています。' where id = '99fOI5SCpglhHcWI0sleR';
update content_bodies set title = 'Find the PEACE in KOBE', description = 'This project expresses gratitude to various contributors, including Kansai International Airport, Sanyo Electric Railway, Ikuta Shrine, and Maya Viewline. The project features cast members who share their experiences in Kobe through social media platforms like YouTube and Facebook. Notable contributors include 蔡祥 (Sonia Thai) and Yuji, who document their lives and adventures in Japan, particularly in Kobe and Hyogo. The links provided lead to their respective profiles and the organizations mentioned, showcasing the beauty and culture of Kobe.' where id = 'vvW8Cv24_H830DkRJG9Uy';
