update content_bodies set title = 'I had a phone call from Japan🇯🇵Can you answer the phone？', description = 'This video discusses whether you would answer the phone if you received a call from Japan.' where id = '4jPgSCPKZvPUx_Y9VGz9c';
update content_bodies set title = '奄美群島 Amami Islands, Japan in 8K', description = '奄美群島は、鹿児島の南方380～580キロメートルに位置する8つの有人島から成り立っています。奄美大島、加計呂麻島、徳之島など、亜熱帯の自然に恵まれ、固有種や珍しい生き物が多く生息しています。各島には、ハブが生息する島やサンゴが隆起してできた島、世界的に有名な鍾乳洞が広がる島など、魅力的なポイントが豊富です。この動画では、奄美群島の美しい自然や文化的な重要性を強調しながら、各島の素晴らしいロケーションを紹介しています。' where id = '49PD3CEjLHv-qyRyd_PJ0';
update content_bodies set title = 'Amami Islands, Japan in 8K', description = 'The Amami Islands consist of eight inhabited islands located 380 to 580 kilometers south of Kagoshima. These islands, including Amami Oshima, Kakeroma Island, and Tokunoshima, are rich in subtropical nature and home to many unique and rare species. Each island offers distinct attractions, such as the presence of habu snakes, islands formed by coral uplift, and impressive limestone caves. The video showcases various stunning locations across the islands, highlighting their natural beauty and cultural significance.' where id = 'ghveRZRw2FtThHRYFD_Hw';
update content_bodies set title = '下呂温泉で遊ぶスポット紹介♪ Autumn&Winter【long ver.】025', description = '下呂温泉では、秋から冬にかけて楽しめる多彩なアクティビティが用意されています。紅葉や花火、雪遊びなど、温泉だけではない下呂市の魅力を紹介するプロモーション動画です。動画では、巌立峡や滝巡り、ミネラルハンティングツアー、地元の酒造り体験など、地域の様々な体験が紹介されています。また、紅葉ライトアップや下呂温泉花火ミュージカルといった季節のイベントも取り上げられています。この動画を通じて、寒い季節に下呂が提供するユニークな魅力を発見していただければと思います。' where id = 'DU4IRq-FtDOaDGfFxL7BN';
update content_bodies set title = 'Introducing Fun Spots in Gero Onsen♪ Autumn&Winter【long ver.】025', description = 'Gero offers a variety of activities to enjoy during autumn and winter, including viewing autumn leaves, fireworks, and snow activities. This promotional video showcases the charm of Gero City, emphasizing that it is more than just a hot spring destination. The video features various experiences in the area, such as visiting Gandate Gorge, exploring waterfalls, participating in mineral hunting tours, and enjoying local sake brewing. Additionally, it highlights seasonal events like the autumn leaves illumination and the Gero Onsen fireworks musical. The video invites viewers to discover the unique attractions and experiences that Gero has to offer throughout the colder months.' where id = '5hwMNo0yXMu2a67Q05BR6';
update content_bodies set title = '下呂温泉', description = '下呂温泉は飛騨川のそばに位置し、哲学者林羅山によって日本三名泉の一つと称されています。彼は徳川家康を含む四人の将軍に仕え、室町時代の京都五山の禅僧でもありました。下呂の温泉街は美しい山村の風景が広がり、観光地として魅力的です。観光名所には、しらさぎ緑地公園や森山神社のしだれ桜、そして水明館やしょうげつなどの旅館があり、訪れる人々は自然の美しさと文化的な遺産を楽しむことができます。' where id = '9QA3tbcFbefrn7EVgVuyE';
update content_bodies set title = 'Gero Hot Springs', description = 'Gero Hot Springs, located alongside the Hida River, is renowned as one of Japan''s top three hot springs, a title attributed to philosopher Razan Hayashi, who served four shoguns, including Ieyasu Tokugawa, during the Muromachi era. The area is characterized by its picturesque hot spring mountain village, making it a popular tourist destination. Visitors can explore various attractions, including Shirakagi Green Park, Moriyama Shrine''s weeping cherry blossoms, and several ryokans such as Suimeikan and Shogetsu. Gero Hot Springs offers a unique blend of natural beauty and cultural heritage, appealing to both relaxation seekers and history enthusiasts.' where id = 'mXgWtyirRDaObz2q1JPgr';
update content_bodies set title = '夜晩游4k中文30秒', description = '奄美大島では、エコツーリズムの一環を体験することができます。この動画は『夜観（夜晩游）』というタイトルです。' where id = 'lu5eXLQjvGkjGsjK_V0m1';
update content_bodies set title = 'Night Tour 4K Chinese 30 Seconds', description = 'In Amami Oshima, you can experience part of eco-tourism. This video is titled ''Night Viewing (夜晩游)''.' where id = 'L8lfDOLmFTKYfx61K5J8L';
update content_bodies set title = '日本の品格、栃木', description = '栃木県は、日本の品格を静かに保ち続ける場所です。荘厳な文化と豊かな自然が調和し、訪れる人々の心を温めます。「The Grace of Japan, TOCHIGI」というフレーズは、この地域が文化遺産と自然の美しさを守り続ける姿勢を表しています。心の豊かさを満たす体験ができる栃木県は、日本の美意識を深く理解するための特別な機会を提供します。' where id = 'Mb6GeSgZeCB2GNABaHXmN';
update content_bodies set title = 'The Grace of Japan, TOCHIGI', description = 'Tochigi Prefecture embodies the grace of Japan, characterized by its serene nature and rich historical culture. Visitors can experience the majestic landscapes and deep-rooted traditions that define this region. The phrase ''The Grace of Japan, TOCHIGI'' reflects the area''s commitment to maintaining its cultural heritage and natural beauty, offering a unique opportunity for personal enrichment and appreciation of Japan''s aesthetic values.' where id = 'f1EOuniN-JvwiiuZb7gfU';
update content_bodies set title = '3秒で保存したくなる高山グルメ！高山駅から徒歩2分創業40年以上の老舗「中華そば郷里」', description = 'この動画では、高山の美味しいグルメを紹介しています。' where id = 'lHdVvr3E_nwmYH3SrdatP';
update content_bodies set title = 'Delicious Takayama Cuisine You Want to Save in 3 Seconds! ''Chuka Soba Gori'' - A Long-Established Restaurant Just 2 Minutes from Takayama Station, Established Over 40 Years Ago', description = 'This video introduces Takayama''s gourmet food.' where id = '6z4r0F5V7XL3EBW_3PY2w';
update content_bodies set title = '【LIVE CAMERA】アルプス展望公園スカイパーク #飛騨高山', description = '岐阜県高山市に位置する「アルプス展望公園スカイパーク」では、市街地や飛騨山脈の美しい眺望を楽しむことができます。この公園は高山駅から徒歩約20分の距離にあり、芝生広場や周囲の歩道が整備されており、軽スポーツやウォーキングを楽しむのに適した場所です。' where id = 'Lkt4Cm_GbzOdfxTqomrFz';
update content_bodies set title = 'LIVE CAMERA: Alps View Park Sky Park #Hida Takayama', description = 'Located in Takayama City, Gifu Prefecture, the Alps View Park Sky Park offers views of the city and the Hida Mountains. The park is about a 20-minute walk from Takayama Station and features a grassy area and walking paths, making it an ideal spot for light sports and walking.' where id = 'WvCMMj2B4nqGjz4OV8Wnn';
update content_bodies set title = '大盛況の「#氷点下の森」は2月末まで！', description = 'この動画では、大盛況の「#氷点下の森」について紹介しています。氷点下10度の冬の自然を逆手に取り、制作された氷の森は、昼間に太陽の光を浴びて美しい純白の氷を楽しむことができます。' where id = '7yjS_pVPlTyE19rWqcqm6';
update content_bodies set title = 'The Popular ''#Frozen Forest'' Runs Until the End of February!', description = 'This video introduces the highly successful ''#Frozen Forest,'' which creatively utilizes the winter nature at minus 10 degrees Celsius. Visitors can enjoy the beauty of pure white ice illuminated by sunlight during the day.' where id = 'omrIXPgRRy3lvJSOuVgm-';
update content_bodies set title = 'ReVIEW! #飛騨高山　一之宮町', description = '飛騨一之宮観光協会会長の稲子盛雄さんが、一之宮町の魅力を紹介します。一之宮町は高山市の南部に位置し、歴史と伝統が息づく地域です。美しい自然に囲まれ、環境を活かした農業体験や地元の人々とのふれあいが楽しめるグリーンツーリズムが盛んな場所です。特に、飛騨一宮水無神社は飛騨で最も格式高い神社とされ、地域の人々に敬われています。また、内閣府認定のどぶろく特区や、樹齢1,100年の臥龍桜、分水嶺が見られる位山の散策、ウィンタースポーツなど多彩な体験ができます。ぜひ一之宮町にお越しください。高山市街地から車で約20分です。' where id = 'BB9OvdLmGoq43EjmQEmSd';
update content_bodies set title = 'ReVIEW! #Hida Takayama Ichinomiya Town', description = 'Morio Inako, the chairman of the Hida Ichinomiya Tourism Association, introduces the charms of Ichinomiya Town, located in the southern part of Takayama City. This area is rich in history and tradition, surrounded by beautiful nature, making it a popular destination for green tourism. Visitors can engage in farming experiences and interact with locals. The Hida Ichinomiya Mizunashi Shrine, regarded as the most prestigious shrine in Hida, is a significant site of worship for the local community. Additionally, the town features the Cabinet Office-certified Doburoku Special Zone, the 1,100-year-old Garyu Cherry Tree, scenic walks on Mt. Iyama with its watershed, and opportunities for winter sports. Ichinomiya Town is just a 20-minute drive from downtown Takayama.' where id = 'CA_BCymgpTEyb2_nBTFqQ';
update content_bodies set title = 'ReVIEW! #飛騨高山　高根町', description = '飛騨高根観光協会会長の小坂守さんが高根町の魅力を紹介します。高根町は高山市の南東に位置し、乗鞍岳と御嶽山を望む自然に囲まれた高地です。長野県木曽地域に隣接しており、歴史や文化に木曽の影響を色濃く受けているため、飛騨の中でも異郷の地として知られています。高根町は木曽馬の産地としても有名で、馬の供養のための石仏には人と馬の物語が込められています。また、発酵食品に力を入れており、廃校を再利用したウイスキー蒸溜所が注目を集めています。塩を使わず乳酸菌で漬けた「すな」や、飛騨の郷土料理に使われる田舎味噌も盛んに作られています。涼しい夏と寒冷な冬の環境が、これらの発酵食品の育成に役立っています。その他にも火畑そばやタカネコーン、野麦峠や御嶽山など多くの見どころがあります。ぜひ高根町にお越しください。高山市街地から車で約50分です。' where id = 'Ry3LboUOCpqyrigbkpN2u';
update content_bodies set title = 'ReVIEW! #Hida Takayama Takane Town', description = 'Mamoru Kosaka, chairman of the Hida Takane Tourism Association, introduces the charms of Takane Town, located southeast of Takayama City. Surrounded by nature and overlooking Mt. Norikura and Mt. Ontake, Takane is influenced by the nearby Kiso region of Nagano Prefecture, making it a unique area within Hida. Known for its production of Kiso horses, the town features stone Buddha statues that tell stories of the bond between people and horses. Takane is also focusing on fermented foods, with a whiskey distillery repurposed from an abandoned school gaining attention. Other local specialties include suna, pickled with lactic acid bacteria, and country miso, commonly used in Hida cuisine. The region''s cool summers and cold winters support the production of these foods. Takane Town offers various attractions, including Hibata Soba, Takane Corn, Nomai Pass, and Mt. Ontake. Visitors are encouraged to explore this unique destination, just 50 minutes by car from Takayama city center.' where id = 'W1IFA8Gmd8Smlpt-Zs5zp';
update content_bodies set title = 'ReVIEW! #飛驒高山　丹生川町', description = '千光寺の住職、大下真海さんが丹生川町の魅力を紹介します。丹生川町は高山市の北東部に位置する山岳地域で、日本百名山の一つである乗鞍岳が象徴です。標高3,000ｍの山ですが、2,702ｍの畳平までバスでアクセスできるため、子どもや女性でも気軽に山の世界を体験できます。7月から8月中旬には、バスターミナル近くに天空のお花畑が広がり、希少な高山植物を観察できます。運が良ければ天然記念物のライチョウにも出会えるかもしれません。乗鞍岳の裾野には五色ヶ原の森や、日本一高い観光鍾乳洞である飛騨大鍾乳洞など、多様な見どころがあります。丹生川町は、神社巡りや豊かな田園風景も楽しめる場所です。高山市街地から車で約15分、畳平から山頂までは徒歩約90分です。' where id = 'zr4fZFOGIJva4lBnw_Fma';
update content_bodies set title = 'ReVIEW! #Hida Takayama Nyukawa Town', description = 'Chief priest Mami Oshita of Senkoji Temple introduces the charm of Nyukawa Town, a mountainous area in the northeastern part of Takayama City. The town is symbolized by Mt. Norikura, one of Japan''s 100 famous mountains. Visitors can take a bus to Tatamidaira at 2,702 meters, making it accessible for children and women to experience the mountain environment. From July to mid-August, a beautiful flower field appears near the bus terminal, showcasing rare alpine plants, and there’s a chance to see the natural monument, the grouse. Attractions include Goshikigahara Forest at the foot of Mt. Norikura, the Hida Great Limestone Cave, and the rich rural scenery of the area. Nyukawa Town offers a variety of experiences, including shrine visits and local legends. It is about a 15-minute drive from downtown Takayama and a 90-minute walk from Tatamidaira to the summit of Mt. Norikura.' where id = 'XOpiQjThQSzmLM5CjfD5M';
update content_bodies set title = 'ReVIEW! #飛騨高山　一之宮町', description = '飛騨一之宮観光協会会長の稲子盛雄さんが、一之宮町の魅力を紹介します。一之宮町は高山市の南部に位置し、歴史と伝統が息づく地域です。美しい自然に囲まれ、環境を活かした農業体験や地元の人々とのふれあいが楽しめるグリーンツーリズムが盛んです。特に、飛騨一宮水無神社は飛騨で最も格式高い神社とされ、地域の人々に敬われています。また、内閣府認定のどぶろく特区や、樹齢1,100年の臥龍桜、分水嶺が見られる位山の散策、ウィンタースポーツなど多彩な体験ができます。ぜひ一之宮町にお越しください。高山市街地から車で約20分です。' where id = 'kVkC5iPPuVGWuXqjOP9rv';
update content_bodies set title = 'ReVIEW! #Hida Takayama Ichinomiya Town', description = 'Morio Inako, the chairman of the Hida Ichinomiya Tourism Association, introduces the charms of Ichinomiya Town, located in the southern part of Takayama City. This area is rich in history and tradition, surrounded by beautiful nature, making it a popular destination for green tourism. Visitors can engage in farming experiences and interact with locals. The Hida Ichinomiya Mizunashi Shrine, regarded as the most prestigious shrine in Hida, is a significant site of worship for the local community. Additionally, the town features the Cabinet Office-certified Doburoku Special Zone, the 1,100-year-old Garyu Cherry Tree, scenic walks on Mt. Iyama with its watershed, and opportunities for winter sports. Ichinomiya Town is just a 20-minute drive from downtown Takayama.' where id = '9fqA-GC2HgcwMbCXgObzn';
update content_bodies set title = 'アルコピアひまわり園', description = '「アルコピアひまわり園」は、約20万本のひまわりが鮮やかな黄色で彩る美しい場所です。一斉に咲き誇るひまわりの姿は圧巻で、見ごろは8月11日頃から始まります。期間中は、ジャンボしゃぼん玉やトランポリン、キッチンガーデンなどの楽しい催しが行われ、夏らしい写真を撮るのに最適なスポットです。2023年8月5日から20日までの期間中に訪れることができ、来場者には約300円の美化整備協力金の寄付がお願いされています。岐阜県高山市に位置し、中部縦貫自動車道路高山ICから車でアクセス可能です。' where id = 'n4qQYPFdKnziPhWRGD-9p';
update content_bodies set title = 'Alcopia Sunflower Garden', description = 'The Alcopia Sunflower Garden is a stunning display of approximately 200,000 sunflowers blooming in vibrant yellow. This breathtaking sight attracts visitors, especially during the peak viewing period starting around August 11th. The garden also hosts various fun activities, including jumbo soap bubbles, trampolines, and kitchen gardens, making it an ideal spot for summer photos. The event runs from August 5th to 20th, 2023, and visitors are encouraged to contribute a beautification maintenance donation of about 300 yen per person. The garden is located in Takayama City, Gifu Prefecture, and is accessible by car from the Chubu Jukan Expressway Takayama IC.' where id = '2_Z8CYNCPJgGtmVGMXLo_';
update content_bodies set title = '南小国町観光プロモーションビデオ', description = '南小国町の観光プロモーションビデオで、黒川温泉が有名です。このビデオでは、温泉を通じて日本の伝統的な生活に触れることができることを紹介し、温泉だけでなく町全体を楽しむことを訪問者に促しています。' where id = 'qsGaTBZbyPOq5x7XHCHOe';
update content_bodies set title = 'Minamioguni Tourism Promotion Video', description = 'This is a tourism promotion video for Minamioguni, a town known for its Kurokawa Onsen. The video highlights the opportunity to experience traditional Japanese life through its hot springs, while also encouraging visitors to explore the town beyond just its famous onsen.' where id = 'd9DSCZfxVF9byDl2LSuIh';
update content_bodies set title = '【田舎に泊まろう】サステナブルな暮らし - 熊野を1泊2日で旅する 前編｜元アイドルが田舎暮らしを体験｜熊野｜地方移住｜サステナブル', description = '元アイドルの池山智瑛さんが三重県御浜町を1泊2日で旅します。初日は、74歳のシンデレラが運営する体験型ゲストハウスに宿泊し、釜戸でご飯を炊き、囲炉裏を囲んで、五右衛門風呂などのサステナブルな田舎暮らしを体験します。2日目は、世界遺産の熊野古道、風伝峠を歩く旅です。御浜町や地元の特産品についての詳細は、提供されたリンクを参照してください。' where id = 'jpRx13SCs3geZ-N-hCFcE';
update content_bodies set title = 'Sustainable Living in the Countryside - A 1-Night, 2-Day Trip to Kumano Part 1 | Former Idol Experiences Rural Life | Kumano | Regional Migration | Sustainability', description = 'Former idol Tomoe Ikeyama embarks on a 1-night, 2-day journey to Mihama Town in Mie Prefecture. On the first day, she stays at a hands-on guesthouse run by a 74-year-old ''Cinderella,'' where she cooks rice using a traditional kamado, enjoys time around an irori (hearth), and experiences sustainable rural living with a goemon bath. The second day features a trek along the Kumano Kodo, a UNESCO World Heritage site, specifically the Fuden Pass. For more information about Mihama Town and its local products, including the premium sake ''Oroshi,'' visit the provided links.' where id = '318R1olywCOMge2lwEIAO';
update content_bodies set title = '【週末ルーティーン】手間を楽しむ -  焚き火篇｜理想の田舎暮らし｜ていねいな暮らし｜熊野｜地方移住｜サステナブル', description = '都会での生活では「手間を惜しんで」生きていましたが、熊野に移住してからは「手間を楽しむ」生活に変わりました。三重県御浜町での田舎暮らしの一端を紹介します。友人の猟師からもらったジビエの燻製を作り、お気に入りのワインを楽しみます。熊野杉で焚き火をし、熊野杉の香りが漂うお酒を味わいながら、熊野の山深くへ旅するような夜を過ごします。このような「手間を楽しむ」暮らし方を教えてくれた友人たちに感謝しています。' where id = 'oArGzR7i2BCBcDgPxP2cl';
update content_bodies set title = 'Weekend Routine: Enjoying the Effort - Bonfire Edition | Ideal Rural Living | Careful Living | Kumano | Regional Relocation | Sustainable', description = 'In the past, while living in the city, I lived by avoiding effort. However, after moving to Kumano, my lifestyle has transformed into one that enjoys effort. This is a glimpse into my rural life in Mihama, Mie Prefecture. I make smoked game given to me by a hunter friend and enjoy my favorite wine. I have bonfires with Kumano cedar and savor drinks infused with the scent of Kumano cedar, experiencing nights that feel like a journey deep into the mountains of Kumano. I am grateful to the friends here who have taught me this way of enjoying effort.' where id = 'zkES0XYtqetseRt5llBay';
update content_bodies set title = '美里の森キャンプ場', description = '美里の森キャンプ場ガーデンプレイスは、美里町にある静かな湖畔のキャンプ場です。ガーデンプレイスは、日本最長のジップスライドを備えたフォレストアドベンチャー美里に隣接しており、大人も子供も自然の中で遊び、共に過ごすことができます。宿泊施設にはロッジ、バンガロー、テントがあり、Wi-Fiも完備されているため、初めての方でも快適に過ごせます。この観光PR動画は2025年に制作されました。' where id = 'cjZoSKRX-aget6Ldw0UJP';
update content_bodies set title = 'Misato no Mori Campground', description = 'Misato no Mori Campground Garden Place is a serene lakeside campsite located in Misato Town. The campground is next to Forest Adventure Misato, which features Japan''s longest zip slide, providing fun for both adults and children. Visitors can enjoy nature together, with options for lodging in lodges, bungalows, and tents. The site is equipped with Wi-Fi, ensuring a comfortable experience even for first-time campers. This tourism PR video was created in 2025.' where id = 'H9wiHNH8npgu5c7X9tlCL';
update content_bodies set title = '熊本県美里町観光PR動画', description = '令和5年度に作成された美里町の観光PR動画です。美里町の魅力を伝えるために制作され、地域の観光資源や文化を紹介しています。' where id = 'toygxoHgbGYbM0ysagT4d';
update content_bodies set title = 'Kumamoto Prefecture Misato Town Tourism PR Video', description = 'This is a tourism PR video for Misato Town created in the fiscal year 2023.' where id = '6t2_scmYsdhFk5HOUUTY9';
update content_bodies set title = '大川テラッツァ（大川市観光・インテリア情報ステーション）', description = '大川テラッツァは、匠人の町である大川市に新たに誕生した観光拠点です。この施設では、大川の有名な家具産業に関する情報を提供しています。訪れる人々は、この地域で作られる独自の家具について学び、体験することができます。大川テラッツァは現在オープンしており、大川の豊かな伝統と職人技を発見するために、皆様をお待ちしています。' where id = 'GvVz6yQGj6-wF1q2YVh6v';
update content_bodies set title = 'Okawa Terrazza (City Tourism and Interior Information Station)', description = 'Okawa Terrazza is a new tourism hub located in the artisan town of Okawa. It serves as a center for information about Okawa''s renowned furniture industry. Visitors can explore and learn everything about the unique furniture crafted in this area. The station is now open and invites everyone to discover the rich heritage and craftsmanship of Okawa furniture.' where id = '_xWz74pICKDkZXJS1YPcs';
update content_bodies set title = '江戸時代のまぼろしの酒「まひ鶴」', description = '2016年4月23日と24日に開催された「第17回小保・榎津 藩境まつり」では、江戸時代のまぼろしの酒「まひ鶴」が復活しました。この酒は、イベント限定で提供され、江戸時代の伝統を感じさせる特別な存在として注目を集めました。' where id = 'Eud2-G7f2uNsYGUNS1oas';
update content_bodies set title = 'The Illusory Sake of the Edo Period: Mahitsuru', description = 'On April 23 and 24, 2016, the ''17th Obō and Enokizu Domain Boundary Festival'' featured the revival of ''Mahitsuru,'' a legendary sake from the Edo period, available exclusively during the event.' where id = 'KvnTHDDAl0uVkRTCW1jMD';
update content_bodies set title = '高松ミュージックブルーフェス2021スペシャル　with サンポートオータムジャム2021（延期開催）PV VO2  「DAY BY DAY」', description = '「高松ミュージックブルーフェス」は2011年に始まり、瀬戸内を代表する音楽フェスとして毎年5月のGWに開催されています。2021年のフェスは2度の延期を経て、2022年3月に開催予定です。会場は瀬戸内海の心地よい風が吹く「サンポート高松エリア」で、ゲストミュージシャン5組と地元ミュージシャン32組の計37組が出演します。テーマは「FREE AS A BIRD」で、自由に歌うことを促しています。プロモーション映像では、ウィリアムス浩子さんと松丸契さんの素晴らしい演奏が紹介されています。フェスは3月20日と21日にJR高松駅前広場やサンポート高松多目的広場で行われ、地元とゲストのミュージシャンが出演します。主催は「MUSIC BLUE TAKAMATSU 実行委員会」です。' where id = '5cGlzoLtW1b5RGYOvdVmr';
update content_bodies set title = 'Takamatsu Music Blue Fest 2021 Special with Sanport Autumn Jam 2021 (Postponed) PV VO2 ''DAY BY DAY''', description = 'The Takamatsu Music Blue Fest, which started in 2011, is a prominent music festival in the Setouchi region, typically held during the Golden Week in May. The 2021 festival was postponed twice and is now scheduled for March 2022 at the pleasant Sanport Takamatsu area by the Seto Inland Sea. The event will feature 37 acts, including five guest musicians and 32 local musicians, under the theme ''FREE AS A BIRD,'' encouraging participants to sing freely like birds. The promotional video showcases performances by Hiroko Williams and Kei Matsumaru, who visited Takamatsu to create a beautiful musical experience. The festival will take place on March 20 and 21, 2022, at various locations, including JR Takamatsu Station and Sanport Takamatsu Multipurpose Square, featuring both local and guest musicians. The event is organized by the MUSIC BLUE TAKAMATSU Executive Committee, which includes various local organizations.' where id = 'qudr5EkBSV042efcgAwlA';
update content_bodies set title = '真っ白な熊野と雪の中のみかん', description = '三重県御浜町の聖地・熊野に訪れ、初めて見る雪は手間がかかるものの、真っ白な町はいつもとは違ったワクワク感をもたらします。雪に覆われた風景は、普段とは異なる魅力を感じさせてくれます。' where id = 'Ws1cpeGUiUCf6rBxD-cmz';
update content_bodies set title = 'Snow quietly falls in Kumano and the oranges in the snow', description = 'In Kumano, a sacred place in Mie Prefecture, the first snowfall brings both challenges and excitement. The town, covered in white, creates a thrilling atmosphere that is different from usual.' where id = '2hlwCt8ko7jPm4-sH27U5';
update content_bodies set title = '【おすすめのカフェ】田舎で見つけたお気に入りのカフェ｜熊野｜地方移住｜サステナブル｜ビーガン', description = '2020年7月、東京から三重県御浜町に移住しました。久々の休みの日に、御浜町尾呂志にあるお気に入りのカフェ「ここからかふぇ」でゆっくりランチを楽しみました。このカフェは先輩移住者が運営しており、地元の野菜やお米を使ったヴィーガン定食や、神戸でパン屋を営んでいたマスターの焼きたてパンが味わえます。素材の味を活かしたシンプルで奥深い料理は、東京ではなかなか味わえないクオリティです。マスターとの会話は、私たちの理想とする田舎での暮らしについて考えるきっかけとなりました。今年1月から移住先を探し始め、コロナの影響で訪問が難しくなる中、運命的に出会った御浜町に移住を決断しました。熊野は「よみがえりの地」として知られ、深い精神的な歴史を持つ場所です。' where id = 'FX0dVayWV9QQWfsu2Yj5K';
update content_bodies set title = 'Recommended Cafe: My Favorite Cafe Found in the Countryside | Kumano | Rural Relocation | Sustainable | Vegan', description = 'In July 2020, I relocated from Tokyo to Mihama Town in Mie Prefecture. On my day off, I visited my favorite cafe, ''Koko Kara Cafe,'' located in Oroshi, Mihama Town, for a relaxing lunch. This cafe, run by a fellow migrant, offers vegan meals made from local vegetables and rice, along with freshly baked natural yeast bread from the master who previously owned a bakery in Kobe. The simple yet profound dishes highlight the flavors of the ingredients, providing a quality rarely found in Tokyo. Conversations with the master prompted me to reflect on my ideal rural lifestyle. After starting my search for a relocation spot in January, I managed to visit Mihama and the surrounding areas just before the COVID-19 restrictions began. Despite the challenges of not being able to visit other locations afterward, I decided to move to Mihama, a town I had only briefly visited, believing that continuing my search would delay my relocation for years. Kumano, known as the ''land of resurrection,'' has a rich spiritual history and is a place where many find a renewed sense of purpose.' where id = 'V7rvPxFxRZ-mfbMWDi3CY';
update content_bodies set title = '中野BC株式会社', description = 'この動画は中野BC株式会社について紹介しています。' where id = 'aS3oVm7W9seOx7Uqtersv';
update content_bodies set title = 'NAKANO BC Corporation', description = 'This video introduces NAKANO BC Corporation.' where id = 'QbmZlxAntfMOSJvIQBmBW';
update content_bodies set title = '御食国　～歴史に愛された美味がある。～　京都・淡路島コース', description = 'この動画では「御食国　～歴史に愛された美味がある。～　京都・淡路島コース」について紹介しています。日本の伝統的な料理や食文化がどのように歴史に根ざしているのかを探求し、特に京都と淡路島の美味しい食材や料理に焦点を当てています。' where id = '6asICLbYdoq2_kTHx48WC';
update content_bodies set title = 'Royal Food of Japan', description = 'This video introduces the ''Royal Food of Japan: A Culinary Heritage Loved by History - Kyoto and Awaji Island Course.''' where id = 'r_257oUV47LkO-N6lo1H3';
update content_bodies set title = '独占的な探検、関西日本 - 滋賀[4K]', description = '三井寺は比叡山の山麓に位置し、琵琶湖を望む場所にあります。平安時代の朝廷によって祈願所として設立された四大寺院の一つです。寺院区域内には40以上の建物があり、650件以上の国宝や重要文化財が保存されています。1300年にわたり、三井寺はこれらの文化資産を守り続けており、長吏や僧侶たちはその重責を命がけで担っています。' where id = 'Tb51fcNCSV9NszcRKsfwE';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan - Shiga[4K]', description = 'Mii-dera, located at the foot of Mount Hiei and facing Lake Biwa, is one of the four major temples established by the Heian period court for prayer. Within its temple complex, there are over 40 buildings that house more than 650 national treasures and important cultural assets. For 1,300 years, Mii-dera has been dedicated to preserving these cultural assets, a responsibility that the temple''s head priest and monks take very seriously, often risking their lives to protect this heritage.' where id = 'b5lRKntD7UFnnBfLbO-wP';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Fukui[4K]', description = 'この動画では、福井県で1500年以上の伝統を持つ越前和紙の手作り技術が紹介されています。第9代の職人、岩野市兵衛氏は人間国宝として認められ、世界中で最高の和紙を製造しています。越前和紙の文化体験に関する詳細情報や、製紙技術とその遺産についての洞察が提供されています。文化体験や行程についての詳細は、提供されたリンクを訪れてご確認ください。' where id = 'x0a4CL79TbWQim8jV2Lsj';
update content_bodies set title = 'Exclusive Expeditions, KANSAI Japan -Fukui[4K]', description = 'The video highlights the traditional craft of Echizen washi, a type of Japanese paper that has been handmade in Fukui Prefecture for over 1500 years. The 9th generation craftsman, Iwano Ichibei, recognized as a Living National Treasure, produces some of the finest washi in the world. The video provides insights into cultural experiences related to this craft, showcasing the unique techniques and heritage involved in washi production. For more details on the cultural experience and itinerary, visit the provided links.' where id = '_6WqG0dNtURUrVSEgO3sb';
update content_bodies set title = 'スピリチュアル関西、侘び寂び', description = '関西、日本の美しい日本庭園を訪れ、正式な着物を着て、茶道を体験することができます。また、関西に残る古くてシンプルな家々が点在する村を訪れることも可能です。シンプルなものの中に秩序と敬意を見出し、古いものの中に純粋な美を感じる瞬間が「侘び寂び」を体感させてくれます。古き良き日本の雰囲気は、静けさ、誠実さ、純粋さ、自然や人々への敬意に満ちています。関西は、完璧さの中の不完全さを真に体験できる場所です。' where id = '_Fy0dSu6uyO8vkXYQkE81';
update content_bodies set title = 'Spiritual KANSAI, Wabi Sabi', description = 'Experience the serene beauty of Kansai, Japan, where traditional aesthetics come to life. Visitors can explore beautiful Japanese gardens, don formal kimonos, and engage in the art of tea preparation. The region is home to quaint villages featuring old, simple homes that embody the essence of ''wabi-sabi''—finding beauty in imperfection and simplicity. The atmosphere of old Japan is characterized by tranquility, honesty, and a deep respect for nature and one another. In Kansai, one can truly appreciate the harmony and purity that define this spiritual region, where the principles of ''wa-kei-sei-jaku'' (harmony, respect, purity, and tranquility) are celebrated.' where id = 'AwYAlVjIB7mE_pwD8S30I';
update content_bodies set title = '買い物編', description = 'このコンテンツは、日本、特に関西地域での買い物を探求することを読者に促しています。関西について詳しく学ぶための専用ガイドへのリンクや、さらなる交流や最新情報のためのFacebookやInstagramのリンクが提供されています。' where id = 'hUezFUZKnJh5tmHPSI0ka';
update content_bodies set title = 'Let''s go Shopping in Japan', description = 'This content invites readers to explore shopping in Japan, particularly in the Kansai region. It provides links to learn more about Kansai through a dedicated guide, as well as social media platforms like Facebook and Instagram for further engagement and updates.' where id = 'bZp_eRFV-Q9ZokOMyGu9B';
update content_bodies set title = '雪国に滞在する - 雪国でしか体験できない価値「里山・ローカルガストロノミー・温泉」', description = 'この文章は、雪国でのユニークな体験と持続可能な価値について述べており、主に「里山」「ローカルガストロノミー」「温泉」の三つの側面に焦点を当てています。里山は、自然と調和した伝統的な農村風景を指し、持続可能な生活様式を垣間見ることができます。ローカルガストロノミーは、地域の食材や料理の伝統を強調し、雪国の文化や環境を反映しています。温泉は、リラクゼーションだけでなく、地域の地熱資源とのつながりも提供します。これらの要素が組み合わさることで、訪問者にとって豊かで持続可能な体験が生まれます。' where id = 'Qjor9LcCb2q0EVjxWgfrp';
update content_bodies set title = 'Staying in the snow country - Sustainable value of Snow country "Satoyama, local gastronomy, Onsen"', description = 'This text highlights the unique experiences and sustainable values found in snow country, focusing on three main aspects: Satoyama, local gastronomy, and Onsen. Satoyama refers to the traditional rural landscape that harmonizes with nature, offering a glimpse into sustainable living practices. Local gastronomy emphasizes the use of regional ingredients and culinary traditions that reflect the culture and environment of the snow country. Onsen, or hot springs, provide not only relaxation but also a connection to the natural geothermal resources of the area. Together, these elements create a rich and sustainable experience for visitors.' where id = 'bnO_wkGPLh_WbO43yWepc';
update content_bodies set title = 'シェリーウイーク - 雪国でしか体験できない価値「里山・ローカルガストロノミー・温泉」', description = 'シェリーウイークは、雪国における独自の体験と持続可能な価値を強調するイベントであり、「里山」やローカルガストロノミー、温泉に焦点を当てています。このイベントでは、地域の豊かな文化遺産や自然の美しさが紹介され、これらの伝統を守るための持続可能な実践の重要性が強調されます。参加者は、土地とその資源に深く結びついた地元の料理を探求し、地域の温泉の癒しの効果を楽しむことができます。' where id = 'G8f2gWiQpPxr1VHg_vpRm';
update content_bodies set title = 'Sherry Week - Sustainable value of Snow country ''Satoyama, local gastronomy, Onsen''', description = 'Sherry Week highlights the unique experiences and sustainable values found in the Snow country, focusing on the concepts of ''Satoyama'', local gastronomy, and Onsen. This event showcases the rich cultural heritage and natural beauty of the region, emphasizing the importance of sustainable practices in preserving these traditions. Participants can explore the local cuisine, which is deeply connected to the land and its resources, while also enjoying the therapeutic benefits of the region''s hot springs.' where id = '3K17-glcIEp1ax260jd6_';
update content_bodies set title = '松之山ダイニング - 雪国でしか体験できない価値「里山・ローカルガストロノミー・温泉」', description = '松之山ダイニングは、雪国の持続可能な価値を体験できるユニークな場を提供します。「里山」やローカルガストロノミー、温泉の癒しの効果に焦点を当てており、訪れる人々は地域の豊かな文化と自然遺産に浸ることができます。地元の食材や伝統的な慣習の重要性を示すこのダイニング体験は、特別なものです。' where id = 'TcC-ZQkaCv0fAi2Lh2fjn';
update content_bodies set title = 'Matsunoyama Dining - Sustainable value of Snow country "Satoyama, local gastronomy, Onsen"', description = 'Matsunoyama Dining offers a unique experience that highlights the sustainable values of the Snow country. It focuses on the concepts of ''Satoyama'', local gastronomy, and the therapeutic benefits of Onsen. This dining experience allows visitors to immerse themselves in the rich cultural and natural heritage of the region, showcasing the importance of local ingredients and traditional practices.' where id = 'luF0iDLUEjz2mSvnwlB3r';
update content_bodies set title = 'SHERRY WEEK IN 松之山温泉', description = '2021年11月11日、新潟県十日町市の松之山温泉でシェリーウイークのイベントが開催されました。この温泉は、現代アートのブラックシンボルを通じて、スペインのシェリーブランドであるオズボルネ社との深い関係があります。イベントでは、地域とシェリーブランドとの文化的なつながりが強調され、地元の伝統と国際的な影響が融合した独自の魅力が紹介されました。' where id = 'dENUM40VT8pTO-Uto_UXb';
update content_bodies set title = 'SHERRY WEEK IN MATSUNOYAMA', description = 'On November 11, 2021, the Sherry Week event took place at Matsunoyama Onsen in Tokamachi, Niigata Prefecture. This onsen has a significant connection with Osborne, a leading sherry brand from Spain, through the black symbol of contemporary art. The event highlighted the cultural ties between the region and the sherry brand, showcasing the unique blend of local tradition and international influence.' where id = 'TDZ2vOxJwtAf-IDFh2W8a';
update content_bodies set title = 'ねぷたまつり２０１９', description = 'ねぷたまつり２０１９の様子を紹介します。' where id = 'VvOkMdGEKSwaMMk5oYwSd';
update content_bodies set title = 'Hirosaki Neputa Festival 2019', description = 'This is an overview of the Hirosaki Neputa Festival 2019.' where id = 'vq4KBc4DlY6HBmhfPI-iP';
update content_bodies set title = '鎌倉', description = '鎌倉は、時を楽しむことができる街です。1人で訪れた narrator は、孤独を感じつつも散歩を楽しみます。祠や鳥居、歴史を刻んだ建物、不思議な竹林に出会い、わくわくする気持ちが湧き上がりますが、やはり寂しさも感じます。しかし、電車に乗ると、誰かと一緒だと景色が違って見えることに気づきます。2人でいることで、楽しさが増し、今日は楽しい一日となりました。ここから、彼らの旅が始まります。' where id = 'ymHQbh1UctPLDDquesSaY';
update content_bodies set title = 'Kamakura', description = 'Kamakura is a city where one can enjoy the passage of time. Visiting alone, the narrator experiences a mix of solitude and joy while strolling through the streets. They encounter shrines, torii gates, and buildings that tell stories of the past, as well as a mysterious bamboo grove. Although the excitement of exploration is palpable, a sense of loneliness lingers. However, upon taking the train, the narrator realizes that the experience changes when shared with someone else. The scenery appears different when there are two people, making the day enjoyable. This marks the beginning of their journey together.' where id = '7R8MjsSqoBCnqbCii6Gya';
update content_bodies set title = '夕焼けに輝く 散歩道', description = '三重県にあるビン玉ロードは、夕焼けの際に美しく輝く散歩道です。夜になるとライトアップされ、幻想的な雰囲気を醸し出します。三重県は絶景が豊富で、観光客にとって魅力的なスポットがたくさんあります。この地域の素晴らしい景色をぜひフォローして見てみてください。' where id = '8C9txKo-exGPfZwFVjGlM';
update content_bodies set title = 'Promenade Shining in the Sunset', description = 'Bindama Road, located in Mie Prefecture, is a picturesque walking path that shines beautifully during sunset. At night, it is illuminated, creating a magical atmosphere. Mie Prefecture is known for its breathtaking views, making it a treasure trove for tourists. Visitors are encouraged to follow and explore the stunning sights of this region.' where id = 'sxf8wisVAPdguU8afOe4d';
update content_bodies set title = '世界にひとつだけ 花お守り', description = '「世界にひとつだけ 花お守り」は、毎月8日のみ彌都加伎神社で手に入る特別なお守りです。この可愛らしいお守りは、インド刺繍が施されており、見た目だけでなく意味も持っています。彌都加伎神社がある三重県は、絶景が豊富な観光地として知られており、旅行者にとって魅力的なスポットです。お守りや三重の美しい景色についての情報は、@mizugakijinjaをフォローしてチェックしてください。' where id = 'LNxhB9rXDXq_rrJN5uUQA';
update content_bodies set title = 'Unique Flower Amulet', description = 'The Unique Flower Amulet is available only on the 8th of each month at Mizugaki Shrine. This charming amulet features beautiful Indian embroidery and is designed to be both cute and meaningful. Mie Prefecture, where the shrine is located, is known for its stunning views and is a great destination for travelers. Follow @mizugakijinja for more information and updates about this special amulet and the beautiful sights in Mie.' where id = 'k1U_J7KAM96KH7FrvhOZO';
update content_bodies set title = '受験に”勝つ”！　#勝速日神社', description = '受験生必見の勝速日神社は、三重県鈴鹿市に位置する必勝祈願の神社です。「勝＝Victory」「速＝Speed」「日＝Rising Sun」といった縁起の良い漢字が並び、勝運の神様が祀られています。全国から合格祈願に訪れる人々が絶えません。最寄りの近鉄白子駅から徒歩3分の距離にあり、鳥居をくぐると雰囲気が一変し、灯籠が並ぶ参道と緑に囲まれた境内が心を癒してくれます。勝負の前にはぜひ立ち寄ってみてください。' where id = 'Svjdo7jTEFaTtjknMvdn3';
update content_bodies set title = 'Win the Exam! #Katsuhayahi Shrine', description = 'A must-visit for examinees, Katsuhayahi Shrine in Suzuka City, Mie Prefecture, is a hidden gem for victory prayers. The shrine''s name translates to auspicious kanji: ''Victory'', ''Speed'', and ''Rising Sun'', embodying the god of victory and luck. People from across the country visit to pray for success in their exams. Just a three-minute walk from Kintetsu Shirako Station, the atmosphere transforms as you pass through the torii gate, leading to a serene path lined with lanterns and surrounded by lush greenery. It''s a perfect spot to visit before any important match or exam!' where id = 'PSSV1QI6pvOoK0CQx_CEO';
update content_bodies set title = '開運を導く神様が宿る！　#椿大神社', description = '「椿大神社」は、古くから「椿さん」と親しまれている日本最古の神社で、開運の神様である猿田彦大神を祀っています。多くの人々が交通安全や無病息災、商売繁昌を祈願しに訪れます。参道は木々に囲まれ、神聖な雰囲気が漂っています。冬には境内で椿の花が咲き誇り、四季折々の自然美も楽しめます。また、境内には縁結びの神社や恋愛成就のパワースポットもあり、新年の始まりに参拝したい場所です。' where id = 'eQzphoEn_iGSrbMMEfqNC';
update content_bodies set title = 'A god who guides good luck dwells! Power spot', description = 'Tsubaki Shrine, affectionately known as ''Tsubaki-san'', is Japan''s oldest shrine located in a forest. It enshrines Sarutahiko Okami, the god of good luck, where many visitors pray for traffic safety, good health, and prosperous business. The approach to the shrine is lined with trees, creating a sacred atmosphere. In winter, camellia flowers bloom throughout the grounds, showcasing the natural beauty of the changing seasons. Additionally, the shrine features a matchmaking shrine and a power spot for love fulfillment, making it a desirable place to visit at the start of a new year.' where id = 'xz80I8hhfnI3nR5rOi2pc';
update content_bodies set title = '海外リゾート顔負けの自然とアクティビティ。伊勢志摩を遊びつくす新しい観光のカタチ', description = '伊勢志摩は、抜けるような青空と吸い込まれそうな紺碧の海、美味しい食事、マリンスポーツをはじめとした多彩なアクティビティを提供する新しい観光地として注目されています。これらの要素が組み合わさり、今までにない観光スタイルを生み出しています。開放的なスペースで自然の美しさとアクティビティを存分に楽しむことができ、冒険とリラクゼーションを求める旅行者にとって理想的な場所となっています。' where id = 'hthER65sjbsfvvVBZ4cg9';
update content_bodies set title = 'A New Style of Tourism in Ise-Shima: Nature and Activities Rivaling Overseas Resorts', description = 'Ise-Shima is emerging as a new tourist destination that offers breathtaking blue skies, deep blue seas, delicious food, and a variety of activities, including marine sports. This location combines all these elements to create a unique tourism experience that utilizes something unprecedented. The area promises an open space where visitors can fully enjoy the natural beauty and engaging activities, making it a perfect getaway for those seeking adventure and relaxation.' where id = 'LW3-Zbb2fl671JhOYUz7L';
update content_bodies set title = '近鉄レールパスアニメーション', description = 'このコンテンツでは、三重県の魅力や特徴を紹介しています。' where id = 'rMAc_C-h2wbBJY9iS7Leh';
update content_bodies set title = 'KINTETSU RAIL PASS Animation', description = 'This content introduces Mie Prefecture, highlighting its attractions and features.' where id = 'kqCKipxRu1SHaxQZGl-P_';
update content_bodies set title = '（Full ver.）Magical Journey Fukushima 02  - A New Leaf, A New Day -', description = '「水」をテーマに、源流から海へとたどる旅を通じて、福島の名産である美味しい水から作られた日本酒や農産物、温泉などの魅力を紹介します。また、現地の方々のこれまでの取り組みや思い、検査の状況を通じて、安全性についても伝えます。' where id = 'Z7QxCrSKboXKoUJDNAcLy';
update content_bodies set title = 'Magical Journey Fukushima 02 - A New Leaf, A New Day', description = 'This project explores the theme of ''water,'' tracing its journey from the source to the sea. It highlights the appeal of Fukushima''s local specialties, including sake made from delicious water, agricultural products, and hot springs. The initiative also shares the efforts and thoughts of local residents, as well as information about safety measures and testing.' where id = 'ZeHezsaHT9wtYugGuX_7x';
update content_bodies set title = '（Full ver.）Magical Journey Tohoku - A New Leaf, A New Day -【ゆりやんレトリィバァさんと行く東北旅】', description = '全長1,000キロの「みちのく潮風トレイル」を巡り、景勝地や日本でも有数のカキ産地など、外国人観光客からも注目を集める人気のスポットを通して、現地の魅力や人々の取組、思いを伝えます。' where id = 'KpcN1Od9FpF_bSzkg6lQ-';
update content_bodies set title = 'Magical Journey Tohoku - A New Leaf, A New Day - A Trip to Tohoku with Yuriyan Retriever', description = 'This journey covers the Michinoku Coastal Trail, spanning 1,000 kilometers, showcasing scenic spots and renowned oyster production areas that attract foreign tourists. The program aims to convey the local charm, the efforts of the people, and their heartfelt stories.' where id = 'YT3U-Po2joEo4N5ECcfof';
update content_bodies set title = '【田舎の隠れた物語】熊野灘の伊勢海老漁師親子の1日に密着', description = '御浜町の七里御浜から見る海の美しさを紹介し、日々変化する海の色について触れています。漁師の知人から船上での海の体験を誘われ、親子で伊勢海老を漁る漁師の日常に密着します。また、御浜町についての詳細や、ふるさと納税を通じて伊勢海老を購入する方法についてのリンクも提供されています。読者にはコメントやいいね、チャンネル登録を促し、インスタグラムのフォローも呼びかけています。' where id = '20CIqaPhKRCLycEPL0Tw8';
update content_bodies set title = 'A Hidden Story in the Countryside: A Day in the Life of a Lobster Fishing Father and Son in Kumano', description = 'This piece highlights the beauty of the sea viewed from Shichiri Mihama in Mihama Town, where the ocean''s colors change daily. The author shares an invitation from a fisherman friend to experience the sea from a boat, focusing on the daily life of a father and son who fish for spiny lobsters. The article also provides links to learn more about Mihama Town and options for purchasing the lobsters through hometown tax donation sites. Readers are encouraged to engage with the content through comments, likes, and subscriptions, and to follow the author''s new Instagram account.' where id = 'uoCjoZFLKpSg-uLMuAWWL';
update content_bodies set title = '世界で最も美しい藤の庭【あしかがフラワーパーク 2021】 | 4K', description = 'この動画では、2021年のあしかがフラワーパークにおける藤の花の美しさを紹介しています。藤（フジ）は日本文化において重要な花であり、日本人は桜だけでなく藤も愛していることを強調しています。' where id = 'V6ogK6GFBN20rESJ3Ijsn';
update content_bodies set title = 'The World''s Most Beautiful Wisteria Garden【Ashikaga Flower Park 2021】 | 4K', description = 'The video showcases the stunning beauty of wisteria flowers at Ashikaga Flower Park in 2021. It highlights the significance of wisteria, also known as Fuji in Japanese culture, emphasizing that Japanese people cherish these flowers just as much as cherry blossoms.' where id = 'fvE4WWDCWbYrgZJ9OIJNQ';
update content_bodies set title = '栃木の春を8Kで体験 - 日光・那須', description = 'この動画では、栃木県の美しい春の風景を紹介しています。あしかがフラワーパークの大藤や、真岡市の桜並木、宇都宮城址公園の河津桜などが登場します。また、栃木市立文学館や那須の篠工芸、野木町の煉瓦窯、うなぎの名店「魚登久」も紹介されています。さらに、龍門の滝や焼森山のミツマタ群生地、中禅寺湖の美しい景色も収められています。詳細は栃木観光のウェブサイトをご覧ください。' where id = 'y-Tg4DMFVcbwma5BZi089';
update content_bodies set title = 'Tochigi Japan in 8K - Nikko/Nasu', description = 'This video showcases the beauty of Tochigi, Japan, featuring stunning locations such as the Big Wisteria at Ashikaga Flower Park, cherry blossom roads in Moka City, and the Kawazu cherry blossoms at Utsunomiya Castle Ruins Park. Other highlights include the Tochigi City Literature Museum, Nasu Bamboo Craft, Nogi Town Brick Kiln, and the famous grilled eel at Uotoku. The video also captures the scenic Ryumon Falls, the Yakemoriyama Oriental Paper Bush, and Lake Chūzenji. For more information, visit the Tochigi tourism website.' where id = 'DJTuzuBF0VJAE4crmWdq1';
update content_bodies set title = '栃木の8K映像 - 日光・那須', description = 'この映像は、栃木県の日光と那須の美しい風景や観光名所を8K解像度で紹介しています。明智平展望台、華厳滝、いろは坂、鬼怒川温泉などの名所が登場します。また、那須高原の自然美や殺生石、中禅寺湖、日光東照宮、蔵の街などの文化的なスポットも取り上げられています。映像は、映像監督・編集の栄川幸、撮影の松村隆、空撮の馬場基成によって制作されています。' where id = '5sCWyDfoWRLlAyfeTEd9u';
update content_bodies set title = 'Tochigi Japan in 8K - Nikko and Nasu', description = 'This video showcases the stunning landscapes and attractions of Tochigi, Japan, captured in 8K resolution. Key locations featured include Akechidaira Observatory, Kegon Falls, Irohazaka, and various hot springs like Kinugawa Onsen. The video also highlights the natural beauty of Nasu Kogen, including Sesshoseki and Lake Chuzenji, as well as cultural sites such as Nikko Toshogu Shrine and the historic Kura-no-machi Old Town. The film is directed and edited by Yuki Eikawa, with photography by Takashi Matsumura and aerial shots by Motonari Baba.' where id = 'ducinx0b7WjcrgQg1bKEQ';
update content_bodies set title = 'KITA ECHIGO Sake Tourism – 日本の隠れた宝石', description = 'KITA ECHIGO Sake Tourismは、日本の本質を示し、風景や地域の自然資源を活用する地元の人々の調和の取れた生活を強調しています。米の栽培から塩の収穫まで、地域の自然と共生する様子が描かれています。この映像は、賑やかな都市を超えた本物の体験を求める人々にアピールし、日本のあまり知られていない一面を明らかにしています。酒は地域の文化、技術、風味を表し、菊水は醸造者の努力と誇りを体現しています。新発田と北新潟を訪れることで、酒の歴史に深く浸り、醸造への理解が深まります。この映像は、2023年の日本世界観光映画祭とART & TUR国際観光映画祭で受賞しました。' where id = 'j1X252ZOowPcUqjY6TB-x';
update content_bodies set title = 'KITA ECHIGO Sake Tourism – Japan’s Hidden Gem', description = 'KITA ECHIGO Sake Tourism showcases the essence of Japan, highlighting its landscapes and the harmonious lifestyle of locals who utilize the region''s natural resources, from rice cultivation to salt harvesting. This film reveals a lesser-known side of Japan, appealing to those seeking an authentic experience beyond the bustling cities. Sake represents the culture, craftsmanship, and flavors of the region, with Kikusui embodying the dedication and pride of its brewers. A visit to Shibata and North Niigata offers a deep dive into the history of sake, fostering a greater appreciation for the brewing process. The film has received accolades at the Japan World''s Tourism Film Festival 2023 and the ART & TUR International Tourism Film Festival 2023.' where id = 'vXusswsY0h1j2FUakDAix';
update content_bodies set title = '栃木の夏 - 日光・那須を8Kで', description = 'この動画では、栃木県の美しい風景を8K解像度で紹介しています。主な見どころには、鬼怒川ライン下り、茶臼岳、鹿の湯、蔵の街、益子焼、大谷資料館、日光東照宮、北温泉、華厳滝などがあります。動画は、映像監督・編集の栄川幸、写真撮影の松村隆、空撮の馬場基成によって制作されています。栃木についての詳細は、提供されたリンクを訪れてください。' where id = 'rMOAyWLTJ7JdBd9QtPHsN';
update content_bodies set title = 'Tochigi Japan in 8K - Nikko and Nasu', description = 'This video showcases the beauty of Tochigi, Japan, featuring stunning locations in 8K resolution. Key highlights include the Kinugawa River Boat Tour, Mt. Chausu, Shika-no-yu hot springs, the historic Kura-no-machi Old Town, Mashiko Ware pottery, the Nikko Toshogu Shrine, Kita Onsen, Kegon Falls, and the Oya History Museum. The video is directed and edited by Yuki Eikawa, with photography by Takashi Matsumura and aerial photography by Motonari Baba. For more information about Tochigi, visit the provided links.' where id = 'smrNPtkndY03ODfuuC0wc';
update content_bodies set title = '冬の栃木、日本の8K映像', description = 'この動画は、栃木県の冬の美しい風景を紹介しています。明智平展望台、いろは坂、華厳滝、中禅寺湖、那須高原など、さまざまな名所が映し出されています。また、日本酒の仕込みや地元の温泉、日光東照宮などの文化的なスポットも見ることができます。栃木の自然と文化の美しさを強調したこの動画は、この地域を探求したい人々にとって、完璧な視覚的旅となっています。' where id = '6s0MTzS0G7404dd7K1K3d';
update content_bodies set title = 'Winter Tochigi Japan in 8K', description = 'This video showcases the stunning winter landscapes of Tochigi, Japan, featuring various iconic locations. The footage includes the Akechidaira Observatory, Irohazaka, Kegon Falls, Lake Chuzenji, and Nasu Kogen, among others. Viewers can also see traditional Japanese sake brewing, local hot springs, and cultural sites like the Nikko Toshogu Shrine. The video highlights the beauty of Tochigi''s nature and culture, making it a perfect visual journey for those interested in exploring this region.' where id = 'V8ZWI3hZ8sqSlBcpeUsKX';
update content_bodies set title = '【兵庫県赤穂市PR動画】Ako Onsen,Japan「Feel Ako Time」', description = '赤穂温泉から見える美しい瀬戸内の水平線を背景に、赤穂の自然、歴史、文化、グルメを体感できるPR動画です。日常と非日常が交錯する、ゆったりとした旅の時間を想起させる映像が特徴です。ここでしか味わえない体験が待っていますので、ぜひご覧ください。' where id = 'FN2XRuyD71TYfb6rYkgn8';
update content_bodies set title = 'Ako Onsen, Japan ''Feel Ako Time''', description = 'The promotional video for Ako City, Hyogo Prefecture, showcases the beautiful horizon of the Seto Inland Sea as seen from Ako Onsen. It invites viewers to experience the nature, history, culture, and cuisine of Ako. The visuals evoke a sense of leisurely travel, blending the ordinary with the extraordinary, suggesting that this destination may offer both familiar and unique experiences. Be sure to watch!' where id = 'HooX7gdZF_2xREdwPoCWD';
update content_bodies set title = '道東凍冬，一起凍冬趣（外篇)', description = 'この記事では、台湾女子の北海道生活を紹介し、特に道東地域の神秘的な美しさに焦点を当てています。愛努族との出会いや自然体験が強調されており、阿寒湖でのカヌー、ファットバイク、スノーモービルなどのアクティビティが紹介されています。また、文化ガイドやJR花咲線の風景を楽しむこともできると述べられています。この冬のワンダーランドでのユニークな体験が強調され、北海道の自然美と文化の豊かさが紹介されています。' where id = 'nfmhE1OyxmlbWCEM0ZCaO';
update content_bodies set title = 'Frozen Winter in Eastern Hokkaido: A Fun Experience', description = 'This article explores the life of a Taiwanese woman in Hokkaido, Japan, particularly in the eastern region. It highlights the mysterious beauty of Hokkaido, including encounters with the Ainu culture and experiences in nature. The article features various locations such as Lake Akan, where visitors can engage in activities like canoeing, fat biking, and snowmobiling. It also mentions cultural guides and scenic train rides along the Hanasaki Line. The content emphasizes the unique experiences available in this winter wonderland, showcasing the natural beauty and cultural richness of Hokkaido.' where id = 'ZJ_NsWFravDsFlwLRTub3';
update content_bodies set title = '湯畑', description = 'この動画では、湯畑について紹介しています。湯畑は草津温泉のシンボルであり、温泉の魅力を伝える重要な存在です。' where id = 'm9d8JjZj-AQ8g9ZO6FSnc';
update content_bodies set title = 'Yubatake -Symbol of KusatsuOnsen-', description = 'This video introduces Yubatake, the symbol of Kusatsu Onsen.' where id = 'QoCPU7SQY3V6VJ0zp2yJc';
update content_bodies set title = '西の河原公園', description = 'この動画では、西の河原公園の四季折々の美しい景色を紹介しています。公園は、春の花々、夏の緑、秋の紅葉、冬の雪景色と、四季それぞれの魅力を楽しむことができる場所です。自然の変化を感じながら、訪れる人々に癒しを与える公園の魅力を伝えています。' where id = '8K3uwfYtHDaWShG1oH2To';
update content_bodies set title = 'Sainokawara Park -Scenery of the 4 seasons-', description = 'This video introduces the seasonal scenery of Sainokawara Park.' where id = 'LyLy8cMuFvo6j6AZjgchm';
update content_bodies set title = '屋久島：生命が満たされる旅', description = '1993年に世界自然遺産に登録された屋久島は、類い稀な自然環境を誇る山や森で知られています。自然の美しさだけでなく、楽しいアクティビティや美味しい食事、豊かな文化も楽しめる島です。訪れる人々は、自分自身のルートで屋久島を探求し、友人や家族と共に特別な思い出を作りながら、島の魅力を発見することが奨励されています。' where id = 'djOI3qIfUF9-wX119kbqT';
update content_bodies set title = 'Yakushima: A Fulfilling Journey', description = 'Yakushima, registered as a UNESCO World Heritage Site in 1993, is renowned for its unique natural environment, including stunning mountains and forests. Beyond its natural beauty, the island offers a variety of enjoyable activities, delicious cuisine, and a rich cultural experience. Visitors are encouraged to explore Yakushima in their own way, discovering the island''s unique charms and creating memorable journeys with friends or family.' where id = '4DiJhtZT30m508RccWSmE';
update content_bodies set title = '福山市移住定住シティプロモーション動画', description = 'このシティプロモーション動画は、広島県福山市の移住・定住をテーマに制作されました。福山市は広島県で人口が2番目に多い都市で、北には山々、南には穏やかな瀬戸内海の景色が広がっています。市内は程よい都会で、新幹線も停車するため、買い物やお出かけに便利です。特に江戸時代に栄えた鞆の浦の美しい景観や、穏やかな生活のペースは多くの観光客を惹きつけています。この動画では、首都圏や他の県から福山市に移住した方々の貴重な体験談を紹介しています。福山市への移住や旅行を考えている方は、ぜひこの動画を視聴し、実際に訪れてみてください。' where id = 'pxogXOyGml8bMwsLL6oaG';
update content_bodies set title = 'FUKUYAMA CITY JAPAN Official Promotional Video', description = 'This promotional video highlights migration and settlement in Fukuyama City, located in Hiroshima Prefecture. Fukuyama is the second most populous city in the prefecture, surrounded by mountains to the north and the tranquil Seto Inland Sea to the south. The city offers a harmonious mix of urban and rural living, with convenient Shinkansen access for outings and shopping. Notably, the historical views of Tomonoura, which thrived during the Edo period, and the relaxed lifestyle make it an inviting destination for tourists. The video features testimonials from individuals who have relocated to Fukuyama from the Tokyo area and other regions. For those considering a move or visit to Fukuyama City, this video serves as an informative guide.' where id = 'P11nzlyJV0D5GPBE1yT7v';
update content_bodies set title = '【石狩市公式動画】Fun to Ride ISHIKARI', description = 'このプロモーション動画は、北海道石狩市のサイクルツーリズムを紹介しています。石狩を自転車で走りたくなるような魅力的な風景や、サイクリング中に立ち寄れるグルメスポットが紹介されており、観光客にとっての魅力が伝わる内容となっています。' where id = 'eUgWs9nBD2GVxWlvIDj5X';
update content_bodies set title = 'Fun to Ride ISHIKARI', description = 'This promotional video showcases the cycling tourism in Ishikari City, Hokkaido. It highlights the attractive landscapes that make you want to ride a bicycle through Ishikari, as well as gourmet spots that you can visit while cycling.' where id = '9JxAK6uDqISkmeO-nFZxI';
update content_bodies set title = '青の洞窟～The Blue Grotto of Japan～', description = 'この動画は、日本の津根神半島への短い旅行のダイジェストです。青の洞窟を訪れ、その美しさや神秘さ、素晴らしさを体験しました。' where id = 'ApDVxRaXlsExtZ0U43i3R';
update content_bodies set title = 'The Blue Grotto of Japan', description = 'This video summarizes a short trip to the Tsunegami Peninsula in Japan, where I visited the Blue Grotto. The grotto is described as beautiful, mysterious, and amazing.' where id = 'rtwOAwJB0CI6i5Flarusl';
update content_bodies set title = '【大分県】おんせん県おおいた観光動画　～大分県：アクティビティver.～', description = '大分県は日本一の温泉県として知られています。この観光PR動画では、大分県内の18市町村のアクティビティを紹介しています。旅行の参考にぜひご覧ください。詳細は大分県観光情報公式サイトをご覧ください。' where id = '1LyrG6hC2bcrg3L2sf6tf';
update content_bodies set title = 'Oita Prefecture: Activity Version of the Onsen Prefecture Oita Tourism Video', description = 'This is a promotional video showcasing the attractions of Oita Prefecture, known as Japan''s number one onsen (hot spring) destination. The video highlights activities across 18 cities and towns within the prefecture. It serves as a great reference for travelers looking to explore Oita. For more information, visit the official Oita tourism website.' where id = 'Q76rxJWekCDMb_51d5Y0O';
update content_bodies set title = '北太平洋シーサイドライン乗馬クラブMovie', description = 'この乗馬クラブは、すべての人に乗馬の魅力を提供します。東北海道の大自然を楽しむことができ、北太平洋の美しいビーチや花が咲く草原を巡る多彩なトレッキングコースを体験できます。' where id = 'fjENMeKoX2ciFbr80ILnQ';
update content_bodies set title = 'North Pacific Seaside Line Riding Club Movie', description = 'This riding club offers the charm of horseback riding to everyone. Located in eastern Hokkaido, it allows you to enjoy the great outdoors. You can experience a variety of trekking courses that take you through beautiful beaches of the North Pacific and hills adorned with blooming grasslands.' where id = '7SrUYlPm9HBggDQiOs6TJ';
update content_bodies set title = '尾野真千子｜「空」と「海」を繋ぐ場所 五島列島・新上五島町【旅色Movie】', description = '九州の最西端、東シナ海に浮かぶ五島列島の新上五島町を、尾野真千子さんと訪れました。この町は、7つの有人島と60以上の島々から成り立ち、空と海が溶け合う美しい青のグラデーションが特徴です。豊かな自然と貴重な文化遺産に恵まれ、釣り人の聖地としても知られています。尾野さんは「空と海はどこにでもあるけれど、ここは別格」と語り、様々なアクティビティを楽しむ様子が紹介されています。蛤浜海水浴場での海遊び、青方港での釣り体験、竹酔亭での五島うどん、キリシタン物語での歴史探訪、新上五島町観光物産センターでのお土産探しなどが含まれています。' where id = 'MdZiAn9_xbesYaeG41VyB';
update content_bodies set title = 'Machiko Ono | A Place Connecting ''Sky'' and ''Sea'' - Goto Islands, Shinkamigotou Town [Tabiiro Movie]', description = 'The Goto Islands, located at the westernmost tip of Kyushu in the East China Sea, consist of seven inhabited islands and over sixty others, forming Nagasaki Prefecture''s Shinkamigotou Town. Accompanied by actress Machiko Ono, the beauty of the blue gradient where the sky and sea merge is highlighted, along with the town''s rich natural environment and valuable cultural heritage. Known as a sacred place for fishermen, Ono expresses that while sky and sea can be found anywhere, this location is exceptional. The video showcases various activities, including beach fun at Hamaguhama Beach, fishing at Aokata Port, enjoying local Goto udon at Takezuitei, exploring history at Kirishitan Monogatari, and souvenir shopping at the Shinkamigotou Town Tourism and Products Center.' where id = 'NDHWJklxdDn-60TZWIo-z';
update content_bodies set title = '川栄李奈｜清流に心洗われる旅 60秒Ver【旅色Movie】', description = '川栄李奈さんが茨城県常陸大宮市を旅するスペシャルムービーです。彼女の飾らない素顔が垣間見え、まるで一緒に旅をしているかのような感覚を味わえます。常陸大宮は久慈川と那珂川に挟まれた自然豊かな町で、のんびりとした時間を過ごしたり、美味しい食事を楽しんだり、気ままな旅ができる場所です。' where id = 'QERPG7FQsg9bD2r8HRc_o';
update content_bodies set title = 'Rina Kawaei | A Journey to Refresh the Heart by the Clear Stream 60sec Ver【Tabiiro Movie】', description = 'This special movie features Rina Kawaei traveling in Hitachiomiya City, Ibaraki Prefecture. It offers a glimpse of her unpretentious self, making viewers feel as if they are traveling alongside her. Hitachiomiya is a nature-rich town nestled between the Kuji River and the Naka River, where one can enjoy a leisurely time, savor delicious food, and experience a carefree journey.' where id = 'w82Dz08wXSgnZsjQfWff6';
update content_bodies set title = 'VR三間コスモス', description = 'この動画はVR三間コスモスについて紹介しています。VR技術を活用した新しい体験を提供するこのプロジェクトは、視覚的な楽しさと没入感を兼ね備えています。視聴者は、仮想空間での探索やインタラクションを通じて、独自の体験を得ることができます。VR三間コスモスは、エンターテインメントや教育の分野での応用が期待されており、今後の発展が注目されています。' where id = 'aFbY4DmPoESclxNLQ2i0Z';
update content_bodies set title = 'VR Sankan Cosmos', description = 'This video introduces VR Sankan Cosmos.' where id = 'c2PWY9O0m56qZhaaAJomR';
update content_bodies set title = 'ESSENCE OF KITAKYUSHU 15秒CM - ネイチャー編-', description = '「ESSENCE OF KITAKYUSHU」のシリーズの一環として、特にネイチャー編に焦点を当てた15秒のCMです。この動画は、北九州の自然の美しさと本質を短い時間で表現することを目的としています。シリーズに関連する他のコンテンツは、提供されたYouTubeリンクから完全な再生リストを参照することで見ることができます。' where id = 'CanylVLgc81_ov-8I1wED';
update content_bodies set title = 'ESSENCE OF KITAKYUSHU 15-Second CM - Nature Edition', description = 'This is a brief introduction to the ''ESSENCE OF KITAKYUSHU'' series, specifically focusing on the Nature edition. The video aims to showcase the natural beauty and essence of Kitakyushu in a concise 15-second format. For more content related to this series, you can find the complete playlist at the provided YouTube link.' where id = 'BfAhJCoC6C47tF3Gist2D';
update content_bodies set title = '碓氷峠鉄道文化むら', description = 'この動画は碓氷峠鉄道文化むらについて紹介しています。碓氷峠は群馬県に位置し、鉄道の歴史や文化を学ぶことができる場所です。訪れることで、鉄道の魅力やその背景にあるストーリーを知ることができます。' where id = 'yRoGlWDtTUHtRmG609xTT';
update content_bodies set title = 'Usui Pass Railway Cultural Village', description = 'This video introduces the Usui Pass Railway Cultural Village.' where id = 'Tu9XoE0C9HOai2e9sAn-o';
update content_bodies set title = '【大食い】外国人VS超巨大ソースカツ丼！決死の完食チャレンジ', description = 'セネガル人のハーフ・モクタールとアメリカ出身のハンターが、福井名物のソースカツ丼に挑戦します。その量はなんと6人前！余裕を見せるモクタールと、大食い自信満々のハンター。果たして二人はこの巨大な料理を完食できるのでしょうか？ソースカツだけでなく、他にもさまざまなものが付いてきます。現在、コロナウイルスの影響で県外への旅行や観光が難しい状況ですが、落ち着いた際にはぜひ福井を訪れてください。お店からのお願いとして、感染症予防のため、複数人数での挑戦はお断りしており、一人で食べたい猛者のみのお問い合わせをお願いしています。' where id = 'oKbrXMrl5isbxkCijsOhm';
update content_bodies set title = 'Eating Challenge: Foreigners vs. Giant Sauce Katsu Don!', description = 'Mokhtar, a half-Senegalese, and Hunter from the USA take on the challenge of eating a giant Sauce Katsu Don, which is equivalent to six servings! Mokhtar appears confident, while Hunter boasts about his eating skills. Will they be able to finish this massive dish? The meal includes not just the sauce katsu but also various other items. Due to the ongoing COVID-19 pandemic, traveling and sightseeing outside the prefecture is currently difficult, but once things settle down, visitors are encouraged to come to Fukui! The restaurant requests that, for infection prevention measures, challenges with multiple people are currently not allowed, and only those who wish to eat alone (the brave ones) should inquire.' where id = 'ZAQbxi7CQ_J21cvHJt279';
update content_bodies set title = '和琴半島一周カヌークルーズ', description = '和琴半島は、屈斜路湖に突き出た約3kmの半島で、火山の特徴や温泉が点在し、特にオヤコツ地獄では地面から煙が上がる様子が見られます。春にはエゾヤマザクラ、秋には紅葉と、四季折々の美しい自然が楽しめます。天気が良い日には、屈斜路湖の透明度が最高で、息をのむような景色が広がります。半島をカヌーで巡った後は、平塚さんの奥さんが地元の食材を使った手作りランチを提供してくれます。平塚夫妻は経験豊富なカヌーガイドで、故郷の自然の素晴らしさを伝えることを目指しています。' where id = 'tzr7dz17C1VlXlJYqkJBt';
update content_bodies set title = 'Canoe Cruise around Wakoto Peninsula', description = 'Wakoto Peninsula, a 3km long peninsula in Lake Kussharo, is known for its volcanic features and hot springs, including the Oyakotsu Jigoku area where smoke rises from the ground. The peninsula showcases stunning natural beauty throughout the seasons, from cherry blossoms in spring to vibrant autumn foliage. On clear days, the lake''s clarity offers breathtaking views. After paddling around the peninsula, guests enjoy a homemade lunch prepared by Mrs. Hiratsuka, featuring local ingredients from Teshikaga. The Hiratsuka couple, experienced canoe guides, aim to share the natural wonders of their hometown through memorable canoe tours.' where id = 'Z0x1iLvEILhiMAViWE-ew';
update content_bodies set title = '竹老園東家総本店', description = '竹老園東家総本店は、北海道で最も古い蕎麦屋のひとつで、140年以上の歴史を誇ります。この専門店は、本物の地元の蕎麦を追求し続けており、特に緑色の蕎麦が特徴です。これは新そばを使用しているためで、創業者はすべてのお客様に新そばの味を楽しんでもらいたいと考えていました。この伝統は今も受け継がれています。釧路に位置する竹老園は、長年にわたり技術を磨き続け、品質へのこだわりを持っています。店舗の住所は北海道釧路市柏木町3-19で、電話番号は0154-41-6291です。' where id = 'zJ6Q20PUQu7hGwkljHeNG';
update content_bodies set title = 'Chikurouen Flagship Store', description = 'Chikurouen''s flagship store is one of the oldest soba noodle restaurants in Hokkaido, boasting a history of over 140 years. This restaurant specializes in authentic local soba noodles, particularly known for their unique green color, which comes from using new buckwheat. The founder aimed for every customer to enjoy the taste of fresh soba, a tradition that continues today. Located in Kushiro, Chikurouen has refined its craft over the years while maintaining its commitment to quality. The restaurant''s address is 3-19 Kashiwagi-cho, Kushiro, Hokkaido, and it can be contacted at 0154-41-6291.' where id = 'kKXa_NOt36AjyYmwswOAf';
update content_bodies set title = '釧路サンセットクルーズ', description = '釧路は世界三大美しい夕日の一つを持つとされており、その絶景はボートから見るのが最適です。東北海道は独自の歴史と地理を持ち、日本に位置しながらも北アメリカのプレート上にあります。そのため、非常に珍しい植物が豊富に存在します。地元の人々は何世代にもわたり、希少な野生動物や国立公園の自然と共存してきたため、人の手が加わっていない自然のエリアが多く残されています。' where id = 'ULnX2-7W63S0g-S3hPszV';
update content_bodies set title = 'Sunset Cruise: Untouched Hokkaido', description = 'Kushiro is renowned for having one of the three most beautiful sunsets in the world, best viewed from a boat. Eastern Hokkaido boasts a unique history and geography, situated on the North American tectonic plate, which contributes to its rich biodiversity, including rare plant life. The local communities have lived in harmony with the area''s wildlife and the pristine nature of the national parks, resulting in many untouched natural areas.' where id = 'Mez0xhZ3eqzaAbzyv0E6r';
update content_bodies set title = '宇和島', description = 'この動画は宇和島について紹介しています。' where id = 'n0ZzaPi0_z95OCDJrIDbw';
update content_bodies set title = 'Uwajima', description = 'This video introduces Uwajima.' where id = 'ubg1YGAdx8ziMW9IEESN_';
update content_bodies set title = '南紀熊野ジオパークの絶景・本州最南端潮岬', description = '地球の活動によって生まれた美しい景色を、ゆっくりと楽しんでください。自然の音に耳を傾け、周囲の空気を感じてみてください。' where id = '8r2ahvTcYQJzI4l_gfwun';
update content_bodies set title = 'Cape Shionomisaki: The Southernmost Point of Honshu in Nanki Kumano Geopark', description = 'Take your time to enjoy the breathtaking scenery created by the Earth''s activities. Listen to the sounds of nature and feel the air around you.' where id = 'U1-aRHOy4fZ42NXaCsMWM';
update content_bodies set title = '民宿 ながさき家（ながさきや）【利賀村】', description = '民宿ながさき家は、富山県南砺市利賀村長崎91に位置しています。郵便番号は932-0371で、電話番号は0763-82-5326です。詳細については、公式ウェブサイト（http://www.shokoren-toyama.or.jp/~toga/stay16.html）をご覧ください。' where id = 'FHBsmlBAGBeRbiDJfs99d';
update content_bodies set title = 'Minpaku Nagasaki-ya (Nagasaki House) [Toga Village]', description = 'Minpaku Nagasaki-ya is located at 91 Nagasaki, Toga Village, Nanto City, Toyama Prefecture, 932-0371, Japan. For inquiries, you can contact them at 0763-82-5326. More information can be found on their website: http://www.shokoren-toyama.or.jp/~toga/stay16.html.' where id = 'vHauh7zLRU9JSNT81YklG';
update content_bodies set title = '雪とある日のとおかまち -short ver.-', description = 'この動画では、雪の日の十日町市を紹介しており、清津峡や美人林、信濃川などの観光スポットが取り上げられています。' where id = '3HND1iuEcmLDLU8J03tr-';
update content_bodies set title = 'One snowy day in Tokamachi -short ver.-', description = 'This video introduces Tokamachi on a snowy day, highlighting various tourist spots such as Kiyotsukyo, Bijinbayashi, and the Shinano River.' where id = '_8T-Un2LKBhlc5QiKFvvT';
update content_bodies set title = '黒松内ローランドエリアのアドベンチャートラベル：北海道日本', description = '北海道の黒松内ローランドエリアは、ユニークなアドベンチャートラベル体験を提供しています。このプロジェクトは、黒松内観光協会と北海道観光振興機構の支援を受けています。この地域は、北限のブナ林や朱太川などの自然美で知られ、カヌーやサイクリングなどのアクティビティが楽しめます。訪問者は、国の天然記念物であるクマゲラを含む豊かな生物多様性を探索できます。プロジェクトはエコモビリティと持続可能な観光を促進し、地元のそば屋やとうふ処などの魅力を紹介しています。詳細は公式ウェブサイトやSNSをチェックしてください。' where id = 'f8M8_BCmEuQq_b_vncXfT';
update content_bodies set title = 'Adventure Travel in Kuromatsunai Lowland Area: Hokkaido Japan', description = 'The Kuromatsunai Lowland Area in Hokkaido, Japan, offers a unique adventure travel experience, supported by the Kuromatsunai Tourist Association and the Hokkaido Tourism Organization. This region is known for its natural beauty, including the northern limit of beech forests, the Shuta River, and opportunities for activities like canoeing and cycling. Visitors can explore the area''s rich biodiversity, including the black woodpecker, a national natural monument. The project aims to promote eco-mobility and sustainable tourism, showcasing local attractions such as soba restaurants and tofu shops. For more information, visit the official website or follow their social media channels.' where id = 'UWJWyJMHatbgSkxrTu5ky';
update content_bodies set title = 'nippon', description = 'この動画はnipponについて紹介しています。' where id = 'rR21isEvX06Ecp6iiPgzC';
update content_bodies set title = 'nippon', description = 'This video introduces nippon.' where id = 'BmcMo9pxQ7FW88B2QgZeu';
update content_bodies set title = '【旅行Vlog】昭和レトロな宿 海宿 二木島 漁師町の一棟貸しのゲストハウス', description = '友人が三重県熊野市二木島に「海宿 二木島」というゲストハウスをオープンしました。リフォーム中から何度も訪れていたため、オープンは感慨深いものがあります。このゲストハウスは、海を望む丘の上にあり、素朴な漁師町の昭和レトロな雰囲気を持っています。今日は、隣町の熊野市の日常を旅します。「海宿 二木島」や三重県御浜町、神聖な熊野杉の香りが溶け込んだお酒「Mok」についての詳細は、各ウェブサイトをご覧ください。質問があればコメント欄にどうぞ。気に入ったら、いいねやチャンネル登録もお願いします。' where id = 'rhNCIDycOOWJfe7ppDaVZ';
update content_bodies set title = 'Travel Vlog: Retro Showa-style Guesthouse ''Umiyado Nigishima'' in a Fishing Town', description = 'A friend has opened a guesthouse called ''Umiyado Nigishima'' in the fishing town of Nigishima, Kumano City, Mie Prefecture. Having visited multiple times during its renovation, the opening is a deeply emotional moment. The guesthouse, located on a hill overlooking the sea, embodies the simple, retro Showa atmosphere of the fishing town. Today, we explore the daily life in the neighboring town of Kumano City. For more information about ''Umiyado Nigishima'', visit the provided Airbnb link or their Instagram. Additionally, details about Mihama Town and the sacred Kumano cedar-infused sake ''Mok'' can be found on their respective websites. Feel free to leave comments or questions, and if you enjoyed the content, please like, comment, and subscribe to the channel.' where id = 'Dcr-vtma9RtSQVznIRH0X';
update content_bodies set title = '【地方移住】移住365日目｜移住1年目｜東京から三重へ移住した夫婦の移住生活2年目が始まった', description = '東京から三重県御浜町に移住した夫婦が、移住1年目を振り返り、田舎暮らしの楽しさや出会った人々への感謝の気持ちを伝えています。思うようにいかないこともあったものの、充実した一年だったと感じています。今後も動画を月に2本アップする予定で、視聴者からのコメントや質問を歓迎しています。また、インスタグラムも始めたことを紹介しています。' where id = 't2YHQYna-IxFo_0b59mbV';
update content_bodies set title = 'Rural Relocation: Day 365 of Moving to Mie from Tokyo', description = 'A couple reflects on their first year of rural living after relocating from Tokyo to Mie. They express gratitude for the experiences and connections made in their new town, despite facing challenges. They plan to continue sharing their journey through videos and encourage viewers to engage with their content. For more information about Mihama Town in Mie Prefecture, a link is provided. They also invite questions and comments from viewers and mention their new Instagram account.' where id = 'WyS1EchapaXiJuC1Q8tEp';
update content_bodies set title = '空から見たえびの市', description = 'ドローンを使用して撮影されたえびの市の映像です。地上からは見ることのできない絶景を体験できます。' where id = 'PZpQxk4C8W_59uxKWP13v';
update content_bodies set title = 'Ebinog City from Above', description = 'This video showcases Ebinog City as seen from the sky, captured using a drone. Experience breathtaking views of Ebinog City that cannot be seen from the ground.' where id = 'AnC4n66cQtoMCFdr6842C';
update content_bodies set title = '平湯大滝 冬　氷の世界', description = '岐阜県高山市奥飛騨温泉郷に位置する平湯大滝は、落差64メートル、幅6メートルの大きな滝で、飛騨三大名瀑の一つとして知られています。冬の季節になると、滝は氷結し、まるで行く手を阻むかのように巨大な氷の柱に姿を変えます。自然の力によって生み出される氷の彫刻をぜひご堪能ください。' where id = 'fUc1UDOFZHh9dGJb-o2d0';
update content_bodies set title = 'Hida Hirayu Waterfall in Winter', description = 'Hirayu Otaki, located in Okuhida Onsengo, Takayama City, Gifu Prefecture, is one of the three great waterfalls of Hida, with a height of 64 meters and a width of 6 meters. During winter, the waterfall freezes, transforming into a massive pillar of ice that appears to block the path. Visitors can enjoy the stunning ice sculptures created by the forces of nature.' where id = 'YyQckYfFBwL266_ow8V84';
update content_bodies set title = '熊野神社 伊邪那美(イザナミ)の道', description = '広島県庄原市に位置する熊野神社は、旧比婆大社であり、創建年は不詳です。比婆山の山麓にあるこの神社は、日本最古の歴史書『古事記』の伝承を現代に伝える重要な場所です。神々の母である伊邪那美命は、立烏帽子山に伊邪那岐が訪れた際、夜になったため自分の櫛に火を灯し、道を照らしました。彼女は途中の岩穴に身を隠し、天から降る火の雨を逃れたという逸話があります。また、後に火の神を産んだ伊邪那美は、この道の岩穴で亡くなり、黄泉の国へ旅立ったとも伝えられています。' where id = 'BKZcndEvxHGtoAu-9z7IJ';
update content_bodies set title = 'Kumano Shrine The road of IZANAMI', description = 'Kumano Shrine, located in Shobara City, Hiroshima Prefecture, is the former Hiba Ohyashiro Shrine, with an unknown foundation year. Situated at the foot of Mt. Hiba, it serves as a site that conveys the traditions of Japan''s oldest historical text, the ''Kojiki.'' The shrine is associated with the mother of the gods, Izanami Nomikoto, who, when visited by Izanagi Nomikoto at Mt. Tateeboshi, used her comb as a light during the night. An anecdote tells of her hiding in a rock hole to escape a rain of fire from the sky. It is also said that Izanami, who later gave birth to the fire god, died in a rock hole along this path and journeyed to the underworld.' where id = 'iqzqiRw4uMqGz0OAuLJbt';
update content_bodies set title = '出雲大社 - IZUMO NO OHYASHIRO', description = '出雲大社は島根県出雲市大社町杵築東に位置する神社で、日本最古の神社の一つとされています。主祭神である大国主大神は日本国創造の神とされ、旧暦の十月には八百万の神々が集まり神議が行われると伝えられています。出雲大社には、御本殿や神楽殿、参道にあるさざれ石など、重要な場所が数多く存在します。' where id = 'XUtHZ351rg2S1dhSFLd4C';
update content_bodies set title = 'Izumo Taisha - IZUMO NO OHYASHIRO', description = 'Izumo Taisha is a shrine located in Kizukihigashi, Taisha-cho, Izumo City, Shimane Prefecture. It is one of the oldest shrines in Japan, with its main deity, Okuninushi no Okami, regarded as the god of Japan''s creation. According to tradition, in October of the lunar calendar, eight million gods (Yaorozu no Kami) gather at this site to hold a deity meeting. The shrine features various significant locations, including the main hall, the Kagura hall, and the sacred stone path leading to the shrine.' where id = '0fFjJLRlndWlij3OsaT-M';
update content_bodies set title = 'しまなみ海道　全長54km　瀬戸内の多島美！VRの旅', description = '瀬戸内海は本州と四国の間に広がる内海で、大小約700の島々が点在しています。本州の尾道（広島県）から今治（愛媛県）を結ぶ道路は3ルートあり、その一つがしまなみ海道（西瀬戸自動車道）です。この風光明媚な道は、尾道から向島、因島、生口島、大三島、伯方島、大島、そして今治までの54kmにわたります。VRを通じて、瀬戸内の多島美としまなみ海道の壮大な景色をお楽しみください。' where id = 'cEflEfh2BkyocB3mezC4b';
update content_bodies set title = 'Shimanami Sea road, beauty of scattered islands in Setouchi! VR trip', description = 'The Seto Inland Sea is located between Honshu and Shikoku, featuring around 700 islands of various sizes. One of the three connecting roads from Onomichi (Hiroshima Prefecture) to Imabari (Ehime Prefecture) is the Shimanami Kaido (Nishi Seto Expressway). This scenic route spans 54 km, linking Onomichi to Mukaishima, Innoshima, Ikuchijima, Omishima, Hakatajima, Oshima, and Imabari. Experience the stunning beauty of the scattered islands in Setouchi and the magnificent views along the Shimanami Kaido through VR.' where id = '0MYqyiaBwN17BgeIubz-0';
update content_bodies set title = '東京 赤坂 氷川神社', description = '赤坂氷川神社は、千年以上の歴史を持つ神社です。御祭神は素戔嗚尊、奇稲田姫命、大国主命であり、奇稲田姫命はかつて八岐大蛇の生贄となっていましたが、素戔嗚尊によって救われ、後に彼の妻となりました。大国主命は二人の子孫であり、国造の神様として出雲大社の主祭神でもあります。この神社の起源は、ヤマタノオロチ退治の舞台である出雲国の簸川にさかのぼります。951年、東国を旅していた僧が現在の赤坂4丁目で一夜を過ごした際に夢の中で神のお告げを受け、この地に神社を建立しました。江戸幕府第八代将軍、徳川吉宗によって建立されたこの神社は、震災や戦災を免れ、鳥居や狛犬、灯籠など、当時の面影を今に伝えています。' where id = 'qp1eTuoGNfV8ZVOtJiN-A';
update content_bodies set title = 'Tokyo Akasaka Hikawa Shrine', description = 'Akasaka Hikawa Shrine has a history of over a thousand years. The deities enshrined here are Susano-no-mikoto, Kushinadahime-no-mikoto, and Okuninushi-no-mikoto. Kushinadahime was once a sacrifice to the Yamata-no-Orochi but was saved by Susano-no-mikoto, later becoming his wife. Okuninushi is their descendant and is also the main deity of Izumo Taisha, known as the god of national creation. The shrine''s origins trace back to Hikawa in Izumo Province, the site of the Yamata-no-Orochi''s defeat. In 951, a monk traveling to the eastern region received a divine message in a dream while staying overnight at the present Akasaka 4th street, leading to the shrine''s establishment. The shrine, built by Yoshimune Tokugawa, the eighth shogun of the Edo Shogunate, has survived past earthquakes and wars, preserving elements from its original construction, including the torii gate, guardian dogs, and lanterns.' where id = 'BlHK1-CtXHs9S1OrU6MQ4';
update content_bodies set title = '2泊3日で周遊！岡山を味わい尽くす女子二人旅', description = '岡山県の魅力をどれだけ知っていますか？多くの人が倉敷の美しい街並みを思い浮かべるでしょうが、それだけではありません！この2泊3日の女子旅では、蒜山高原の大自然、歴史ある湯原温泉、恋人たちの聖地・黒島ヴィーナスロードなど、岡山の多様な魅力を紹介します。周遊エリアは蒜山、勝山、湯原、倉敷、牛窓、日生、備前など。1日目は蒜山高原や勝山、湯原温泉を訪れ、2日目は倉敷の美観地区や文化体験を楽しみ、3日目は牛窓や日生を巡り、地元のグルメ「カキオコ」を味わいます。リラックス、文化、グルメが融合した旅が待っています。' where id = '7o1BgzfPt2ru9l08I2li5';
update content_bodies set title = '2-Night, 3-Day Tour! A Girls'' Trip to Experience Okayama', description = 'How much do you know about the charms of Okayama Prefecture? Many might recall the beautiful streets of Kurashiki, but there''s so much more! This 2-night, 3-day girls'' trip showcases the diverse attractions of Okayama, including the refreshing nature of Hiruzensei Highland, the historic hot spring town of Yubara Onsen, and the romantic Kuroshima Venus Road. The itinerary covers various areas such as Hiruzensei, Katsuyama, Yubara, Kurashiki, Ushimado, Hinase, and Bizen. Day one includes visits to Hiruzensei Highland, Katsuyama, and Yubara Onsen. Day two features Kurashiki''s scenic beauty and cultural experiences, while day three explores Ushimado and Hinase, highlighting local delicacies like ''Kakioko.'' This trip promises a perfect blend of relaxation, culture, and culinary delights.' where id = 'zZPYESUU5xoqc-HU4xM4Y';
update content_bodies set title = '岡山｜日本 - 北木島！ -', description = '日本の文化遺産である北木島（きたぎしま）、通称「石の島」を自転車で巡り、素晴らしい景色と迫力ある岩の眺めを体験しましょう。出発は、笠岡の伏越港からの1時間のフェリーで、瀬戸内海の美しい景色を楽しめます。島内では、桂林やヴェネツィアを思わせる風景や壮大な採石場など、魅力的なスポットがたくさんあります。特に「みなとや」での独特な「亀の手」出汁のラーメンや、元映画館の光映画館、石切り谷の展望台などが見どころです。最後は自転車を返却し、海の見えるカフェで休憩を楽しんでから、フェリーで帰ることができます。' where id = 'csYoIw-l0z3fXGBi-nsP6';
update content_bodies set title = 'Okayama, Japan - Kitagi-shima Island!', description = 'Experience the beauty of Kitagi-shima Island, also known as ''Stone Island,'' through a cycling adventure around this Japan Heritage site. The journey begins with a one-hour ferry ride from Fushigoe-ko Port to Toyoura-ko Port, offering stunning views of the Seto Inland Sea. Once on the island, you can rent a bike to explore various attractions, including picturesque landscapes reminiscent of Guilin and Venice, as well as impressive quarry sites. Highlights include a unique ramen lunch at ''Minatoya,'' a visit to the former Hikari Cinema, and breathtaking viewpoints like Ishikiri no Tani. The day concludes with a return ferry ride, making it a perfect day trip filled with scenic beauty and cultural experiences.' where id = 'pZ3soh9qb4wdpZCRg6s7s';
update content_bodies set title = 'TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（240s）', description = '岡山県の玉野市は、瀬戸内トリエンナーレの開催を経て、世界中の旅行者を惹きつける港町です。この動画では、玉野を訪れた旅行者がこの街に魅了され、移住を決意した人々の声を紹介しています。玉野市の魅力は、単なる通過点ではなく、訪れる人々が新たな生活を見つける場所であることを伝えています。' where id = '_FC54tneFMNBcLx-ok4LQ';
update content_bodies set title = 'TAMANO Calling: A PR Video for Tamano City, Okayama Prefecture (240s)', description = 'Tamano is a port town in Okayama Prefecture, positioned as a gateway to the islands and attracting travelers from around the world, especially during events like the Setouchi Triennale. This video highlights the experiences of those who have visited and subsequently chosen to live in Tamano, showcasing the city''s unique charm that captivates visitors. Through their voices, the video presents the allure of Tamano, a place where travelers not only pass through but also find a new home.' where id = 'kNdbBsJxI8DoelyAKq4AE';
update content_bodies set title = '北海道のナイアガラの滝', description = '北海道の伊達市大滝区に位置するナイアガラの滝は、大滝総合運動公園から長流川沿いの森林を歩く約6㎞のトレイルコースでアクセス可能です。この滝は落差3ｍ、幅30ｍで、大滝ナイアガラの滝と徳舜瞥山の美しい眺望を楽しむことができます。' where id = 'tWY-p8bayxPA-VR0RhlaQ';
update content_bodies set title = 'Hokkaido’s Niagara Falls', description = 'Hokkaido''s Niagara Falls, located in the Otaki area of Date City, is a scenic waterfall accessible via a 6 km trail through the forest along the Nagauru River, starting from the Otaki Comprehensive Sports Park. The waterfall features a drop of 3 meters and a width of 30 meters, offering beautiful views of both the falls and Mount Tokushunbetsu.' where id = '41IptfvSEmjWPAR_HAhTE';
update content_bodies set title = '三重県 8K HDR - 三重県', description = 'この動画は、日本の三重県の美しさを8K HDR映像で紹介しています。主な撮影場所には、英虞湾、伊勢神宮、伊賀の組紐などが含まれています。動画では、鳥羽マリンターミナル、伊勢エビ、伝統的な伊勢うどんなどの観光名所が強調されています。また、伊賀上野城や世界遺産の熊野古道伊勢路などの文化遺産も取り上げられています。動画の監督・編集は栄川幸、撮影は松村隆、空撮は馬場基成が担当しています。詳細については、三重県観光公式サイトをご覧ください。' where id = 'rxBYjqDsq-kODc_AuuVWr';
update content_bodies set title = 'Mie, Japan 8K HDR - Mie Prefecture', description = 'This video showcases the beauty of Mie Prefecture in Japan, featuring stunning 8K HDR visuals. Key locations include Ago Bay, Ise Jingu, and Iga Braided Cords, among others. The video highlights various attractions such as Toba Marine Terminal, Ise Ebi (spiny lobster), and traditional Ise Udon. It also covers cultural heritage sites like Iga Ueno Castle and the World Heritage Kumanokodo Iseji. The director and editor of the video is Yuki Eikawa, with photography by Takashi Matsumura and aerial photography by Motonari Baba. For more information, visit the official Mie Prefecture tourism website.' where id = 'LF1Pe9X6Drk2NQ8Qplb2E';
update content_bodies set title = 'かながわの花を見に行こう！～歴史編～', description = '神奈川県には四季を彩る美しい花と風景が溢れています。今回は歴史を感じられるスポットをご紹介します。色とりどりに咲き誇る花と四季折々の風景を巡ってみませんか？' where id = 'MTq07v14nP_KXfcIq224I';
update content_bodies set title = 'Let''s Go See the Flowers of Kanagawa! - Historical Edition', description = 'Kanagawa Prefecture is filled with beautiful flowers and landscapes that change with the seasons. This time, we will introduce spots where you can feel the history. Why not take a tour of the colorful flowers and the seasonal scenery?' where id = 'BVgLI4AmiDsYwfq62-n2B';
update content_bodies set title = '神奈川観光動画コンテスト　応募作品02 「Miura　Peninsula　三浦半島｜Ａ　pleasant holiday」', description = '晴れやかで心地よい休日を友人たちと共に過ごし、ドローン・カメラを使って夕暮れまで楽しむ様子が描かれています。投稿者はyqualiaです。' where id = 'IHCaNJ3JZ9oYtFFSPu6mR';
update content_bodies set title = 'Kanagawa Tourism Video Contest Entry 02: ''Miura Peninsula - A Pleasant Holiday''', description = 'A bright and pleasant holiday is captured as friends enjoy their time together with a drone camera until sunset.' where id = 'r8LtfcFdNgdZHamxw3plf';
update content_bodies set title = 'プライベートビーチでの海女バトラーとのプレミアムディナー', description = 'このユニークな体験では、三重県志摩市の海女（あま）と共に過ごすことができます。海女漁は2000年以上の歴史を持ち、200名以上の現役海女が活躍している地域で、平均年齢は65歳です。参加者は海女と共に船に乗り、伝統的なかご漁法を体験し、あわびやウニなどの新鮮な海産物を収穫します。その後、捕れた食材を使った特別ディナーがプライベートビーチで提供され、海女がバトラーとしてサービスを行います。このプログラムは、三重県の豊かな自然と文化遺産を体験できる特別な機会です。' where id = 'wu-1iNAVReGEn9IQ9YE1L';
update content_bodies set title = 'Premium dinner with Ama butler at private beach', description = 'This unique experience allows participants to engage with ama, female freedivers from Shima, Mie, who have been practicing traditional fishing for over 2,000 years. With more than 200 active ama, this region is one of the few places in Japan where this cultural practice continues, with an average age of 65 among the ama. Participants will embark on a boat with the ama to learn their traditional basket fishing techniques, collecting fresh seafood like abalone and sea urchin. Following the fishing experience, a special dinner featuring the freshly caught seafood will be served on a private beach, with the ama acting as personal butlers, ensuring an unforgettable evening. This program highlights the rich natural resources and cultural heritage of Mie Prefecture.' where id = 'FbvS4SwFzqCa2gOJ4c79g';
update content_bodies set title = '成相寺の紅葉とライトアップ', description = 'この動画は、2017年秋の成相寺における紅葉とライトアップイベントを紹介しています。' where id = 'OHHM6n80BcgYQvCT1yDij';
update content_bodies set title = 'Autumn Foliage and Illumination at Nariai-ji Temple', description = 'This video showcases the autumn foliage and illumination event at Nariai-ji Temple in 2017.' where id = '0gG6HmgKp35dumoo8urAZ';
update content_bodies set title = '紀伊山地の世界遺産、馬越峠を歩く', description = 'かつて日本全国から伊勢神宮や熊野三山を巡る聖地巡礼が盛んでした。その中で、紀伊山地の世界遺産「馬越峠」は多くの旅人が通った祈りの道の一つです。美しい石畳は地元の人々によって何百年も保全され、今も昔の姿を留めています。本プログラムでは、浮世絵や文献を参考にした旅装束を身にまとい、古の旅人のように馬越峠を歩く体験ができます。参加費の一部は石畳の保全活動に使われ、未来の世代のためにこの美しい景色を守ります。三重県の自然や人々の生活に触れ、「三重県ならでは」の魅力を感じる特別な体験です。' where id = 'jBYaFFzJiFuwN6TJhpqJb';
update content_bodies set title = 'Walk the Magose pass on the Kumano Kodo trail, UNESCO World heritage site', description = 'The Kumano Kodo trail, part of the UNESCO World Heritage site, features the historic Magose Pass, once a popular route for pilgrims traveling hundreds of kilometers to sacred sites like Ise Grand Shrine and Kumano Sanzan. This beautiful stone-paved path, maintained by locals for centuries, retains its ancient charm. Participants in this program can dress in traditional travel attire inspired by ukiyo-e prints and historical documents, experiencing the journey as ancient travelers did. A portion of the program''s proceeds goes towards preserving the stone paving and maintaining the scenic beauty for future generations. The program offers a unique opportunity to connect with the rich natural environment and culture of Mie Prefecture.' where id = '42nwdMGyuYQxcL-sQuDSW';
update content_bodies set title = '山城での本格的な忍者体験', description = '本プログラムは、かつて忍者が重宝された伊賀の山城跡で、本格的な忍者体験を提供します。参加者は、まず道場で伊賀忍術に基づく呼吸法や印、歩き方の基礎を学ぶ入門編から始まります。昼食後には、実際に忍者が活動した記録の残る山城を散策し、森の中での刀の振り方や鍵縄の使い方、隠れ方などに挑戦します。このプログラムは日本忍者協議会によって設計されており、体系的なカリキュラムに基づいた継続的なスキル向上が可能な珍しいワークショップです。' where id = '6yADMgIED4fOxIsLuNge9';
update content_bodies set title = 'An authentic Ninja experience on the site of a mountain castle', description = 'This program offers an authentic ninja experience at a historical mountain castle site in Iga, where ninjas were once valued for their agility in mountainous terrain. Participants will start with an introductory course at an indoor dojo, learning breathing techniques, hand signs, and basic walking methods based on Iga ninjutsu. After lunch, they will explore the castle grounds, practicing sword swinging, grappling hook use, and concealment techniques in the forest, all while engaging in activities that reflect the training of actual ninjas. Designed by the Japan Ninja Council, this workshop features a systematic curriculum that allows for continuous skill advancement, making it a unique opportunity for participants.' where id = '5sMRuLW3tOOsArRq7tooT';
update content_bodies set title = 'リラックスできる自然の音 - 穏やかな川 - 三重県', description = '三重県の観光情報を提供する公式サイトでは、英語や繁体字、簡体字、タイ語、韓国語、日本語など、さまざまな言語で情報を得ることができます。訪問者は、FacebookやInstagram、YouTubeなどのSNSを通じて、三重県の旅行情報や観光名所についての最新情報を得ることができます。このサイトは、三重県の自然の美しさや文化の豊かさを体験したい人々にとって、包括的なリソースとなっています。' where id = 'GTBobB5cSchIF_kz4iFYA';
update content_bodies set title = 'Relaxing Nature Sounds - Gentle River - Mie Prefecture, Japan', description = 'Discover the beauty of Mie Prefecture in Japan through its official tourism site. The site offers information in multiple languages, including English, Traditional Chinese, Simplified Chinese, Thai, Korean, and Japanese. Visitors can explore various social media platforms such as Facebook, Instagram, and YouTube to stay updated on travel tips and attractions in Mie. The site serves as a comprehensive resource for anyone interested in experiencing the natural beauty and cultural richness of Mie Prefecture.' where id = 'vY-mZWznietmNT2kgAJ-_';
update content_bodies set title = '善光寺ツアー', description = '長野市の善光寺ツアーでは、日本の重要な仏教寺院の一つである善光寺を探訪するユニークな機会が提供されます。このツアーでは、寺院の歴史、建築、文化的意義についての洞察が得られます。参加者は、寺院の敷地内の静かな雰囲気を体験し、善光寺に関連するさまざまな儀式や慣習について学ぶことができます。このツアーは、日本の文化や精神性に興味がある方に最適です。' where id = 'o3Yso54527qBK3dYkrgZR';
update content_bodies set title = 'Zenkoji Temple Tour', description = 'The Zenkoji Temple Tour in Nagano City offers visitors a unique opportunity to explore one of Japan''s most significant Buddhist temples. The tour includes insights into the temple''s history, architecture, and cultural significance. Participants can experience the serene atmosphere of the temple grounds and learn about the various rituals and practices associated with Zenkoji. This tour is ideal for those interested in Japanese culture and spirituality.' where id = 'RIH2EvIjIRqUQL9l4q45m';
update content_bodies set title = '第15回 那智勝浦町花火大会', description = '令和6年8月18日（日）に開催される花火大会のダイジェスト動画です。撮影には株式会社ドローンワークスの協力がありました。' where id = 'j40wvii48tqg_knwMeH1z';
update content_bodies set title = '15th Nachikatsuura Fireworks Festival', description = 'This is a digest video of the fireworks festival held on August 18, 2024. Filming cooperation by Drone Works Co., Ltd.' where id = 'ADvZsR4wRF7tPO4B6kPlQ';
update content_bodies set title = '青森ねぶた祭り完全復活‼︎', description = 'この動画は青森ねぶた祭りの完全復活について紹介しています。' where id = 'FaJSBzpo5QGDC5FTmQFKN';
update content_bodies set title = 'Aomori Nebuta Festival Fully Revived!', description = 'This video introduces the complete revival of the Aomori Nebuta Festival.' where id = '-5ksUpEumDvPao_dpzRn-';
update content_bodies set title = '京都京北の隠れた名所', description = '京北は古くから皇室にゆかりのある御料地であり、寺院や神社、豊かな自然を楽しむアクティビティが豊富です。また、農家民宿を通じて田舎暮らしを体験することもできます。' where id = 'S1yg_tdPzyWUDEGUTVJ4c';
update content_bodies set title = 'Hidden Gems of Kyoto Keihoku', description = 'Keihoku, historically associated with the imperial family, is introduced through its temples, shrines, and rich natural activities. Visitors can also experience rural life through farm stays.' where id = 'Qmy4syRmOdfg_O-kAXKJO';
update content_bodies set title = '富山市のおすすめ観光10選', description = '富山市は日本の中央に位置する隠れた宝石で、息を呑むような自然、豊かな文化、美味しい食事が楽しめます。このガイドでは、訪れるべきトップ10の観光スポットを紹介します。絶景が楽しめる富山市役所展望塔、近代建築とガラスアートが魅力の富山市ガラス美術館、新鮮な海鮮が味わえる地元の寿司店などが含まれています。富岩運河環水公園でリラックスしたり、路面電車で市内を観光したり、富山城で歴史を体験することもできます。富山ならではのブラックラーメンや、レトロな魅力の岩瀬地区もおすすめです。護国神社や日枝神社では静かな歴史を感じられ、総曲輪アーケードや大和百貨店でショッピングも楽しめます。9月にはおわら風の盆という伝統的な祭りも開催され、音楽と踊りが楽しめます。' where id = '8hOovuskcaPHj6GKXg7Jg';
update content_bodies set title = 'Top 10 Things to Do in Toyama City', description = 'Toyama City, a hidden gem in central Japan, offers a unique blend of stunning nature, rich culture, and delicious cuisine. This guide highlights the top 10 attractions and activities for visitors. Key spots include the Toyama City Hall Panorama for breathtaking views, the Toyama Kirari Glass Art Museum showcasing modern architecture and glass art, and local sushi restaurants featuring fresh seafood. Visitors can relax at Fugan Canal Kansui Park, explore the city via the scenic Toyama City Tram, and experience history at Toyama Castle. Unique culinary experiences include trying Black Ramen and visiting the historic Iwase Port Area. Peaceful shrines like Gokoku Shrine and Hie Shrine offer a glimpse into the area''s history. For shopping, Sougawa Arcade and Daiwa Department Store provide local vibes. Don''t miss the Owara Kaze no Bon festival in September, a celebration of music and dance. Toyama City was also recognized by The New York Times as a top travel destination.' where id = 'z89X8VZUPWEiQsQKnfUMr';
update content_bodies set title = '茂木町で、過ごす今日（冬ver）', description = 'この文章は、茂木町に関連するさまざまなリソースへのリンクを提供しています。道の駅もてぎの公式ウェブサイトが含まれており、地元の特産品やサービスに関する情報が得られます。また、茂木町観光協会のウェブサイトも紹介されており、地域の観光を促進しています。さらに、茂木町の公式ウェブサイトもあり、町の歴史や文化、観光名所についての情報が提供されています。' where id = '4mWuJ0mPekrPdaCwEr9SO';
update content_bodies set title = 'Today in Motegi Town (Winter Version)', description = 'This text provides links to various resources related to Motegi Town. It includes the official website of the Motegi Road Station, which offers information about local products and services. Additionally, it features the Motegi Town Tourism Association''s website, which promotes tourism in the area, and the official website of Motegi Town itself, providing insights into the town''s history, culture, and attractions.' where id = 'hy6n7WsIc5UoyfHLJzwrB';
update content_bodies set title = '感情 -上島エコツーリズム- 60秒ショートバージョン', description = '上島町観光協会が主催する「かみじまエコツーリズム」のPRイメージ動画のダイジェスト版です。かみじまエコツーリズムでは、シーカヤックやSUP、ファミリーキャンプ、電動キックボード、ハイキング、ポタリングなど、さまざまなアウトドアアクティビティを提供しています。上島町の美しい自然や島の独特な空気感、素朴でありのままの魅力をぜひ体感してみてください。' where id = 'bz5-CBcpymwsmiHtWWA5G';
update content_bodies set title = 'Feelings -Kamijima Eco Tourism- 60sec. Short ver.', description = 'This is a digest version of a promotional image video for ''Kamijima Eco Tourism,'' organized by the Kamijima Town Tourism Association. Kamijima Eco Tourism offers a variety of outdoor activities, including sea kayaking, stand-up paddleboarding (SUP), family camping, electric kickboarding, hiking, and cycling. Visitors are encouraged to experience the beautiful nature of Kamijima Town, the unique atmosphere of the island, and its simple, authentic charm.' where id = 'talbsqtaoi0d6nr57OlhH';
update content_bodies set title = '秋 -上島エコツーリズム-', description = '上島エコツーリズムの秋におすすめのアクティビティを紹介するイメージ動画です。' where id = '8fzgpXs0I4zDxIGgUq618';
update content_bodies set title = 'autumn -Kamijima Eco Tourism-', description = 'This is an image video featuring recommended activities for autumn in Kamijima Eco Tourism.' where id = '6_q8rNi47EQVT1VXHqXvH';
update content_bodies set title = '平櫛田中の庭', description = '今年も春がやってきました。彫刻家・平櫛田中がこの地に移り住んだのは九十八歳の時で、その後の二十年、三十年にわたり彫刻を掘るためにクスノキを購入し、周囲を驚かせました。今もこの庭を眺めながら彫刻を掘り続けているかもしれません。その優雅で力強い景色から、平櫛田中の息遣いが聞こえてくるようです。平櫛田中彫刻美術館は、彼の作品を保存し市民に公開するために昭和59年に開館しました。美術館は美しい庭園を有し、年間を通じて様々な企画展やイベントを開催しています。開館時間は午前10時から午後4時までで、火曜日は休館日です。観覧料も手頃で、音声と画像による作品解説サービスも提供されています。' where id = '2QqGG6bSwmD4vMNLU2kTa';
update content_bodies set title = 'Japanese garden of Hirakushi Denchū', description = 'Spring has arrived again this year. Sculptor Hirakushi Denchū moved to this place at the age of ninety-eight. For the next twenty to thirty years, he purchased camphor trees to carve sculptures, surprising those around him. Perhaps even now, he continues to carve while gazing at this garden. The elegant yet powerful scenery seems to echo the indomitable spirit of Hirakushi Denchū. The Hirakushi Denchū Sculpture Museum, established in October 1984, preserves and publicly displays the works of this modern Japanese sculptor, a recipient of the Order of Culture and an honorary citizen of Kodaira City. The museum features a beautiful garden overlooking the Tamagawa Josui and hosts various exhibitions and events throughout the year. Visitors can enjoy guided audio-visual explanations of the artworks. The museum is open from 10 AM to 4 PM, closed on Tuesdays, and offers affordable admission fees.' where id = '5iYEclvDqFfqq6bsxmh-R';
update content_bodies set title = '【絶景茨城】ネモフィラ［4K］茨城県ひたちなか市（国営ひたち海浜公園）', description = '茨城県ひたちなか市にある国営ひたち海浜公園は、ネモフィラの美しい花々で知られ、空と融合する鮮やかな青の風景を楽しむことができます。公園の面積は約190ヘクタールで、春には水仙やチューリップ、初夏にはネモフィラやバラ、夏には百日菊、秋にはコキアやコスモスと、四季折々の花々が楽しめます。自転車道やBMXコース、ピクニックエリアも整備されており、自然を愛する人々や家族連れにとって理想的な観光地です。' where id = 'tj56sOtUON8wFPzDS_GPQ';
update content_bodies set title = 'Hitachi Seaside Park - Nemophila [4K] Ibaraki Prefecture, Japan', description = 'Hitachi Seaside Park, located in Hitachinaka City, Ibaraki Prefecture, is renowned for its breathtaking nemophila flowers, creating a stunning blue landscape that merges with the sky. The park covers approximately 190 hectares and features a variety of seasonal flower gardens, including daffodils and tulips in spring, nemophila and roses in early summer, zinnias in summer, and kochia and cosmos in autumn. Visitors can enjoy cycling paths, BMX courses, and picnic areas, making it a perfect destination for nature lovers and families alike.' where id = 'G_Gk4KPy7XNqK_PwNKG05';
update content_bodies set title = '長崎ばーどアイ４Ｋ　三菱造船所のジャイアント・カンチレバークレーン', description = 'このコンテンツでは、長崎の三菱造船所にあるジャイアント・カンチレバークレーンの4K空撮映像を紹介しています。ドローンを使用して撮影された映像は、この印象的な構造物と造船業におけるその重要性を示しています。' where id = 'Hwy8h6tuUYFgesurLbWFy';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Mitsubishi Shipbuilding''s Giant Cantilever Crane', description = 'This content features a 4K aerial view of the giant cantilever crane at Mitsubishi Shipbuilding in Nagasaki. The footage is captured using a drone, showcasing the impressive structure and its significance in the shipbuilding industry.' where id = '2_3EqR5nrNmjvGoDtkFpf';
update content_bodies set title = '審査員特別賞「立ち上がろう雲仙市」', description = '第17回NCCふるさとCM大賞で受賞した作品です。ふるさと長崎をテーマにした30秒の動画を募集しました。協賛は十八親和銀行です。' where id = 'vmluTWsvDH2DHh0-HfT9C';
update content_bodies set title = 'Special Jury Award ''Let''s Stand Up Unzen City'' by Ryuji Shibata', description = 'This work won the 17th NCC Hometown CM Award. A 30-second video showcasing the hometown of Nagasaki was solicited. Sponsored by Juhachi Shinnwa Bank.' where id = 'aypHCo9IjSNkHymNGqddx';
update content_bodies set title = 'ハイパーラプス 福岡市 4k (ウルトラHD) - フルバージョン', description = 'この動画は、福岡市の観光名所を4KウルトラHDで紹介するハイパーラプス映像です。百道浜や福岡タワー、キャナルシティ博多、大濠公園など、さまざまなランドマークが登場します。視聴者は、字幕機能をオンにすることで撮影場所を確認でき、より楽しめる内容となっています。監督は栄川幸、音楽はWolves Unite Japan, Inc.によるものです。福岡市についての詳細は、公式観光サイトやSNSを訪れることが推奨されています。' where id = 'qHVhunGE1gKGiotCvU_rv';
update content_bodies set title = 'Hyperlapse Fukuoka City, Japan 4k (Ultra HD) - Full ver.', description = 'This video presents a hyperlapse tour of Fukuoka City, showcasing various landmarks and attractions in stunning 4K Ultra HD. Viewers can explore notable sites such as Momochihama, Fukuoka Tower, Canal City Hakata, and Ohori Park, among others. The video includes subtitles that display the shooting locations, enhancing the viewing experience. Directed by Yuki Eikawa, the film features music by Wolves Unite Japan, Inc. For more information about Fukuoka City, viewers are encouraged to visit the official tourism websites and social media channels linked in the description.' where id = 'ofshgyHh9WWSied8huUUH';
update content_bodies set title = '絶景！大島 三原山火口をドローン空撮', description = '大島は東京都心から高速ジェット船で最短1時間45分の距離にあります。三原山の火口を間近で見ることができるほか、広大な「砂漠」や海面から突き出た「筆島」といったダイナミックな景観が楽しめます。自転車やキャンプなど、豊かな自然の中でのアクティビティも充実しており、訪れる人々を魅了する魅力あふれる大島が待っています。' where id = 'hxbcAhY1eWsmdnLEELcRS';
update content_bodies set title = 'Enchanting Tokyo - Is this really Tokyo? - Volcano Island OSHIMA (Full ver.)', description = 'Oshima Island is located just 1 hour and 45 minutes from central Tokyo by high-speed jet ferry. The island offers stunning scenery, including the close-up view of Mt. Mihara''s volcanic crater, a vast ''desert'', and ''Fudeshima'', a rock formation that juts out from the sea. Visitors can engage in various activities such as camping and cycling, allowing them to fully experience the island''s rich natural environment. Oshima Island is a charming destination that promises to enchant all who visit.' where id = 'uSi3MlkgGxxmS3_Wsf1Wr';
update content_bodies set title = '八丈島', description = '東京から飛行機で1時間弱で到着する八丈島は、大自然と向き合える島です。日本でも降水量がトップクラスとなる八丈島は、巨大なシダ植物や、枯れることのない湧水によって岩盤が削られたポットホールなど独自の自然を育んでいます。島ではトレッキングはもちろんランニングや釣りなども楽しめます。身体を動かすアクティビティを楽しんだ後は、豊かな自然に囲まれた天然温泉でリラックスすることができ、週末のリフレッシュには最適な環境です。アクセスは、羽田空港からの飛行機が1日3便、片道約55分、または竹芝桟橋からの船が毎日運航されており、片道約10時間20分です。' where id = 'turSSo4GvZ-gNqdK6BzXA';
update content_bodies set title = 'Enchanting Tokyo HACHIJOJIMA Island (Full ver.)', description = 'Hachijojima Island, located less than an hour''s flight from Tokyo, offers a unique outdoor experience. Known for its high precipitation, the island features a distinctive environment with giant ferns and potholes formed by continuous spring water. Visitors can engage in various activities such as hiking, running, and fishing. After an active day, they can unwind in natural hot springs surrounded by lush nature, making it an ideal spot for a refreshing weekend getaway. Access to the island is available via airplane from Haneda Airport, with three flights daily taking approximately 55 minutes, or by boat from Takeshiba Pier, which takes about 10 hours and 20 minutes.' where id = 'lg-OQxHc06tb-XcUXmeFj';
update content_bodies set title = '青ヶ島', description = '青ヶ島は、東京から南に358㎞離れた太平洋上に位置し、アメリカの環境保護NGOによって「死ぬまでに見るべき世界の絶景13選」に日本で唯一選出され、世界中から注目を集めています。動画「Enchanting Tokyo AOGASHIMA Island」では、珍しい二重カルデラや地熱による水蒸気噴出「ひんぎゃ」など、独特な景観を紹介しています。また、自然と共生する島の生活や信仰についても探求しています。アクセスは、八丈島空港からのヘリコプターが1日1便（約20分）と、八丈島からの船（週4・5回、約2時間30分）があります。' where id = 'GFzZhkuvJRmhPQeATQM7d';
update content_bodies set title = 'Enchanting Tokyo AOGASHIMA Island (Full ver.)', description = 'Aogashima Island, situated 358 kilometers south of Tokyo in the Pacific Ocean, is the only Japanese site recognized by a US-based NGO as one of the ''World’s Top 13 Most Beautiful Views to See Before You Die.'' This has garnered global attention. The video ''Enchanting Tokyo AOGASHIMA Island'' showcases the island''s unique features, including its rare double caldera and geothermal steam eruptions known as ''hingya.'' It also delves into the island''s lifestyle and beliefs that harmonize with nature. Access to Aogashima is available via helicopter from Hachijojima Airport, with one flight daily taking about 20 minutes, or by boat from Hachijojima, with 4-5 trips weekly, taking approximately 2 hours and 30 minutes.' where id = 'FMvF6wCy5Yk2b_MsFRBXM';
update content_bodies set title = '【外国人移住者】山奥のフランス人 - 父の背中篇', description = '熊野の山奥に住むフランス人移住者の家族を紹介する動画です。子どもは父の背中を見て育ち、父はその背中を子に見せています。彼らの田舎暮らしのテーマは「手間を楽しむ」であり、今日は田舎暮らしの師匠と共に薪を作る特別な体験をしています。自分の山から木を切り出し、薪にする過程は特別なものです。三重県御浜町についての詳細は、下記のウェブサイトをご覧ください。月に2本の動画をアップする予定で、視聴者にはいいね、コメント、チャンネル登録をお願いしています。インスタグラムも始めました。' where id = '_8_4Ba27hXbT85PXw6BMO';
update content_bodies set title = 'French Immigrant in the Mountains - A Father''s Influence', description = 'This video features a French family living in the mountains of Kumano, Japan. The child learns from the father''s example, while the father demonstrates his skills. The theme of their rural life is ''enjoying the effort.'' Together with a mentor, the French immigrant engages in the special experience of cutting wood from their own mountain to make firewood. For more information about Mihama Town in Mie Prefecture, visit the provided website. The channel plans to upload videos twice a month, and viewers are encouraged to like, comment, and subscribe. An Instagram account has also been started.' where id = 'fH3MnWIk7EhP8UalTpL1e';
