update content_bodies set title = 'イントロダクション', description = 'この映像は、森の京都に位置する6つの市町（亀岡市、南丹市、京丹波町、綾部市、福知山市、京都市右京区京北）の大自然の風景や伝統、文化、そして人々の暮らしを紹介します。イントロダクションでは、京都市右京区京北に住む一瀬裕子さんが、幼少期に祖父母と共に過ごした森の奥の小屋を探しに行く旅を描いています。' where id = '6IpJTzPODBkj1XLrg5B6m';
update content_bodies set title = 'Introduction', description = 'This video explores the natural landscapes, traditions, culture, and daily lives of the people in the six cities and towns of ''Mori no Kyoto'' (Kameoka City, Nantan City, Kyotanba Town, Ayabe City, Fukuchiyama City, and Ukyo Ward in Kyoto City). The introduction features Yuko Ichinose, who lives in Ukyo Ward, as she embarks on a journey to find the cabin deep in the forest where she lived with her grandparents during her childhood.' where id = 'PfeVyyaKX17bM_2x_HmNu';
update content_bodies set title = 'ひらけ岡山城【予告編映像】', description = 'この予告編映像では、謎の少女と彼女の歌声が紹介されます。9月14日（水）には新しい岡山城が見えてきます。ムービーやイベント情報をお楽しみにし、詳細は https://kin-ujo.jp/ をご覧ください。' where id = 'PUuD1TtpMOkLOq8r_o0NZ';
update content_bodies set title = 'Open Okayama Castle [Trailer]', description = 'This trailer introduces a mysterious girl and her captivating song. On September 14th, a new Okayama Castle will be revealed. Stay tuned for the movie and event information, and discover the full details at https://kin-ujo.jp/' where id = 'MQ5G4B86sH5_2t2ffON2v';
update content_bodies set title = '舞鶴、特別クルーズ', description = '人気の「海軍ゆかりの港めぐり遊覧船」の特別便では、特定のゲームやアニメのファン向けに護衛艦の見学に特化したコースが設定されています。この特別便は、ファンにとって貴重な体験を提供します。今後も特別便の運航を企画していく予定ですので、ぜひご期待ください。' where id = 'Xk1rz50NanXO-m-jkglvZ';
update content_bodies set title = 'MAIZURU, Special Cruise', description = 'This special cruise offers a unique experience on the ''Maizuru Bay Sightseeing Boat'', specifically designed for fans of a certain game or anime. The tour focuses on visiting escort ships, providing an exclusive opportunity for enthusiasts. Future special cruises will be planned, so stay tuned for more exciting offerings.' where id = 'JTIWa84i20XvynwjX8Ve3';
update content_bodies set title = '知らなきゃ損！愛知観光で行きたい感動ドライブ7選【穴場＆絶景】', description = '愛知県の旅行や観光に役立つドライブスポットを紹介する動画です。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供しています。メンバーは旅行を通じて人生を豊かにすることを目指しており、視聴者が新しい可能性を発見できるようサポートしています。公式SNSをフォローして、最新情報をチェックしてください。' where id = 'T0qBgCNNHD-6Yc-KSCKue';
update content_bodies set title = 'Don''t Miss Out! 7 Emotional Drive Spots to Visit in Aichi【Hidden Gems & Scenic Views】', description = 'This video introduces various driving spots in Aichi Prefecture, perfect for travel and sightseeing. If you have any recommendations that are not mentioned in the video, please share them in the comments! The channel aims to provide enjoyable travel information, covering everything from sightseeing to accommodation and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, follow their official social media accounts.' where id = 'cWJn1OIUSsDK63ymNJwSo';
update content_bodies set title = 'a letter from ~島を継ぐ~', description = 'この動画は「a letter from ~島を継ぐ~」について紹介しています。' where id = '0qMbJVBEirda0G3ZAcd19';
update content_bodies set title = 'a letter from ~島を継ぐ~', description = 'This video introduces ''a letter from ~島を継ぐ~''.' where id = 'SYXhVFVD5PI13CY9nXzfU';
update content_bodies set title = '京都舞鶴の春', description = '京都北部に位置する舞鶴市は、美しい山々に囲まれた海のまちです。春になると、多くの桜の名所が訪れる人々を魅了します。舞鶴市は、桜の美しさを楽しむための観光地として知られています。' where id = 'i_gdzq9XVQcpVoZwm_cgt';
update content_bodies set title = 'Spring in Maizuru, Kyoto', description = 'Maizuru City, located in the northern part of Kyoto, is a beautiful coastal town surrounded by stunning mountains. The area is known for its many cherry blossom viewing spots, making it a popular destination during the spring season.' where id = 'hRoUDKwfltDWe4yps1dWQ';
update content_bodies set title = '暮らしのそばに、ほら世界。', description = '市内へ向かうトンネルを抜けると、目の前に海と街が同時に現れる。港を囲む斜面には家々がひしめき、かつては外国人や志士、幕臣が行き交った場所である。現在もポルトガルのお菓子やオランダの商館、中華街、造船所、うまい魚料理が共存している。日本の西の端に位置する長崎市は遠い印象があるが、海と街、人々の距離は近い。地元の人々は、長崎市民の懐の広さがこの街を常に進化させてきたと語る。この意味を理解するには、何度か訪れる必要がありそうだ。' where id = 'n8Rr1lMqEuit67NN8wYph';
update content_bodies set title = 'Close to Life, Here Comes the World.', description = 'As you pass through the tunnel heading into the city, the sea and the town appear simultaneously before you. Houses are densely packed on the slopes surrounding the port. Historically, this city was a crossroads for foreigners arriving from across the sea and Japanese patriots and samurai heading towards it. Today, a mix of Portuguese sweets, Dutch trading posts, Chinatown, shipyards, and delicious seafood coexist. Located at the western edge of Japan, Nagasaki City feels distant, yet the proximity of the sea, the town, and its people is striking. The locals say that the open-mindedness of Nagasaki citizens has continuously evolved the city into something new. It seems I will need to visit several more times to fully understand this sentiment.' where id = 'cOKKbAAHuym9SFjnyNrTy';
update content_bodies set title = '舞鶴赤れんがパーク紹介動画', description = 'この動画は、京都にある舞鶴赤れんがパークの紹介VTRです。舞鶴赤れんがパークの公式ウェブサイトは、http://akarenga-park.com/ です。' where id = 'lFddVDtWTuuW4pyhK60ob';
update content_bodies set title = 'Introduction to Maizuru Red Brick Park', description = 'This is a video introduction to Maizuru Red Brick Park in Kyoto. For more information, visit the official website at http://akarenga-park.com/' where id = 'V5aszRyoyG4lY9cA9vFmh';
update content_bodies set title = 'ART&FACTORY JAPAN トレーラー', description = '第3回日本国際観光映像祭は、世界の映像クリエイターたちと観光映像の未来を探るために「ART&FACTORY JAPAN」を開催します。この新しいコンテスト形式は、ポルトガルの観光映像祭ART&TURが始めたもので、クリエイターたちを観光地に招待し、その地域の課題解決のために短編映像を制作します。今年はCOVID-19の影響を受け、日本からのクリエイターが鹿児島県与論町に招待されます。彼らは2021年2月に与論島で3泊4日滞在し、それぞれの才能を活かした観光映像を制作します。制作された映像は、京都の清水寺で開催される第3回日本国際観光映像祭でプレミア上映され、コンテストが行われます。詳細は日本国際観光映像祭のウェブサイトをご覧ください。' where id = 'pL0Ak0FfTgJ9AHIn_XAIk';
update content_bodies set title = 'ART&FACTORY JAPAN TRAILER', description = 'The Japan World''s Tourism Film Festival will host ''ART&FACTORY JAPAN'' to explore the future of tourism films and digital marketing through a contest with global creators. This new contest format, initiated by the Portuguese festival ART&TUR, invites creators to a tourist destination to produce short films addressing local issues. This year, due to the COVID-19 pandemic, Japanese creators will be invited to Yoron town in Kagoshima prefecture. They will stay on Yoron Island for 4 days and 3 nights in February 2021 to create tourism films showcasing their talents. The films will premiere at the 3rd Japan International Tourism Film Festival at Kiyomizu Temple in Kyoto, where a competition will take place. For more details, visit the festival''s website.' where id = 'EKbEnSxakkTD4vLFOeQtI';
update content_bodies set title = 'THE ROOTS #05 人に伝えたくなるメロン', description = '穏やかな瀬戸内海の因島重井町はスイカの名産地ですが、極上のマスクメロンが栽培されていることはあまり知られていません。村上智規さんは、稼業として「因島メロン」を継ぎ、「熊八屋」を盛り立てています。「熊八屋」は彼がメロンに惚れ込んで婿入りした農家の屋号で、初代の名に由来します。智規さんは五代目で、甘さは測れるが美味しさは心を動かすものだと語ります。彼は地元の子どもたちにもメロンの魅力を伝え、給食に取り入れるなどしています。メロンも子どもたちも、島の穏やかな時間の中で愛され、育まれています。さあ、ひとくち、召し上がれ。' where id = 'JnlzkuoHId5TfS5DyHe4F';
update content_bodies set title = 'THE ROOTS #05 A Melon Worth Sharing', description = 'In the tranquil island of Innoshima, known for its watermelons, a rare and exquisite type of musk melon is cultivated by a select few farmers. Tomonori Murakami, who has taken over the family business ''Kumahachiya,'' is dedicated to promoting the unique ''Innoshima Melon.'' The name ''Kumahachiya'' comes from the first ''Kumahachi'' and reflects the local tradition of unique shop names. Tomonori, the fifth generation, emphasizes that while sweetness can be measured, true deliciousness moves the heart. He aims to share the joy of melons with local children, even incorporating them into school lunches. The melons, like the children, thrive in the island''s nurturing environment, embodying the essence of love and care. Enjoy a bite!' where id = '_JShQ5TmLaBHoNH3iSHzq';
update content_bodies set title = 'THE ROOTS #02 一年で嫁ぐにんにく', description = '福山市加茂町で農業を営む岡本啓二さんは、20年前から農業に従事し、3年前からにんにくの栽培を始めました。無農薬での栽培を行っており、除草剤を使わないため、畑には雑草が生い茂り、虫も集まります。この方法は手間がかかり、心配も尽きませんが、彼は「娘」と呼ぶにんにくを大切に育てています。愛情をたっぷり受けたにんにくは、雑味がなく素直な味わいを持ち、他の野菜も同様です。岡本さんは、にんにくを塩こしょうだけで炒めるシンプルな調理法をおすすめしています。まずはひとかけ、味わってみてください。' where id = '0mPF_e6n3DtR7AJoM9RzM';
update content_bodies set title = 'THE ROOTS #02 Garlic Grown in a Year', description = 'Keiji Okamoto has been farming in Kamo Town, Fukuyama City, for 20 years and started growing garlic three years ago. He practices organic farming, avoiding pesticides and herbicides, which leads to a weedy field and attracts insects. This method requires more effort and brings worries, but he cherishes his ''daughters''—the garlic plants. These plants, nurtured with love, grow with a pure and straightforward flavor, similar to other vegetables he cultivates. Okamoto recommends a simple cooking method: sautéing garlic with just salt and pepper. He invites everyone to try a clove first.' where id = 'Ujr_hq5ufjfPSvi46HQm2';
update content_bodies set title = 'GEO DINING SHIMOKITA', description = '下北半島からの招待状が届いたら、特別な旅の準備を始めましょう。ここでしか体験できない、下北ジオダイニングというユニークな旅です。ジオガストロノミー・ツーリズムは、2019年のクールジャパンマッチングアワードで《特別賞》を受賞しました。' where id = 'b5AA84OF7Si7CUNDpYDjJ';
update content_bodies set title = 'GEO DINING SHIMOKITA', description = 'Shimokita is inviting you to prepare for a unique travel experience. This is a one-of-a-kind journey in the world, known as Shimokita GEO-DINING. The concept of geogastronomy tourism has been recognized with the ''Special Award'' at the Cool Japan Matching Award 2019.' where id = '-iGOZfeTEoKKcvBmXsjdd';
update content_bodies set title = '鰹節工場見学', description = '鰹節（かつおぶし）の製造過程を観察できる工場見学です。-50℃の冷凍庫に入る体験や、鰹節と鰹だしの試食も行えます。このツアーでは、日本料理に欠かせない食材である鰹節の伝統的な製造方法を深く理解することができます。' where id = 'JAZud21O0qT7tabJ2WrZL';
update content_bodies set title = 'Katsuobushi (Bonito Flake) Factory Tour', description = 'Experience a factory tour focused on the production of bonito flakes, known as Katsuobushi. Visitors will have the opportunity to observe the entire manufacturing process, enter a -50℃ freezer, and sample both bonito flakes and bonito soup. This tour offers a unique insight into the traditional methods of producing this essential ingredient in Japanese cuisine.' where id = 'qVil_oReZ4JYEn4oouGz4';
update content_bodies set title = 'KIPPUSHI -WATER NEIGHBORHOOD- 盛岡市木伏緑地', description = '木伏緑地は、JR盛岡駅北口から徒歩4分の場所に位置する、北上川沿いの約200メートルの帯状の公園です。豊かな緑と空が広がるこの場所は、楽しみたい人々が集まることで、いつの間にか「ここにしかない風景」が生まれる特別な空間となっています。' where id = 'qnwz0OtwhfGSmxUDEdBpe';
update content_bodies set title = 'KIPPUSHI -WATER NEIGHBORHOOD- Morioka City Kibushi Green Space', description = 'Kibushi Green Space is a linear park approximately 200 meters long along the Kitakami River, located just a 4-minute walk from the north exit of JR Morioka Station. This area is characterized by rich greenery and open skies. It serves as a gathering place for people who want to enjoy the outdoors, and as they come together, unique and beautiful landscapes emerge that can only be found here.' where id = 'Khxul0Y5Iym7JaPjzHCJZ';
update content_bodies set title = '筏下り【北山村】夏限定！！', description = 'この動画では、和歌山県の北山村で楽しめる夏限定の筏下りについて紹介しています。' where id = 'C2XdgTF35qGy6iO8hdYyp';
update content_bodies set title = 'Ika River Rafting in Kitayama Village - Summer Limited!', description = 'This video introduces the summer-limited Ika River rafting experience in Kitayama Village, Wakayama.' where id = 'o94PCCE8CP1QvD2EGhCjc';
update content_bodies set title = 'わかやま“ほんまもん”アウトドア', description = '和歌山では、キャンプやさまざまなアウトドアアクティビティを通じて、真のアウトドア体験を提供しています。この地域は美しい自然景観で知られており、リラックスや探検を求める旅行者にとって理想的な目的地です。また、温泉も楽しむことができ、和歌山でのアウトドアアクティビティの魅力をさらに高めています。' where id = 'flvgg1gbH3S0GmDJC0PAB';
update content_bodies set title = 'Wakayama ''Authentic'' Outdoor', description = 'Wakayama offers a genuine outdoor experience, featuring activities such as camping and various outdoor adventures. The region is known for its beautiful natural landscapes, making it an ideal destination for travelers seeking relaxation and exploration. Visitors can also enjoy hot springs, adding to the overall appeal of the outdoor activities available in Wakayama.' where id = '5Ge_i7zP3Pl2gL4iREsr_';
update content_bodies set title = '【指宿市】長太郎焼陶芸体験・白薩摩絵つけ体験', description = '長太郎焼陶芸体験では、カップや皿などの手作り陶器を制作することができ、完成品は1か月後に届けられます。また、白薩摩絵つけ体験では、カップや皿に絵を描くことができ、こちらも完成品は1か月後に届けられます。詳細については、指宿観光体験グループのウェブサイトをご覧ください。' where id = 'puF-_d9djRsjj-K4ZMROQ';
update content_bodies set title = 'Ibusuki City Chotaro Ware Pottery Experience and White Satsuma Painting Experience', description = 'The Chotaro ware pottery experience allows participants to create handmade pottery items such as cups or plates, with the finished products delivered after one month. Additionally, the White Satsuma painting experience offers the opportunity to paint on a cup or plate, with the completed work also delivered after one month. For more information, you can contact the Ibusuki sightseeing & experience group through their website.' where id = 'TOd56nAFKPPDIK0Naidtn';
update content_bodies set title = '【指宿市】青隆寺文化体験', description = '青隆寺では、青隆寺の美しい庭を散策し、写経体験や瞑想体験を行う文化体験を提供しています。詳細については、指宿観光・体験グループのウェブサイトをご覧ください。' where id = 'k1l3jZd7xqZKkgxH6UJ7C';
update content_bodies set title = 'Ibusuki City Seiryuji Temple Cultural Experience', description = 'The Seiryuji Temple offers a cultural experience that includes walking around the beautiful Seiryuji garden, participating in a sutra copying experience, and engaging in meditation. For more information, you can contact the Ibusuki sightseeing & experience group through their website.' where id = 'H3rQ0UAtVE4pxIIKe0JCg';
update content_bodies set title = 'いぶすき元湯温泉', description = 'いぶすき元湯温泉は、指宿温泉を代表する老舗の公衆浴場であり、観光客にとって魅力的なスポットです。周辺には宿泊施設や砂むし温泉もあり、訪れる人々は路地を散策しながら立ち寄ることができます。温泉の歴史と文化を感じながら、リラックスしたひとときを過ごすことができる場所です。' where id = '9C1ChDBWEleffFKRzAhSj';
update content_bodies set title = 'Ibusuki Moto Yu Onsen, Japan', description = 'Ibusuki Moto Yu Onsen is a historic public bath that represents the Ibusuki Onsen area. Nearby, visitors can find accommodations and sand baths, making it a popular stop for tourists who enjoy exploring the local alleys.' where id = '9M2rn7Xb3u1N4w5loE3WH';
update content_bodies set title = 'AIZU LAMPLIGHT 末廣酒造', description = 'この動画では、AIZU LAMPLIGHT 末廣酒造について紹介しています。' where id = 'kvbVGVb1fyUmmAlgl3snN';
