update content_bodies set title = 'AIZU LAMPLIGHT 七日町駅', description = 'この動画はAIZU LAMPLIGHT 七日町駅について紹介しています。' where id = 'TkXJ4tuPrgKsW-rLW-W8l';
update content_bodies set title = 'AIZU LAMPLIGHT Nanokamachi Station', description = 'This video introduces AIZU LAMPLIGHT Nanokamachi Station.' where id = 'v_ADoWcTuYdn83DadE5tO';
update content_bodies set title = '四国まんなかガチ秘境物語', description = '徳島県立池田高校の探求科の生徒たちが、にし阿波を舞台にした修学旅行のPR動画を制作しました。この修学旅行プランは、祖谷地方を中心に展開されており、高校生たちの熱い地元愛が込められています。豊かな自然が創り上げた壮厳な景色やアクティビティを通じて、あなたもこの美しい地域の魅力を肌で体感してみませんか？' where id = 'cAPHNTONYqbxF004rVSg-';
update content_bodies set title = 'Shikoku Manaka Secret Wilderness Story', description = 'Students from the Tokushima Prefectural Ikeda High School''s inquiry department have created a promotional video for a school trip set in the Nishi-Awa region. This trip plan, centered around the Iya region, reflects the students'' deep love for their local area. Experience the majestic landscapes created by rich nature and engage in various activities that allow you to feel the essence of this beautiful region.' where id = 'at-pFQQOjPLuY_9sCPSTX';
update content_bodies set title = '丹波山観光PR 氷瀑', description = '大自然が織りなす氷の芸術「氷瀑」を見に、山梨県丹波山村の不動滝へ行きませんか？秩父多摩甲斐国立公園内に位置するこの場所では、冬限定の絶景を体験できます。凍り付いた風景は、まるで時が止まったかのような美しさを持ち、訪れる人々に感動を与えます。' where id = 'xzUtT9X2YhAUFH2E3jwmc';
update content_bodies set title = 'Tamba-yama Tourism PR: Ice Falls', description = 'Experience the frozen art of nature with the stunning ice falls in Tamba-yama Village, located within the Chichibu-Tama-Kai National Park. Visit the Fudo Falls, where winter transforms the landscape into a breathtaking scene that feels as if time has stopped. This winter-only spectacle offers a unique opportunity to witness the beauty of ice formations in a serene natural setting.' where id = '5rUBfCiTsD80XmybLk-SW';
update content_bodies set title = 'ともによろこぶ Celebrate Tomonoura Together -Francais-', description = 'このウェブサイトは、日本の美しい港町、鞆の浦を祝うことに特化しています。地域の文化やコミュニティの参加を促進するイベントや活動に関する情報やリソースを提供しています。' where id = 'gnN9Cx0oBfp7e8S-9kCtQ';
update content_bodies set title = 'Celebrate Tomonoura Together -Francais-', description = 'This is a website dedicated to celebrating Tomonoura, a picturesque port town in Japan. The site provides information and resources related to events and activities that promote the local culture and community engagement.' where id = 'cJZf5YaTJcY_RYIFIt54J';
update content_bodies set title = 'ユニークベニュー', description = '愛知・名古屋ＭＩＣＥ推進協議会が制作したこのプロモーション動画では、地域の歴史や文化、技術を象徴する個性豊かなユニークベニューを紹介しています。動画を通じて、施設の雰囲気を感じながら、その魅力や見どころを知ることができます。愛知・名古屋ＭＩＣＥ推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューロー、及びMICE関連の関係者で構成されています。' where id = 'h-GEIWmVHo0BvsmOk8DzK';
update content_bodies set title = 'Technical Visit & Unique Venue –Journey to Nagoya-', description = 'This promotional video by the Aichi-Nagoya MICE Promotion Council showcases unique venues that embody the region''s history, culture, and technology. Viewers will experience the atmosphere of these venues and discover their highlights. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders in the region.' where id = 'OOL4cC13B78Qfldq83BZW';
update content_bodies set title = '[ver.POP] 愛知県の8K映像', description = 'この動画では、愛知県の美しさと文化を8K映像で紹介しています。名古屋城や熱田神宮、味噌煮込みうどんや寿司などの伝統的な料理が登場します。また、有松・鳴海の古い町並みや香積寺などの歴史的な名所、香嵐渓や阿寺の七滝といった自然の魅力も強調されています。活気ある大須商店街や静かな徳川園、独特の常滑焼も紹介され、最後にはトヨタ博物館や名古屋駅周辺の街並みが映し出されます。監督は栄川幸、撮影は松村隆、空撮は馬場基成が担当しています。' where id = '2cC-KuYaYn51kecGIaqpV';
update content_bodies set title = '[ver.POP] AICHI Japan in 8K - Aichi Prefecture', description = 'This video showcases the beauty and culture of Aichi Prefecture, Japan, through stunning 8K visuals. Key locations featured include Nagoya Castle, Atsuta Jingu Shrine, and traditional dishes like Misonikomiudon and sushi. The video also highlights historical sites such as Arimatsu Narumi Traditional Townscape and Kojakuji Temple, as well as natural attractions like Korankei Gorge and Atera-no-Nanataki Waterfall. Viewers can explore the vibrant Osu Shopping District, the serene Tokugawaen Garden, and the unique Tokoname-yaki pottery. The video concludes with a glimpse of the Toyota Automobile Museum and the cityscape around Nagoya Station. Directed by Yuki Eikawa, with photography by Takashi Matsumura and aerial shots by Motonari Baba.' where id = 'mF9EmQdEOou194POPYTwE';
update content_bodies set title = '[ver.DEEP] AICHI Japan in 8K - 愛知県', description = 'この動画は、愛知県の美しさと魅力を8K解像度で紹介しています。オアシス21、リニア・鉄道館、豊川稲荷、竹島、伊良湖岬など、さまざまなロケーションが登場します。また、ひつまぶし、天むす、味噌カツといった地元の名物や、犬山城や尾張大国霊神社などの文化的なスポットも紹介されています。セリサイト鉱山や常滑やきもの散歩道など、ユニークな体験も含まれています。この視覚的な旅は、愛知の自然、文化、料理の本質を捉えています。' where id = 'HMipjAZGfsN78qSGorRlr';
update content_bodies set title = '[ver.DEEP] AICHI Japan in 8K - Aichi Prefecture', description = 'This video showcases the beauty and attractions of Aichi Prefecture in stunning 8K resolution. It features various locations, including Oasis 21, SCMAGLEV and Railway Park, Toyokawa Inari Temple, Takeshima Island, and Cape Irago. The video also highlights local delicacies such as Hitsumabushi, Tenmusu, and Miso-Katsu, as well as cultural sites like Inuyama Castle and Owari Okunitama Shrine. The exploration includes unique experiences like the Sericite Mine and the Tokoname Pottery Footpath. The visual journey captures the essence of Aichi, blending nature, culture, and cuisine.' where id = 'KaUmwobg3WYlp_Q1jgAvx';
update content_bodies set title = 'オススメ『沖縄の絶景な海５選！』', description = 'この動画では、沖縄の美しい海を5つ紹介しています。南城市の『カフーバンタ』、知念岬公園、読谷村の『三重城』、恩納村の『BEACH51ザネ浜』、本部町の『海洋博公園』が含まれています。沖縄の海岸線の美しさを楽しむための、のんびりとした散歩を通じてこれらの絶景スポットを探索する内容です。' where id = 'seBMbk2z7Gkvl4Ae8L3nd';
update content_bodies set title = 'Recommended ''5 Stunning Beaches in Okinawa'' for Sunny Days! #577', description = 'This video showcases five beautiful beaches in Okinawa, including ''Kafu Banta'', ''Chinen Misaki Park'' in Nanjo City, ''Miejijo'' in Yomitan Village, ''BEACH51 Zane Beach'' in Onna Village, and ''Okinawa Ocean Expo Park'' in Motobu Town. It offers a leisurely exploration of these scenic spots, perfect for enjoying the beauty of Okinawa''s coastline.' where id = 'Q4aaD_6kDXnOkFebyKv1g';
update content_bodies set title = '大道芸ワールドカップin静岡', description = '11月1日から11月4日までの4日間、静岡で大道芸ワールドカップが開催されます。このイベントは「大道芸世界一」を決めるもので、今年で27回目を迎えます。世界23か国から102組のアーティストが集結し、静岡市内の繁華街や駿府城などでパフォーマンスを披露します。この機会にぜひ静岡を訪れてみてください！' where id = 'DuTKnOgJYlBIeG00RQhFg';
update content_bodies set title = 'Street Performance World Cup in Shizuoka', description = 'The Street Performance World Cup will be held in Shizuoka from November 1 to November 4. This event, which determines the ''World''s Best Street Performer,'' is in its 27th year. A total of 102 artists from 23 countries will gather to showcase their talents. Performances can be enjoyed in the bustling streets of Shizuoka City and at Sunpu Castle. Don''t miss this opportunity to visit Shizuoka!' where id = 'vyago3XIvCodmodehRKa8';
update content_bodies set title = '丹波山観光PR 武田家の隠し金山探検', description = '武田信玄の時代、丹波山村には黒川金山の採掘のために金山奉行が置かれていたと伝えられています。村内にはその跡が残っており、訪れる人々はガイドと共に金山跡を探検することができます。また、東京都の水源でもある沢を歩きながら、水の恵みを五感で感じることができます。' where id = 'jrw1PzNhCEiNaRWQ5ZhEb';
update content_bodies set title = 'Exploring the Hidden Gold Mine of the Takeda Clan in Tanbayama', description = 'During the era of Takeda Shingen, it is said that a gold mine magistrate was established in Tanbayama Village for the extraction of gold from the Kurokawa Mine. Remnants of this history can still be found within the village, and visitors can explore the mine site with a guide. As you walk along the streams that serve as a water source for Tokyo, take the opportunity to experience the blessings of water through your senses.' where id = 'SQCN4xcWVi4JDnGhaxzGJ';
update content_bodies set title = '南信州まつかわ だんだん好きになる旅', description = '南信州まつかわは、人々や自然、暮らしとの出会いを通じて、何度でも訪れたくなる魅力を提供します。このブランドムービーは、まつかわの本質を紹介し、訪問者にこの地域のユニークな側面を探求し、楽しむことを促しています。詳しくはウェブサイトをご覧ください。' where id = '03FzESxHrU1tW43dAJHKP';
update content_bodies set title = 'Matsukawa: A Journey to Fall in Love Again', description = 'Matsukawa in southern Nagano invites you to discover its charm through encounters with people, nature, and lifestyle that you will want to experience again and again. This brand movie showcases the essence of Matsukawa, encouraging visitors to explore and appreciate the unique aspects of this region. For more details, visit the website.' where id = 'eGqvw-PK06FVo-J-Pcb0u';
update content_bodies set title = '愛知・名古屋産業視察: スギ製菓株式会社', description = '愛知・名古屋ＭＩＣＥ推進協議会が制作したこのプロモーション動画では、産業視察を受け入れる企業の一つであるスギ製菓株式会社を紹介しています。実際の視察の様子や担当者へのインタビューを通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を感じることができます。ぜひご覧いただき、愛知・名古屋の産業の魅力を体験してください。' where id = 'rCs29f1STi82YuzrN32Ik';
update content_bodies set title = 'Aichi-Nagoya Technical Visit: Sugiseika Co., Ltd.', description = 'This promotional video by the Aichi-Nagoya MICE Promotion Council showcases a company that offers tours for visitors to learn about the industry. The video includes actual tours and interviews with staff, providing viewers with a sense of the inspection site''s atmosphere and the unique appeal of technical visits in this region. It invites viewers to experience the charm of Aichi-Nagoya''s industrial landscape.' where id = 'QtPEtcTcm3RaByCJPlSrm';
update content_bodies set title = '[愛知・名古屋産業視察] 堀田新五郎商店', description = '愛知・名古屋ＭＩＣＥ推進協議会が制作したこのプロモーション動画では、産業視察を受け入れる企業の様子や、担当者へのインタビューを通じて、視察先の雰囲気や地域特有のテクニカルビジットの魅力を紹介しています。実際の視察の様子を通じて、視聴者はこの地域ならではの体験を感じることができる内容となっており、ぜひご覧いただきたい動画です。' where id = 'VVKGAxMZvSuWKLn0bExuy';
update content_bodies set title = '[Aichi-Nagoya Technical Visit] HOTTASHINGORO', description = 'This promotional video by the Aichi-Nagoya MICE Promotion Council showcases a company that offers tours for visitors to learn about the industry. It features actual tours along with interviews from staff, providing viewers with a sense of the inspection site''s atmosphere and the unique appeal of technical visits in this region. The video aims to highlight the engaging experiences available to those interested in industrial tours.' where id = 'OsKhi5q-Gr-LJGPXhCn_a';
update content_bodies set title = 'テクニカルビジットとユニークな会場 -愛知への旅-', description = '愛知・名古屋MICE推進協議会が制作したこのプロモーション動画では、産業視察が可能な企業の視察の様子や担当者へのインタビューを紹介しています。実際の視察を通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を感じることができる内容となっています。愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューロー、及びMICE関連のステークホルダーで構成されています。' where id = 'bl9VbV_EO0tKQBhI-2rmy';
update content_bodies set title = 'Technical Visit & Unique Venue –Journey to Aichi-', description = 'This promotional video, created by the Aichi-Nagoya MICE Promotion Council, showcases companies that can be toured to learn about the industry. It features actual tours and interviews with staff, allowing viewers to experience the atmosphere of the inspection sites and the unique appeal of technical visits in this region. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders.' where id = 'x-o7vL6Plu1D81abXra4w';
update content_bodies set title = 'カンゲキ', description = '津の花火は想像以上にキレイでした。' where id = 'sT1gdrowQDyLToOhvmk4T';
update content_bodies set title = 'Kangeki', description = 'The fireworks in Tsu were more beautiful than I imagined.' where id = 'zYLHFUn6_jrwSN4AXyPa3';
update content_bodies set title = 'テクニカルビジットとユニークな会場 -名古屋への旅-', description = '愛知・名古屋MICE推進協議会が制作したこのプロモーション動画では、産業視察を受け入れる企業の様子や、担当者へのインタビューを通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を紹介しています。実際の視察の様子を通じて、視察先の魅力を感じることができる内容となっており、ぜひご覧いただきたいです。愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューローなどで構成されています。' where id = 'O9rJbEJGRdBaI3c_5K5Do';
update content_bodies set title = 'Technical Visit & Unique Venue –Journey to Nagoya-', description = 'This promotional video, created by the Aichi-Nagoya MICE Promotion Council, showcases companies that welcome visitors for industry tours. It features actual tours along with interviews from staff, allowing viewers to experience the atmosphere of the inspection sites and the unique appeal of technical visits in this region. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders.' where id = 'Tru4tjftXOcBUEFyPbxec';
update content_bodies set title = 'COOL！NAGOYA - ファミリーブログ', description = '「COOL！NAGOYA」は、名古屋の観光魅力を家族向けのVLOG形式で紹介する動画シリーズです。家族旅行の体験を通じて名古屋の魅力を伝えています。動画では、中部国際空港、BUCYO COFFEE、名古屋港水族館、久屋大通公園、うなぎ飯三吃、名古屋王子大飯店天空塔、若宮八幡社、大須商店街、矢場とん、そして日本レゴランド®リゾートなど、さまざまなスポットが紹介されています。各スポットへのリンクもあり、名古屋を訪れる人々にとっての包括的なガイドとなっています。' where id = 'ealAaS11kKR2HFPYAgw7F';
update content_bodies set title = 'COOL! NAGOYA - FAMILY VLOG', description = 'The video series ''COOL! NAGOYA'' showcases the attractions of Nagoya through a family-oriented VLOG format. It highlights the charm of Nagoya by sharing experiences from a family trip. The video features various locations, including Chubu Centrair International Airport, BUCYO COFFEE, Nagoya Port Aquarium, Hisaya Odori Park, Uya Hitsumabushi, Nagoya Prince Hotel Sky Tower, Wakamiya Hachiman Shrine, Osu Shopping District, Yabaton, and LEGOLAND Japan Resort. Each location is linked for further exploration, making it a comprehensive guide for visitors to enjoy the best of Nagoya.' where id = 'Zfe-tTTCD153WmMLaa4Ch';
update content_bodies set title = '抑留から交流へ〜「舞鶴モデル」による語り継ぎの新しいかたち②引揚記念館〜', description = '引揚記念館は、引き揚げの歴史を通じて平和の重要性を伝えています。この館は、過去の出来事を振り返りながら、平和の尊さを「世界へ、未来へ」と発信することを目的としています。' where id = 'cQnFuZ0ISBAtgiXzWkcbp';
update content_bodies set title = 'From Detention to Exchange: A New Form of Storytelling through the ''Maizuru Model'' - Part 2: The Returnee Memorial Museum', description = 'This text introduces the Returnee Memorial Museum, which communicates the importance of peace through the historical facts of repatriation, aiming to share this message with the world and future generations.' where id = 'sI1YTk8ntoQMLakw6Y9_D';
update content_bodies set title = '300年続く沖縄の超定番行事食 ｢ムーチーを作りました～！｣', description = 'この動画では、300年の歴史を持つ沖縄の伝統的な料理「ムーチー」を紹介しています。オープニングダイジェストの後、ムーチー作りに使用する材料が紹介されます。続いて、カボチャと紅芋の餅作りの過程が示され、包み作業や蒸し作業も行われます。最後に、完成したムーチーが披露され、沖縄の伝統におけるムーチーの文化的意義が強調されます。視聴者は沖縄の文化や料理を体験しながら、バーチャル散歩を楽しむことができます。' where id = 'rT9ZDEz0FE7UVjzWj-FIg';
update content_bodies set title = '300-Year-Old Okinawan Traditional Event Food: Making Moochi!', description = 'This video showcases the traditional Okinawan dish ''Moochi,'' which has been celebrated for 300 years. It begins with an opening digest, followed by an introduction to the ingredients used in making Moochi. The video then demonstrates the process of making pumpkin and red potato rice cakes, including the wrapping and steaming stages. Finally, it reveals the completed dish, highlighting the cultural significance of Moochi in Okinawan traditions. Viewers are invited to enjoy a virtual stroll through Okinawa, experiencing the local culture and cuisine.' where id = '8FRZOZlZkoTM4msswhZEJ';
update content_bodies set title = '熊本県錦まち観光プロモーション2018', description = 'この動画は熊本県錦町を紹介しています。錦町の歴史や魅力を伝える内容で、一般社団法人錦まち観光協会のプロモーション活動の一環として制作されています。動画には、山の中にある海軍の町としての特徴や、ひみつ基地ミュージアムの情報も含まれています。さらに、錦町役場の公式ウェブサイトやフェイスブックページも紹介されています。' where id = 'oNl1s_D8cpNMhXRVyLBQg';
update content_bodies set title = 'Kumamoto Prefecture Nishiki Town Tourism Promotion 2018', description = 'This is a video introducing Nishiki Town in Kumamoto Prefecture. It features the unique aspects of Nishiki Town, including its history and attractions. The video is part of the promotional efforts by the Nishiki Town Tourism Association. Additional resources include the Nishiki Town Hall website and Facebook page, as well as the secret base museum located in the mountains, which highlights the town''s naval history.' where id = 'uKKLe6Rn3UV0LlfC0jUjS';
update content_bodies set title = '木曽観光連盟 -Kiso Tourist Federation- Official Channel のライブ配信', description = 'この動画は、木曽観光連盟 -Kiso Tourist Federation- Official Channel のライブ配信について紹介しています。木曽地域の観光情報やイベントをリアルタイムで視聴できる機会を提供しており、視聴者は木曽の魅力を直接体験することができます。' where id = 'QW2z7nLaIBCfPz9LdOz-4';
update content_bodies set title = 'Live Streaming of Kiso Tourist Federation - Official Channel', description = 'This video introduces the live streaming of the Kiso Tourist Federation - Official Channel.' where id = 'dMCVvqLsJ5oLCzgPVFvPY';
update content_bodies set title = 'ネズミ講で国が潰れたってやばくない？', description = 'この動画では、ネズミ講が原因で国が潰れた事例について紹介しています。ネズミ講は、参加者が新たな参加者を勧誘することで利益を得る仕組みですが、その持続可能性がないため、最終的には多くの人々が損失を被ることになります。このような状況が国全体に及ぶと、経済や社会に深刻な影響を与えることがあるため、注意が必要です。' where id = 'PnLba03bFVKcveSho3R87';
update content_bodies set title = 'Isn''t it crazy that a country collapsed due to a pyramid scheme?', description = 'This video introduces the topic of a country that collapsed because of a pyramid scheme.' where id = 'EW_D7CXSiRbuWV_S8bZ7Z';
update content_bodies set title = '利尻町ウニ種苗生産センターの紹介', description = '利尻町に位置するウニ種苗生産センターは、エゾバフンウニの子どもを生産する施設です。この動画では、センターの利用方法について案内しています。利尻島の観光情報は「りしぷら」で確認できます。詳細は https://www.rishiri-plus.jp/ をご覧ください。また、ウニっこ図鑑の特設サイトも https://www.rishiri-plus.jp/unikko/ でご覧いただけます。' where id = 'ZK9-xcDJSVVtMOUJwi7Xs';
update content_bodies set title = 'Introduction to Rishiri Uni Seed Production Center', description = 'The Rishiri Uni seed production center, located in Rishiri Town, is dedicated to producing juvenile Ezo Bafun sea urchins. This video provides guidance on how to utilize the facility. For more information on tourism in Rishiri Island, please visit ''Rishipura'' at https://www.rishiri-plus.jp/. Additionally, you can explore the special site for the Uni-kko Encyclopedia at https://www.rishiri-plus.jp/unikko/.' where id = '4VHbODT1ksE2efTKBJB1n';
update content_bodies set title = '【王道】兵庫旅行で絶対外せない！兵庫の定番観光スポット7選', description = 'この動画は兵庫県への旅行を計画している方に向けて、兵庫の定番観光スポットを7つ紹介しています。動画で紹介されていないおすすめスポットがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、国内外の旅行情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。詳細は公式SNSをチェックしてください。' where id = 'pEEByQ8exzwU3qxLv5yGM';
update content_bodies set title = 'Must-Visit Tourist Spots in Hyogo: 7 Classic Recommendations', description = 'This video serves as a guide for those traveling to Hyogo Prefecture, showcasing seven essential tourist spots. If you have any additional recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For more information, check out their official social media accounts.' where id = 'dBSUHJLPBheaoeMS7jMct';
update content_bodies set title = '日本には絶対ない…', description = 'この動画では、日本には絶対に存在しないものについて紹介しています。海外旅行やヨーロッパ、特にギリシャ神話に関連する内容が含まれており、海外旅行好きな人々とつながることを目的としています。' where id = 'ixt-a1uCb4-eX79f9kVdN';
update content_bodies set title = 'There are absolutely no such things in Japan…', description = 'This video introduces things that absolutely do not exist in Japan.' where id = '_NX1W4K96V7zxKokCI_Zd';
update content_bodies set title = '秋田旅行するなら定番で外さない名所巡り！秋田観光の王道スポット7選！', description = 'この動画は秋田県への旅行を計画している方に向けて、おすすめの名所を紹介しています。動画で紹介されていないおすすめスポットがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、国内外の旅行情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。紹介されている7つのスポットは、角館武家屋敷通り、田沢湖、男鹿真山伝承館、秋田市民市場、白神山地、小安峡大噴湯、鳥海山です。訪れる前に公式サイトで最新情報を確認することをお勧めします。' where id = 'BpA6MLIot0PAhSeeMXnTD';
update content_bodies set title = 'Must-Visit Attractions in Akita: 7 Classic Spots for Your Trip!', description = 'This video serves as a guide for those planning to travel to Akita Prefecture, showcasing recommended attractions. If you have any additional suggestions not covered in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. The video highlights seven key locations: Kakunodate Samurai District, Lake Tazawa, Oga Man''yō Heritage Center, Akita City Market, Shirakami-Sanchi, Oyasukyo Gorge, and Mount Chokai. Viewers are advised to check official websites for the latest information before visiting.' where id = '1npm1pMdVvz22LFZ-ljwI';
update content_bodies set title = '日本の品格を静かに保ち続ける栃木県', description = '栃木県は、荘厳な文化と豊かな大自然、そして美意識を兼ね備えた地域です。ここでは、心の豊かさを上質に満たすことができる静かな環境が広がっています。歴史的な意義と自然の美しさが調和した栃木の魅力を訪れることで体験できます。' where id = 'OI6aE_OcVgWGW0FSEKrKf';
update content_bodies set title = 'The Grace of Japan, TOCHIGI Digest', description = 'Tochigi Prefecture quietly maintains the grace of Japan, characterized by its majestic culture, rich nature, and aesthetic sensibility. The region offers a peaceful environment that enriches the heart and soul. Visitors can explore the harmonious blend of historical significance and natural beauty that Tochigi has to offer.' where id = '638jghw7fViXujlMSTxxs';
update content_bodies set title = '埼玉グルメツアー', description = '埼玉グルメツアーでは、埼玉地域の多様な地元料理が紹介されています。伝統的な日本料理であるニボトや、独特の食感と風味で知られる加須うどんが取り上げられています。また、独自の調理法が特徴のすったてうどんも注目されています。川幅うどんはその豊かな味わいで評価されています。さらに、行田の人気料理であるフライや、愛される焼き鳥も楽しめます。最後に、浦和の名物であるうなぎの蒲焼も味わえ、埼玉の食文化を体験できるツアーとなっています。' where id = 'EBQ5JKh7bOR7jhGdk1J5d';
update content_bodies set title = 'Saitama Gourmet Tour', description = 'The Saitama Gourmet Tour showcases a variety of local delicacies from the Saitama region. It features Niboto, a traditional Japanese dish, and Kazo Udon, known for its unique texture and flavor. Suttate Udon, another local specialty, is highlighted for its distinct preparation method. Kawahaba Udon is also included, celebrated for its rich taste. Additionally, the tour offers Furai, a popular dish in Gyoda, and Yakitori, a beloved grilled chicken skewer dish. Lastly, visitors can enjoy grilled eel in Urawa, a delicacy that is well-regarded in the area. Each dish represents the culinary heritage of Saitama, making this tour a must for food enthusiasts.' where id = 'yJsrdk8eDNX7rLO8w4XvY';
update content_bodies set title = 'COOL！NAGOYA - ファミリーブログ', description = '名古屋観光の魅力を紹介するハイライト動画「COOL！NAGOYA」では、家族での旅行をテーマにしたVLOG形式で名古屋を旅する様子が描かれています。中部国際空港やBUCYO COFFEE、名古屋港水族館、ヒサヤオオドオリパーク、ひつまぶし う家名駅本店、名古屋プリンスホテルスカイタワー、若宮八幡社、大須商店街、矢場とん矢場町本店、レゴランド・ジャパン・リゾートなど、名古屋の様々な観光スポットが紹介されています。各スポットへのリンクもあり、視聴者が訪問計画を立てやすくなっています。このプロジェクトは公益財団法人名古屋観光コンベンションビューローによって制作されています。' where id = '1v-smcpWn3kdWX-L9zM7z';
update content_bodies set title = 'COOL! NAGOYA - FAMILY VLOG', description = 'The highlight video ''COOL! NAGOYA'' showcases the attractions of Nagoya. It introduces a family trip concept, encouraging viewers to explore Nagoya through a VLOG format. The video features various locations, including Chubu Centrair International Airport, BUCYO COFFEE, Nagoya Port Aquarium, Hisaya Odori Park, Hitsumabushi Uya, Nagoya Prince Hotel Sky Tower, Wakamiya Hachiman Shrine, Osu Shopping District, Yabaton, and LEGOLAND Japan Resort. Each location is linked for more information, making it easy for viewers to plan their visit. The project is produced by the Nagoya Convention & Visitors Bureau.' where id = 'RUq9DBbqBosW7rSS0O7CO';
update content_bodies set title = '飛行機ので横になれるビジネスクラスやばすぎない！？', description = 'この動画では、飛行機のビジネスクラスについて紹介しています。特に、横になれる快適さや利便性に焦点を当てており、海外旅行を楽しむ人々にとっての魅力を伝えています。ビジネスクラスの特典やサービスについても触れ、旅行の質を向上させる要素を紹介しています。' where id = 'HO4QDFARvfoDycAI6-1Fk';
update content_bodies set title = 'Isn''t the Business Class on Airplanes Where You Can Lie Down Amazing!? #travel #connectwithtravelenthusiasts #overseastravel #vlog #Vietnam', description = 'This video introduces the business class on airplanes that allows you to lie down.' where id = 'mHWF5lwb1ZDVCiXRchHm3';
update content_bodies set title = '秋田旅行で絶対食べたい！地元に愛される老舗＆名物グルメ7選', description = 'この動画は秋田県への旅行や観光を考えている方に向けて、地元のグルメスポットを紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、国内外の旅行情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて新しい可能性を発見し、人生を豊かにすることを願っています。' where id = 'CkH9WZU_anFWpg4P-cQ2M';
update content_bodies set title = 'Must-Try Local Gourmet and Long-Established Restaurants in Akita: 7 Selections', description = 'This video serves as a guide for those traveling to Akita Prefecture, showcasing various gourmet spots. If you have any recommendations not mentioned in the video, please feel free to share them in the comments. The channel, ''Travel Master,'' aims to enrich your travel experiences by providing a wide range of information on sightseeing, transportation, accommodation, and dining, both domestically and internationally. The team behind the channel believes in the transformative power of travel and encourages viewers to explore new possibilities through their journeys.' where id = 'RsFQAv4nXJ--88koL3g6Y';
update content_bodies set title = '【心に残る絶景＆歴史】和歌山旅行で一度は行きたい！観光スポット7選', description = '和歌山県への旅行を計画している方に向けて、王道の観光スポット7選を紹介する動画です。動画に紹介されていないおすすめスポットがあれば、コメント欄でシェアしてください。また、40代・50代からでも始められるマイル活用法も配信中です。旅行の達人チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。メンバーは年間の半分を旅に費やし、視聴者が新しい可能性を発見できるような情報を届けています。' where id = 'Im80pefvmTN5i4ETaqYv5';
update content_bodies set title = 'Must-Visit Scenic and Historical Spots in Wakayama', description = 'This video serves as a guide for those planning to travel to Wakayama Prefecture, showcasing seven classic tourist spots. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel also offers tips on how to effectively utilize miles for travel, especially for those in their 40s and 50s. The Travel Master channel aims to enrich lives through travel, providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team, which spends nearly half the year traveling, hopes to inspire viewers to discover new possibilities and enhance their lives through travel experiences.' where id = '7R6-Zy4Txvd1iOip0Cqv0';
update content_bodies set title = '沖縄旅行 春休み！『賑わう那覇空港』♯948 おきなわさんぽ沖縄散歩 American Supermarket Jimmy Misato Branch and Island Grill', description = '春休みが始まり、那覇空港は多くの観光客で賑わっています。この動画では、沖縄の各地をのんびりと散歩しながら紹介しています。ウェルカムホールやお土産売り場、到着ロビー、バス・タクシー乗り場、出発ロビー、チェックインカウンター、搭乗者降り場、モノレール那覇空港などのセグメントが含まれています。賑やかな旅行シーズンの沖縄の雰囲気を伝えることを目的としています。' where id = 'bTQM6x2pZIWEwMZvLpiHZ';
update content_bodies set title = 'Okinawa Trip: Spring Break! ''Busy Naha Airport'' #948 Okinawa Walk American Supermarket Jimmy Misato Branch and Island Grill', description = 'As spring break begins, Naha Airport is bustling with many tourists. This video showcases various parts of Okinawa while taking a leisurely stroll. It includes segments such as the welcome hall, souvenir shops, arrival lobby, bus and taxi stands, departure lobby, check-in counters, boarding areas, and the monorail at Naha Airport. The video aims to provide a glimpse into the vibrant atmosphere of Okinawa during the busy travel season.' where id = 'd5jxxTd9TkTmfGOTUBIu4';
update content_bodies set title = 'ドローン映像　青森の四季２０２０', description = '2020年にドローンで撮影された青森県の四季の映像を集めたものです。青森の自然の美しさが四季折々に表現されており、地域の魅力を伝える内容となっています。' where id = '5FGd0TW8GQ18vJTnsQafu';
update content_bodies set title = 'Drone Footage: Aomori''s Four Seasons 2020', description = 'This is a collection of footage captured by drone in Aomori Prefecture, showcasing the beauty of the four seasons throughout the year 2020.' where id = 's9gPHB02D4yN8XPGEHgfP';
update content_bodies set title = '熊本旅行するなら食べないと後悔する！熊本の人気グルメ７選', description = 'この動画は、熊本県を訪れる旅行者のためのガイドとして、絶対に食べるべき人気のグルメを7つ紹介しています。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しく快適にすることを目的としています。チャンネルの運営メンバーは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを促しています。最新の旅行情報やヒントを得るために、公式のSNSアカウントをフォローしてください。' where id = 'ufNF8BbIEThKsYPe8RicN';
update content_bodies set title = 'Must-Try Gourmet Foods in Kumamoto: 7 Popular Picks', description = 'This video serves as a guide for travelers visiting Kumamoto Prefecture, showcasing seven popular gourmet foods that you shouldn''t miss. If you have any additional recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on sightseeing, transportation, accommodation, and dining, all designed to make your journey more enjoyable and comfortable. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their adventures. For more travel tips and updates, follow their official social media accounts.' where id = 'wPCcJms5amgGsvEiwr_-s';
update content_bodies set title = '2021五所川原立佞武多「暫」完成', description = '立佞武多「暫」の組立作業が3日間にわたって行われ、その様子を収めたタイムラプス動画が公開されました。来年こそは祭りが開催されることを願っています。' where id = 'GAvji2piIY5i8vP95uNq-';
update content_bodies set title = 'Completion of Goshogawara Tachineputa ''Zan'' 2021', description = 'A time-lapse video of the three-day assembly work for the Tachineputa ''Zan'' has been released. We hope that the festival will be held next year.' where id = 'YrH3F5l0w3uuyjIi9D7ac';
update content_bodies set title = '海外の航空会社最高やー', description = 'この動画では、海外の航空会社について紹介しています。海外旅行が好きな人々とつながりたいという思いが込められており、特にフィリピンに焦点を当てています。旅行の楽しさや航空会社の魅力を伝える内容となっています。' where id = 'pmSVwl4Igvw58Z8YeemnL';
update content_bodies set title = 'Overseas Airlines Are the Best!', description = 'This video introduces overseas airlines.' where id = '2Q-0TQbOditBSmhPw2We5';
update content_bodies set title = 'COOL！NAGOYA - ファミリーブログ', description = '「COOL！NAGOYA」は名古屋の観光魅力を紹介する精選動画です。家族での冒険をテーマに、VLOG形式で名古屋を一緒に楽しむことを提案しています。動画では、新特麗亞名古屋中部国際空港、BUCYO COFFEE、名古屋港水族館、久屋大通公園、鰻魚飯三吃Uya名驛店、名古屋王子大飯店天空塔、若宮八幡社、大須商店街、矢場炸豬排矢場町本店、日本樂高樂園®度假村など、さまざまなスポットが紹介されています。各スポットへのリンクもあり、名古屋の魅力を家族で楽しむための包括的なガイドとなっています。' where id = 'kk31D1pDJrHrVZkrKgFbl';
update content_bodies set title = 'COOL! NAGOYA - FAMILY VLOG', description = 'COOL! NAGOYA is a curated video showcasing the attractions of Nagoya. The concept revolves around a family adventure, inviting viewers to explore Nagoya together through a VLOG format. The video features various locations, including Chubu Centrair International Airport, BUCYO COFFEE, Nagoya Port Aquarium, Hisaya Odori Park, Uya Nagoya Station for eel rice, Nagoya Prince Hotel Sky Tower, Wakamiya Hachiman Shrine, Osu Shopping District, Yabaton for pork cutlet, and LEGOLAND Japan Resort. Each site is linked for further exploration, making it a comprehensive guide for families looking to enjoy Nagoya''s charm.' where id = 'm_VmgYnJ1Mu2swZpMbU19';
update content_bodies set title = '一本釣り真鯛の調理', description = '加太名物の一本釣りの真鯛を紹介します。最高のブランド鯛を、加太観光協会青年部長の稲野雅則氏がさばきます。新鮮で美味しい鯛を提供しており、ぜひ食べに来てください。' where id = 'iVNF9UahnxThCb-9SpRxN';
update content_bodies set title = 'Cooking of Line-Caught Sea Bream', description = 'This is the famous line-caught sea bream from Kada. The best brand of sea bream is prepared by Masanori Inano, the head of the Kada Tourism Association''s Youth Division, at the live fish restaurant Inasa. It is truly delicious sea bream. Please come and taste it!' where id = '9tz5AN3urmTtew20U9ZVx';
update content_bodies set title = '埼玉体験ツアー', description = '埼玉体験ツアーでは、訪問者がさまざまな伝統的な日本の工芸やスタジオを探索する機会を提供します。参加者は、独自の染色技術で知られる武州中島紺屋の染色スタジオを訪れることができます。秩父メイセン館では、メイセン絹織物の技術が紹介されています。陶玉は伝統的な日本の陶器を専門としています。長瀞ガラススタジオ「そう」では、ガラス製作の技術を学ぶことができます。また、久保翔太郎の和紙スタジオでは、和紙の職人技が強調されています。各場所はユニークな体験を提供し、訪問者が埼玉の豊かな文化遺産を理解する手助けをします。' where id = 'KeUe49XbeNp_WHuHJM6Tg';
update content_bodies set title = 'Saitama Experience Tour', description = 'The Saitama Experience Tour offers visitors a chance to explore various traditional Japanese crafts and studios. Participants can visit the Bushu Nakajima Konya dyeing studio, known for its unique dyeing techniques. The Chichibu Meisenkan showcases the art of Meisen silk fabric. Togyoku specializes in traditional Japanese pottery. The Nagatoro Glass Studio So provides insights into glass-making. Additionally, Shotaro Kubo’s Japanese paper studio highlights the craftsmanship of washi paper. Each location offers a unique experience, allowing visitors to appreciate the rich cultural heritage of Saitama.' where id = 'iuaxQqYcJ7S0RMT3FJCUb';
update content_bodies set title = '22歳で意識していること', description = 'この動画では、22歳という年齢において自分が意識していることについて紹介しています。' where id = 'VPqTqRImzOzouRJcbvABv';
update content_bodies set title = 'Things I Am Aware of at 22', description = 'This video introduces the things I am conscious of at the age of 22.' where id = 'P1bP-ZSloNWiGD0zEQmEI';
update content_bodies set title = '雪とある日のとおかまち', description = 'この動画は新潟県十日町市における雪の日の様子を紹介しています。十日町市の美しい雪景色や、日常の風景が映し出され、雪がもたらす特別な雰囲気を感じることができます。雪に覆われた街並みや、雪遊びを楽しむ人々の姿が描かれ、冬の魅力を伝える内容となっています。' where id = 'BbAK5hYJymVDlWzMH8xuQ';
update content_bodies set title = 'One snowy day in Tokamachi', description = 'This video introduces a snowy day in Tokamachi, Niigata Prefecture.' where id = 'y-kAzU6cX_Rdd7HK-VnXw';
update content_bodies set title = '世界中を旅した1年間で行ってよかった場所TOP3', description = 'この動画では、世界中を旅した1年間の中で特に訪れて良かった場所のトップ3を紹介しています。旅行の経験を通じて得た感動や思い出が詰まった内容となっており、視聴者にとっても旅行の参考になる情報が含まれています。どの場所が選ばれたのか、またその理由についても触れられており、旅行好きにはたまらない内容です。' where id = 'Gm87BO4vgbQrLMpCpkyZ8';
