update content_bodies set title = 'The Ultimate Guide to Nara Tourism: 7 Must-Visit Attractions', description = 'This video serves as a guide for those planning to travel to Nara Prefecture, showcasing popular tourist spots. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on various aspects of travel, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more information and updates, follow their official social media accounts.' where id = 'l2GeOa_ZDoTz8CWzX5zbz';
update content_bodies set title = '佐賀県・武雄のおいしい料理体験', description = '佐賀県武雄市観光協会の公式チャンネルでは、武雄の名物であるイノシシ肉と新鮮な野菜を使った料理体験を提供しています。この体験を通じて、地域の美味しい料理を楽しむことができます。予約は、提供されたリンクから行えます。' where id = 'pl1Ntb6YEeDWckmhBXakK';
update content_bodies set title = 'Special Cooking Experience in Takeo, Saga Prefecture', description = 'The official channel of the Saga Prefecture Takeo City Tourism Association offers a unique cooking experience featuring local specialties. Participants can enjoy cooking with wild boar meat and fresh vegetables, showcasing the region''s culinary delights. Reservations can be made through the provided link.' where id = 'WcRVvzhZb3c3YgOlX9D6T';
update content_bodies set title = '迷ったらココ！宮城観光で行くべき大崎市の観光＆グルメ7選', description = 'この動画は宮城県への旅行を考えている方に向けて、大崎市のおすすめ観光スポットを紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。また、40代・50代からでも始められるカンタンでお得なマイル活用法も配信中です。旅行の達人チャンネルは、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = 'nZomShoglezsVhu8aZjPa';
update content_bodies set title = 'Must-Visit Tourist Attractions and Gourmet Spots in Osaki City, Miyagi', description = 'This video serves as a guide for those traveling to Miyagi Prefecture, highlighting recommended spots in Osaki City. If you have any additional recommendations not mentioned in the video, please share them in the comments. The channel also offers tips on easy and cost-effective ways to utilize miles, especially for those in their 40s and 50s. The Travel Master channel aims to enhance your travel experience by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'YxazQB27WoeOy0zpg4x4h';
update content_bodies set title = '長野県 渋温泉 共同浴場 全9湯', description = '渋温泉は長野県に位置する有名な温泉地で、全9つの公衆浴場があります。訪れる人々は、伝統的な日本の温泉文化を体験することができます。アクセスも良好で、歴史と自然の美しさに恵まれた地域です。体験を共有したい方のために、インスタグラムのアカウントも開設されています。また、日本秘湯を攻める会のオリジナルオレンジタオルが、さまざまなセットで購入可能なリンクも提供されています。' where id = 'ioFQOCvjI_xJJX6BEyy-J';
update content_bodies set title = 'Shibu Onsen''s Nine Public Hot Springs (Nagano)', description = 'Shibu Onsen is a renowned hot spring area in Nagano, featuring nine public baths. Visitors can enjoy the unique experience of traditional Japanese onsen culture. The location is easily accessible, and the area is rich in history and natural beauty. For those interested in sharing their experiences, an Instagram account has been created. Additionally, original orange towels from the Nihon Hito Onsen Attack Club are available for purchase in various sets through provided links.' where id = 'DE5o57W_sbTnvLhmlET-S';
update content_bodies set title = '夜たび神戸～ハーバーランド前編', description = 'この動画では神戸の夜の楽しみ方を紹介しています。ハーバーランドは食事や買い物など、エンターテインメントの要素がすべて揃った活気あるエリアです。港町神戸を代表する美しい景色をクルーズ船から海上で楽しむことが必見です。' where id = 'issMlSdbh-MQrmMxUWjQF';
update content_bodies set title = 'Night Trip in Kobe - Harborland Part 1', description = 'This video introduces how to enjoy the night in Kobe. Harborland is a vibrant area where you can find a variety of entertainment options, including dining and shopping. A must-see is the stunning view of Kobe, a port town, from the sea while on a cruise ship.' where id = 'DuxuclQrbfAReZaQ7B98H';
update content_bodies set title = '夜たび神戸～ハーバーランド後編', description = '神戸の夜の楽しみ方を紹介する動画です。ハーバーランドは、食事や買い物、エンターテインメントが揃った神戸の重要なエリアです。特に、クルーズ船から見る港町神戸の美しい景色は必見です。' where id = 'BAV6bksB-TA89b70rV_Ux';
update content_bodies set title = 'Night Trip in Kobe - Harborland Part 2', description = 'This video introduces how to enjoy the night in Kobe. Harborland, a key area in Kobe, offers a complete entertainment experience with dining, shopping, and more. A must-see is the stunning view of the port town of Kobe from the sea, especially when viewed from a cruise ship.' where id = '3SsHd0b5xkDK7UwS5Macc';
update content_bodies set title = '2021年度森の京都文化観光サポーターラジオ 第3回「丹波の漆かき」', description = '京都FM丹波のラジオ番組「森の京都presents知っとる？伝統文化in 福知山」の放送音声です。森の京都文化観光サポーターが月1回福知山市の無形文化財を取り上げ、サポーターの目線で紹介します。第3回目は「丹波の漆かき」で、福知山市夜久野町は日本有数の漆の産地です。漆かき職人が伝統産業を守り続けています。番組前半では漆の基礎知識を紹介し、江戸時代に盛んだった漆かきの歴史や、現在の漆の90%が輸入であることを説明します。後半では、漆かき職人でNPO法人丹波漆の広報担当の山内耕祐さんをゲストに迎え、漆との出会いや福知山移住の理由、苦労や漆の魅力についてお話を伺います。山内さんの漆に対する熱い想いにサポーターも感動しました。' where id = 'QIsUsiWGBZJ-A_nUwTKEy';
update content_bodies set title = '2021 Forest Kyoto Cultural Tourism Supporter Radio Episode 3: ''Tamba Lacquer Harvesting''', description = 'This is the audio broadcast of the radio program ''Forest Kyoto presents: Do You Know? Traditional Culture in Fukuchiyama'' aired on Kyoto FM Tamba. The Forest Kyoto Cultural Tourism Supporters introduce intangible cultural assets from Fukuchiyama each month from their perspective. The third episode focuses on ''Tamba Lacquer Harvesting.'' Yaku no Town in Fukuchiyama, Kyoto Prefecture, is one of Japan''s leading lacquer-producing areas. Here, lacquer artisans work to preserve and pass on this traditional industry. The first half of the program covers basic knowledge about lacquer, noting that while lacquer harvesting thrived during the Edo period, 90% of lacquer used today is imported. The program highlights the value of this precious domestic lacquer. In the second half, guest Kousuke Yamauchi, a lacquer artisan and public relations officer for the NPO Tamba Lacquer, shares his experiences, including his encounter with lacquer, reasons for moving to Fukuchiyama, challenges faced, and the allure of lacquer. The supporters are moved by Yamauchi''s passionate commitment to lacquer.' where id = 'J_4Wvhm9j1rt4Ieh9QS2u';
update content_bodies set title = 'MIYAMOBI hiraya English', description = 'この動画はMIYAMOBI hiraya Englishについて紹介しています。' where id = 'OmdpIXlWeup5vb1kuAPFm';
update content_bodies set title = 'MIYAMOBI hiraya English', description = 'This video introduces MIYAMOBI hiraya English.' where id = '1g7CAAxoYzGFBMNz_vanA';
update content_bodies set title = 'SKY HOP BUS ぐるっと森の京都〈福知山編〉', description = 'この動画では、SKY HOP BUSの福知山編に焦点を当て、森の京都を巡るツアーについて紹介しています。' where id = 'yWBMKt2IwMA5oy-kdMbS7';
update content_bodies set title = 'SKY HOP BUS: Exploring the Forest of Kyoto - Fukuchiyama Edition', description = 'This video introduces the SKY HOP BUS, focusing on the Fukuchiyama edition of the Forest of Kyoto tour.' where id = '3a5ZaNxVEEmJIt8RG3iKW';
update content_bodies set title = 'MIYAMOBI tsurugaoka Chinese', description = 'この動画では、MIYAMOBI tsurugaoka Chineseを紹介しています。その特徴や提供内容について説明しています。' where id = 'LajLH2QO_rCppJMVa-A_j';
update content_bodies set title = 'MIYAMOBI tsurugaoka Chinese', description = 'This video provides an introduction to MIYAMOBI tsurugaoka Chinese, showcasing its features and offerings.' where id = '_E9TyCHqLQ3TBLNUlbqwB';
update content_bodies set title = '【京都 八瀬 比叡山】 八瀬もみじの小径、瑠璃光院、叡山ケーブル、三千院', description = 'この映像では、京都の紅葉スポットの中でも特に人気のある「八瀬もみじの小径」や「瑠璃光院」を美しい映像を通して紹介しています。内容は八瀬、八瀬もみじの小径、瑠璃光院、大原の三千院、叡山ケーブルに関するもので、これらの場所の美しい風景と静かな雰囲気を視聴者に伝えています。' where id = 'WmJrO9jMl1XaVhGEUwW7-';
update content_bodies set title = 'Kyoto Yase Mt.Hiei: Yase Momiji Path, Rurikoin, Eizan Cable Car, Sanzenin', description = 'This video showcases popular autumn foliage spots in Kyoto, particularly the Yase Momiji Path and Rurikoin, through beautiful visuals. The video includes segments on Yase, the Yase Momiji Path, Rurikoin, Sanzenin in Ohara, and the Eizan Cable Car, providing viewers with a glimpse of the stunning scenery and serene atmosphere of these locations.' where id = 'adeIUnlmgFvLxudiyx8Tb';
update content_bodies set title = '【滋賀 びわ湖】ミシガンクルーズ、琵琶湖ホテル、大津祭', description = '琵琶湖の雄大な景色や、絶景クルーズが楽しめる「ミシガン」の魅力を美しい映像と共に紹介しています。また、琵琶湖ホテルや大津祭の情報も含まれています。各スポットへのアクセス情報は、指定されたリンクを参照してください。' where id = 'MPy5yH9yoHIieg25AgtdD';
update content_bodies set title = 'Lake Biwa: Michigan Cruise, Biwako Hotel, Otsu Festival', description = 'Experience the breathtaking scenery of Lake Biwa and enjoy the stunning Michigan cruise. This presentation showcases the beauty of these attractions, including the Biwako Hotel and the Otsu Festival, accompanied by beautiful visuals. For access information to each spot, visit the provided link.' where id = '7Ypn6EjB9BKRlwG5BnFPl';
update content_bodies set title = '広尾町サンタランド ／北海道の絶景景色', description = '今回紹介するのは、北海道十勝に位置する「サンタランド」です。広尾町は、サンタクロースの故郷であるノルウェーのオスロ市から認められた、日本で唯一のサンタランドです。サンタランドの活動拠点であるフログン市と友好交流提携を結び、「愛と平和、感謝と奉仕」を基本理念にしたまちづくりを進めています。日本一早いクリスマス点灯式である「サンタランドツリー点灯式」が行われ、11月からは15万球のイルミネーションが楽しめます。また、2020年にはシンボルツリーとしてクリスマスツリーが植樹され、カップルにおすすめのスポットとなっています。' where id = '8gvoLC4GU8fyX-QAtJ5Qf';
update content_bodies set title = 'Hiroo Town Santa Land / Superb view of Hokkaido', description = 'This article introduces ''Santa Land'' located in Hiroo Town, Tokachi, Hokkaido, which is recognized as the first Santa Land in Japan and the first outside Norway''s Oslo, the hometown of Santa Claus. Hiroo Town has established a friendship and exchange partnership with Frogn City, the base of Santa Land''s activities, and is developing the town based on the philosophy of ''Love, Peace, Gratitude, and Service.'' The ''Santa Land Tree Lighting Ceremony'' is the earliest Christmas lighting event in Japan, featuring the ''Santa Land Illumination'' with 150,000 lights available from November. In 2020, a Christmas tree was planted as a symbol of the location, making it a recommended spot for couples.' where id = 'F1UihPZoeXSAJ5RwEm-V7';
update content_bodies set title = '網走から望むオホーツク海', description = 'この映像では、網走市から見たオホーツク海の絶景を紹介します。網走は能取湖や網走湖などの美しい湖に囲まれた地域で、特に流氷が有名です。毎年シベリアからやってくる流氷がオホーツク海を真っ白に染める光景は、多くの人々を魅了します。「オホーツクブルー」という言葉が示すように、澄んだ空とオホーツク海沿いの景色を楽しみながらのドライブもおすすめです。詳細はリンクをご覧ください。' where id = 'U7HL0zrtQTm6mCG1Ni-3q';
update content_bodies set title = 'Superb view of Hokkaido／Sea of Okhotsk', description = 'This video showcases the stunning views of the Sea of Okhotsk from Abashiri City, a region surrounded by lakes and the sea, including Lake Notoro and Lake Abashiri, both known for their scenic beauty. Abashiri is particularly famous for its drift ice, which arrives annually from Siberia, transforming the Sea of Okhotsk into a breathtaking white landscape. The term ''Okhotsk Blue'' reflects the clear skies and beautiful scenery along the coast, making it a perfect spot for scenic drives. For more information, visit the provided link.' where id = 'kKZJFHbzABn2JfQ94ujXK';
update content_bodies set title = 'サロマ湖展望台 4K／北海道の絶景景色', description = '北海道のオホーツク管内佐呂間町に位置する「サロマ湖展望台」を紹介します。この展望台は、日本で3番目に広いサロマ湖全体を見渡せる唯一の場所で、高い山に囲まれていないため、ここでしか楽しめない壮大なパノラマを提供します。晴れた日には、湖と海を隔てる砂州「龍宮街道」や、遠くに知床連山を望むこともできます。展望台には3つの望遠鏡が設置されており、サロマ湖の隅々まで眺めることができ、その眺望は一級品です。' where id = '4LsdjtUZ7-cV7o3BE3Caj';
update content_bodies set title = 'Lake Saroma Observatory 4K / Superb view of Hokkaido', description = 'This video introduces the Lake Saroma Observatory located in Saroma-cho, Okhotsk, which offers a unique panoramic view of Lake Saroma, the third largest lake in Japan. The observatory is the only place where visitors can see the entire lake, surrounded by no high mountains, providing an unparalleled vista. On clear days, one can also view the sandbar known as ''Ryugu Kaido'' that separates the lake from the sea, as well as the Shiretoko mountain range in the distance. The observatory is equipped with three telescopes, allowing visitors to explore every corner of Lake Saroma, ensuring a first-class viewing experience.' where id = '1_gujU-pGZSKv_PnWuJmz';
update content_bodies set title = '【4K高画質】北海道の絶景&ドローン映像で心の疲れを癒してください｜総集編 計19スポット', description = 'この動画は、北海道の魅力的な観光スポットを紹介する総集編です。昨年の絶景動画を基に、肉眼ではなかなか見られないドローン映像を含む4K動画で、計19スポットの美しい景色をお楽しみいただけます。神の道や円山公園、もいわ山夜景、さっぽろテレビ塔など、札幌市を中心に多彩な絶景が収められており、リラックスやながら視聴に最適です。' where id = '7G5wVKSj-QxT-7EfZJt12';
update content_bodies set title = 'Superb view of Hokkaido【compilation vol.1】', description = 'This video compilation showcases the stunning tourist spots and attractions of Hokkaido, featuring breathtaking views captured from various angles, including drone footage. The 4K video presents a total of 19 remarkable locations, making it perfect for relaxation and casual viewing. Highlights include Kan No Michi in Kaminokuni Town, Maruyama Park, Mt. Moiwa, Sapporo TV Tower, and many more scenic spots across Sapporo and beyond. Enjoy the beauty of Hokkaido like never before!' where id = 'tRb40OFQIwaxyRXpys4si';
update content_bodies set title = 'もいわ山山頂展望台クリスマスツリー 4K／北海道の絶景景色', description = '今回は、札幌の絶景夜景スポット「もいわ山山頂展望台」を紹介します。この展望台は、日本新三大夜景に認定されており、標高531mの藻岩山の山頂に位置しています。昼夜を問わず札幌の街を一望できるこの場所は、恋人の聖地としても知られ、カップルに人気です。12月25日まで、「幸せの鐘」は札幌で最も高いクリスマスツリーとして装飾され、夜には美しいイルミネーションが輝きます。ぜひ、素晴らしい夜景とイルミネーションを楽しんでください。' where id = 'dQOfDS8mZ3imD0K8exO8_';
update content_bodies set title = 'Mt. Moiwa Summit Observation Deck Christmas Tree 4K / Superb View of Hokkaido', description = 'This video introduces the Mt. Moiwa Summit Observation Deck, a spectacular night view spot in Sapporo, recognized as one of Japan''s New Three Great Night Views. At an altitude of 531m, Mt. Moiwa is centrally located in Sapporo, offering panoramic views of the city both day and night. The observation deck, known as a ''Lover''s Sanctuary,'' features the ''Bell of Happiness,'' making it a popular destination for couples. Until December 25th, the bell is adorned as the tallest Christmas tree in Sapporo, illuminated beautifully at night. Enjoy the stunning night views and festive lights.' where id = 's0Mxj2YgbG30ML47wRpJA';
update content_bodies set title = '羊蹄山 4K／北海道の絶景景色', description = 'この動画では、均整のとれた円錐形の成層火山「羊蹄山」を紹介します。別名「蝦夷富士」とも呼ばれ、札幌中心部から車で約2時間の後志地方南部に位置し、標高は1,898メートルです。羊蹄山は支笏洞爺国立公園に属し、日本百名山にも認定されています。登山スポットとしても人気があり、4種類の登山コースが用意されています。頂上からは日本海と太平洋の絶景を楽しむことができます。また、周囲には羊蹄山に降った雨や雪が長い年月をかけてろ過されたミネラル成分たっぷりの湧き水を汲めるスポットもあります。' where id = 'HLSbdJqFhkae_0e4cIahj';
update content_bodies set title = 'Mt. Yotei 4K / Superb View of Hokkaido', description = 'This video introduces the well-proportioned cone-shaped stratovolcano, Mt. Yotei, also known as ''Ezo Fuji''. Located about two hours by car from Sapporo in the southern Shiribeshi region, Mt. Yotei stands at an altitude of 1,898 meters and is part of Shikotsu-Toya National Park. It is recognized as one of Japan''s 100 famous mountains and is a popular destination for mountain climbing, offering four different climbing courses. From the summit, climbers can enjoy breathtaking views of both the Sea of Japan and the Pacific Ocean. Additionally, the area around Mt. Yotei features spots where visitors can collect mineral-rich spring water, filtered through the earth over many years from rain and snow that has fallen on the mountain.' where id = 'b6rd6rDXoeghhRdJLr-XY';
update content_bodies set title = '白老ポロト湖 冬編4K／北海道の絶景景色', description = '今回紹介するのは、北海道の白老町に位置するポロト湖です。この湖は周囲約4㎞、面積33haを誇り、湿原や森林に囲まれた自然豊かな場所にあります。ポロトという名前はアイヌ語で「大きな沼」を意味します。湖の南側には、アイヌの歴史を紹介するナショナルセンター「ウポポイ」があり、伝統的なアイヌの集落が再現されています。冬になると湖は凍り、ワカサギ釣りを楽しむことができます。' where id = 'HpBACJqzUaSkolADdkmbe';
update content_bodies set title = 'Lake Poroto Winter Edition 4K / Superb View of Hokkaido', description = 'This video introduces Lake Poroto located in Shiraoi Town, Hokkaido, showcasing the stunning natural scenery of Hokkaido from various angles. Lake Poroto has a circumference of about 4 km and covers an area of 33 hectares, surrounded by rich nature, including moors and forests. The name ''Poroto'' means ''big swamp'' in the Ainu language. On the southern shore of the lake, there is ''Upopoy'', a national center for ethnic symbiosis that presents the history of the Ainu people and recreates a traditional Ainu settlement. In winter, the lake freezes over, allowing for smelt fishing.' where id = 'Bo39diK8HVHde-6iAk1Io';
update content_bodies set title = '大迫力！海軍ゆかりの港めぐり遊覧船', description = '舞鶴東港から舞鶴湾を遊覧船でクルーズします。目の前に迫る護衛艦や海軍にゆかりのある造船所を訪れることができます。心地よい潮風を感じながら、海からの美しい景色を楽しんでみませんか。' where id = 'SXDf49A_XuuG0QqDf9trH';
update content_bodies set title = 'Powerful Experience! Naval Heritage Port Cruise', description = 'Take a cruise from Maizuru East Port through Maizuru Bay. Experience the impressive sight of a destroyer up close and visit shipyards associated with the navy. Enjoy the refreshing sea breeze while taking in the beautiful views from the water.' where id = 'PLrXnsKK13e24pvyAyjjL';
update content_bodies set title = '【うきはの今】 冬バージョン', description = 'この動画は、うきは市地域おこし協力隊の井上宗之輔によって制作され、福岡県うきは市の冬の風景や観光名所を紹介しています。浮羽稲荷神社や調音の滝、つづら棚田など、九州のこの地域の美しさと文化を垣間見ることができる内容となっています。' where id = 'TR5w5_bi2NdiLEgFgCHrz';
update content_bodies set title = 'Ukiha Now: Winter Version', description = 'This video, produced by Munenobu Inoue, a community revitalization cooperation team member in Ukiha City, showcases the winter scenery and attractions of Ukiha, Fukuoka Prefecture. The video highlights various locations such as Ukihainari Shrine, Chouon Falls, and Tsuzura Rice Terraces, providing a glimpse into the beauty and culture of this region in Kyushu.' where id = 'EnZ3FpTC-J9t2-HnMjqBD';
update content_bodies set title = '調音の滝｜うきはの今', description = '調音の滝は、四季折々の自然と美しく調和し、訪れる人々にやすらぎを提供するスポットです。春の新緑や秋の紅葉は特に美しく、夏は涼しさを感じることができる別天地です。清流ではそうめん流しを楽しむこともでき、夏期には地元住民が手作りのこんにゃくやしいたけ、お茶などの特産品を販売しています。公園内には、音楽のように水音が響くことから名付けられた調音の滝をはじめ、魚返りの滝や斧渕の滝などがあり、四季の景色を楽しみながら散策できます。' where id = 'JZLFVUSMN_SVR180x79Lt';
update content_bodies set title = 'Choonnotaki Waterfall | UkihaDays', description = 'Choonnotaki Waterfall is a serene spot that harmonizes beautifully with nature throughout the seasons, offering visitors a peaceful retreat. In spring, the fresh greenery and in autumn, the vibrant foliage create stunning views. Summer is particularly refreshing, providing a cool escape from the heat. The clear streams, where the sound of the river can be heard, also offer the fun of flowing somen noodles. During the summer, local residents sell seasonal specialties such as tea, shiitake mushrooms, and handmade konnyaku, showcasing the area''s natural bounty. The park features several waterfalls, including Choonnotaki, named after the sound of the water resembling music, as well as Uo-kaeri Falls and Onobuchi Falls. Visitors can enjoy a stroll while taking in the seasonal scenery.' where id = '2dI3wr1gM5yJZvEBX2p1x';
update content_bodies set title = '浮羽稲荷神社', description = '浮羽稲荷神社は城ヶ鼻公園内に位置し、伏見稲荷神社からの稲倉魂の神、京都松尾大社からの大山咋の神、太宰府天満宮からの菅原道真公の三神が祀られています。これらの神々は商売繁盛、五穀豊穣、健康、長命長寿、学問の神様として知られています。赤い鳥居を登ると、見晴らしの良いビュースポットがあり、天気が良ければ原鶴温泉や甘木方面を見渡すことができます。また、春には桜の名所としても有名です。近年、SNSでの人気が高まり、多くの参拝客が訪れています。' where id = 'aogejNZPb-DPOl90dmXMj';
update content_bodies set title = 'Ukiha Inari Shrine', description = 'Ukiha Inari Shrine, located within Jōganbana Park, is home to three deities: Uga Mitama no Kami from Fushimi Inari Shrine, Ōyama Kui no Kami from Matsuo Taisha in Kyoto, and Sugawara no Michizane from Dazaifu Tenmangu. These deities are believed to bring prosperity in business, abundant harvests, health, longevity, and academic success. Climbing the red torii gates along the mountain offers a scenic viewpoint, with clear weather allowing views of Harazuru Onsen and Amagi. The shrine is also famous for cherry blossoms in spring. Recently, it has gained popularity on social media, attracting many visitors.' where id = 'zVxp6L7UoURlHTCvVFZnr';
update content_bodies set title = '滝ノ上温泉　滝観荘', description = '滝ノ上温泉　滝観荘は、岩手県雫石町に位置しています。日帰り入浴は10時から17時まで営業しており、大人700円、4歳以上の子ども（小学生まで）は300円の料金がかかります。宿泊は予約制で、素泊まりのみの料金はお一人様7,000円（二人利用の場合は6,000円、三人利用の場合は5,000円）で、小学生までは3,000円です。金曜日、土曜日、祝前日は500円の追加料金があります。チェックインは15時、チェックアウトは10時です。なお、11月中旬から5月上旬までは冬期通行止めのため休業します。' where id = 'OT6SgZpOkCVzikPPT1ZEO';
update content_bodies set title = 'Takinoue Onsen Takikansou', description = 'Takinoue Onsen Takikansou is located in Shizukuishi, Iwate Prefecture. The facility offers day-use bathing from 10:00 AM to 5:00 PM, with fees of 700 yen for adults and 300 yen for children aged 4 to elementary school age. Reservations for overnight stays are available, with a room-only rate of 7,000 yen per person (6,000 yen for two people, 5,000 yen for three). Children up to elementary school age are charged 3,000 yen. There is an additional fee of 500 yen on Fridays, Saturdays, and the day before holidays. Check-in is at 3:00 PM and check-out is at 10:00 AM. Please note that the facility is closed from mid-November to early May due to winter road closures.' where id = 'Sbr7vfQObRBz6Bzhck_a9';
update content_bodies set title = '温泉民宿 あけぼの荘', description = '温泉民宿あけぼの荘は、岩手県岩手郡雫石町に位置する宿泊施設です。自然の温泉を楽しむことができる、伝統的な日本の民宿体験を提供しています。詳細は公式ウェブサイト（http://akebonosou.net/）をご覧ください。住所は、岩手県岩手郡雫石町鶯宿9-65-1で、電話番号は019-695-2245、ファックス番号は019-695-2247です。' where id = 'idfpl36f0mXaGUWvzzSMz';
update content_bodies set title = 'Akebono-so Hot Spring Inn', description = 'Akebono-so is a hot spring inn located in Shizukuishi Town, Iwate Prefecture, Japan. The inn offers a traditional Japanese lodging experience with access to natural hot springs. For more information, you can visit their website at http://akebonosou.net/. The address is 9-65-1 Ushuku, Shizukuishi Town, Iwate County, Iwate Prefecture, 020-0574. You can contact them via phone at 019-695-2245 or by fax at 019-695-2247.' where id = '06eNbyFth4VP4H2mtzd-6';
update content_bodies set title = '橋でつながり、人とつながる。（尾道バージョン）', description = 'しまなみ海道に住む人々が、訪れる人々にその魅力を語りかける動画です。それぞれのメッセージには、彼らの想いが込められており、穏やかな時間の流れの中でしっかりと伝わります。この動画を通じて、視聴者がしまなみ海道に行ってみたいと思うような内容に仕上がっています。ぜひご覧ください。' where id = 'aluGs-j86NHhbMYxSRH57';
update content_bodies set title = 'Connect with the Slow Cycle of Island Life', description = 'This video invites viewers to experience the charm of the Shimanami Kaido through the voices of its residents. Each person''s message is infused with their feelings, conveying a sense of calm that flows like the gentle passage of time. The aim is to inspire viewers to visit the Shimanami Kaido, making it a compelling invitation to explore this beautiful region.' where id = 'RWEsibqaD8dxye6bj2mO5';
update content_bodies set title = '橋でつながり、人とつながる。（今治バージョン）', description = 'しまなみ海道に住む人々が、訪れる人々にその魅力を語りかける動画です。それぞれのメッセージには、個々の想いが込められており、穏やかな時間の流れのように、しっかりと心に響きます。この動画を通じて、視聴者がしまなみ海道に行ってみたいと思うような内容に仕上がっています。ぜひご覧ください。' where id = 'Cg1-hhcd2icfO9M04Hb8c';
update content_bodies set title = 'Connect with the Slow Cycle of Island Life', description = 'This video invites visitors to experience the charm of the Shimanami Kaido through the voices of its residents. Each message reflects the unique feelings of the individuals, conveying a sense of calmness akin to the slow passage of time. The aim is to inspire viewers to consider visiting the Shimanami Kaido, making it a compelling invitation to explore this beautiful region.' where id = 'NMjik_K8xaRK4Cmmi0Ix-';
update content_bodies set title = 'サイクリングしまなみ2022', description = '2022年10月30日に開催された『サイクリングしまなみ2022』では、しまなみ海道・ゆめしま海道の美しい景観が紹介され、約7,000人のサイクリストが全国各地から集まりました。このイベントは4年ぶりの開催で、参加者は快晴の中、絶景を楽しみながら高速道路を走る貴重な機会を得ました。動画では、このサイクリングフェスティバルの魅力が伝えられ、地域の文化や住民との触れ合いも紹介されています。ぜひこの地を訪れ、自分自身のサイクリングアドベンチャーを計画してみてください。しまなみの魅力を体験しに来てください。' where id = 'Doxu6kpIx_cNdBuEDpL1B';
update content_bodies set title = 'CYCLING SHIMANAMI 2022', description = 'The CYCLING SHIMANAMI event, held on October 30, 2022, showcased the stunning landscapes of the Shimanami Kaido and Yumeshima Kaido, attracting around 7,000 cyclists from Japan and beyond. This event, returning after a four-year break, offered participants a unique chance to ride along the expressway, enjoying breathtaking views and local hospitality under perfect weather conditions. The video captures the essence of this cycling festival, encouraging viewers to explore the beauty of the region and plan their own cycling adventures. Shimanami welcomes everyone to experience its charm.' where id = '1IyF-SHAeodUuEFp-3GG6';
update content_bodies set title = 'しまなみレンタサイクル', description = 'しまなみレンタサイクルは、しまなみ海道を気軽にサイクリングできるサービスを提供しています。この美しいルートは、瀬戸内海の島々を結んでおり、訪れる人々が素晴らしい景色や観光名所を楽しむことができます。レンタル自転車を利用することで、手軽に周辺を探索できます。詳細は公式ウェブサイトをご覧ください。' where id = 'AUzdjwHWOFxPcZeVmzVXd';
update content_bodies set title = 'Shimanami Rental Cycles', description = 'Shimanami Rental Cycles offers an enjoyable cycling experience along the Shimanami Kaido, a scenic route that connects the islands of the Seto Inland Sea. The service provides rental bicycles for visitors, making it easy to explore the beautiful landscapes and attractions of the area. For more information, you can visit their website.' where id = 'Xvs0uHpoOOUeGBPqSaggl';
update content_bodies set title = '～2018年度総集編～  「海賊むすびにサイクリングソングを添えて、でござる！」の巻', description = 'この動画は、2018年度の総集編である「海賊むすびにサイクリングソングを添えて、でござる！」について紹介しています。内容は、海賊をテーマにしたむすびとサイクリングソングの組み合わせを楽しむもので、視聴者に楽しい体験を提供することを目的としています。' where id = '3gpl7LZW6wchSRA1ggi_x';
update content_bodies set title = '2018 Annual Compilation - ''Adding a Cycling Song to the Pirate Rice Ball!''', description = 'This video introduces the 2018 annual compilation titled ''Adding a Cycling Song to the Pirate Rice Ball!''.' where id = 'lyTSM8Zu2oSQ5tmxaao0P';
update content_bodies set title = '民泊体験2', description = '四国の徳島県西部に位置する「そらの郷」は、にし阿波エリアにあります。そらの郷山里物語では、教育旅行としての民泊を推奨しており、生徒たちは家族の一員として迎えられます。彼らは茶摘みやタマネギ、ジャガイモ、雑穀の収穫など、少量多品目の自給的農業に参加します。収穫した旬の野菜や山菜を使って共同で田舎料理を調理し、家族団らんの食事を通じて心の交流を深め、自然に触れる体験を行います。' where id = 'ad5vx-k19J8kcZgoVnc_i';
update content_bodies set title = 'Minpaku Experience 2', description = 'Located in the western part of Tokushima Prefecture, ''Sora no Sato'' is situated in the central region of Shikoku, known as Nishi-Awa (comprising Mima City, Miyoshi City, Tsurugi Town, and Higashi-Miyoshi Town). Sora no Sato Yamazato Monogatari promotes educational travel through minpaku (private lodging). Students are welcomed as family members and engage in collaborative self-sufficient agriculture, participating in activities such as tea picking and harvesting onions, potatoes, and grains. They also cook countryside dishes together using seasonal vegetables and mountain herbs, fostering emotional connections during family-style meals and experiencing nature.' where id = 'tQJAHNH4QDW4vxFdKgD-z';
update content_bodies set title = 'そらの郷南紀州視察研修', description = 'そらの郷山里物語教育旅行受入家庭のスキルアップと受入家庭同士の交流を目的に、南紀州へ視察研修に行きました。参加者は民泊家庭での体験を通じて、どのようにゲストを喜ばせることができるか、自分たちの町に帰って何ができるかを考える機会を得ました。自分たちの町が一番良いという気づきもありました。来年度春からの受入に向けて、一致団結し、高い目標を掲げています。そらの郷山里物語の教育旅行受入にぜひ参加してみませんか？' where id = '5FfSZI5auTTN1Htg2Lqid';
update content_bodies set title = 'Sora no Sato Nanki-Kishu Inspection Training', description = 'A training inspection was conducted in Nanki-Kishu to enhance the skills of host families involved in the Sora no Sato Yamazato Monogatari educational travel program and to promote interaction among them. Participants experienced staying in minpaku (private lodging) as students, reflecting on what could bring joy to guests and considering what they could implement upon returning to their own town. This experience sparked various thoughts, including the realization that their own town is the best. As they prepare for the upcoming acceptance of guests in spring next year, the group has united with high goals. They invite others to join in the educational travel program of Sora no Sato Yamazato Monogatari.' where id = 'csz1CSmF4XM97HE1sZz5G';
update content_bodies set title = '農泊（ゆずの里いづみ）', description = '徳島県美馬市にある農家民宿「ゆずの里いづみ」での体験動画です。この宿からは標高1,133ｍの高越山が真正面に見え、雨の日には雲海を楽しむことができます。宿の自慢は自家製のゆず味噌で、ピザ窯も完備されており、ピザを作って食べることができます。畑で採れたばかりの新鮮な野菜と一緒に味わってみてください。' where id = 'o3vUyTyHjwfz2NzyyXPHO';
update content_bodies set title = 'Farm Stay (Yuzu no Sato Izumi)', description = 'This is an experience video of the farm stay ''Yuzu no Sato Izumi'' located in Mima City, Tokushima Prefecture. The accommodation offers a direct view of Mount Kōetsu, which stands at 1,133 meters. On rainy days, guests can enjoy a sea of clouds. The highlight of the stay is the homemade yuzu miso. There is also a pizza oven available, allowing guests to make and enjoy pizza. Be sure to try it with freshly harvested vegetables from the farm.' where id = 'zzTdI3HTMoMhXtUwfKS-1';
update content_bodies set title = '愛知・名古屋テクニカルビジットPR動画（ダイジェスト）', description = '愛知・名古屋MICE推進協議会が作成したこのプロモーション動画では、産業視察を受け入れる企業の様子や担当者へのインタビューを紹介しています。実際の視察の様子を通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を感じることができる内容となっています。愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューローなどで構成されています。動画に収録されている企業は、2021年3月時点の参画企業です。' where id = 'LhRJmEAZKRGKJv-voi6__';
update content_bodies set title = 'Aichi-Nagoya Technical Visit Promotion Video (digest ver.)', description = 'This promotional video, created by the Aichi-Nagoya MICE Promotion Council, showcases companies that are open for tours, allowing visitors to learn about the local industry. The video features actual tours and interviews with staff, providing a glimpse into the atmosphere of the inspection sites and highlighting the unique appeal of technical visits in this region. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and other MICE-related stakeholders. The companies featured in the video are those participating as of March 2021.' where id = 'CkWkAZMWkaXS-KzcZobdy';
update content_bodies set title = '奥三河蒸留所', description = '愛知・名古屋MICE推進協議会が作成したこのプロモーション動画では、産業視察が可能な企業の様子や、担当者へのインタビューを通じて、視察先の雰囲気や地域特有のテクニカルビジットの魅力を紹介しています。実際の視察の様子を通じて、訪問者はこの地域ならではの体験を感じることができる内容となっています。愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューローなどで構成されています。' where id = 'jvjkmd_Pj1K3NHMGRSlTi';
update content_bodies set title = 'Technical Visit & Unique Venue –Journey to Aichi-', description = 'This promotional video by the Aichi-Nagoya MICE Promotion Council showcases a company that offers tours for visitors to learn about the industry. Through interviews with staff and actual tour footage, viewers can experience the atmosphere of the inspection site and discover the unique appeal of technical visits in this region. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders.' where id = 'Ogab8RyQtxOEHxVJ96LX0';
update content_bodies set title = '宿泊施設のご紹介 - ヒルトン名古屋', description = '愛知・名古屋ＭＩＣＥ推進協議会が作成したこのプロモーション動画では、インセンティブゲストにおすすめの宿泊施設であるヒルトン名古屋を紹介しています。動画では、施設の雰囲気や魅力を感じることができ、宿泊時の期待感を高める内容となっています。愛知・名古屋ＭＩＣＥ推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューロー、及びMICE関連の関係者で構成されています。ぜひこの動画をご覧いただき、宿泊施設のユニークな魅力を体験してください。' where id = 'Iif2MKcpLQmOrR7kZoiRa';
update content_bodies set title = 'Accommodation in Nagoya - Hilton Nagoya', description = 'This promotional video, created by the Aichi-Nagoya MICE Promotion Council, showcases the Hilton Nagoya hotel, which is highly recommended for incentive guests. The video captures the atmosphere of the facility and highlights its key features, providing viewers with a glimpse of what to expect during their stay. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders in the region. We encourage you to watch the video to experience the unique offerings of this accommodation.' where id = 'rlp9PpoRFBQ1vWKbTnm8G';
update content_bodies set title = '[愛知・名古屋産業視察] 株式会社テクノプラスト', description = '愛知・名古屋MICE推進協議会が制作したこのプロモーション動画では、産業視察を受け入れる企業の様子や、担当者へのインタビューを通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を紹介しています。実際の視察の様子を通じて、視聴者は愛知・名古屋の産業の魅力を感じることができる内容となっており、ぜひご覧いただきたいと思います。' where id = 'HK15ZkhybuvwYS9Rymlot';
update content_bodies set title = '[Aichi-Nagoya Technical Visit] TECHNOPLAST Co., Ltd.', description = 'This promotional video, created by the Aichi-Nagoya MICE Promotion Council, showcases a company that offers tours for visitors to learn about the industry. The video includes actual tours and interviews with staff, providing viewers with a sense of the inspection site''s atmosphere and the unique appeal of technical visits in this region. It invites viewers to experience the charm of Aichi-Nagoya''s industrial landscape.' where id = 'Vg-BwuNf7l3AC3sZyj-3E';
