update content_bodies set title = '技術視察とユニークな会場 - 愛知への旅 -', description = '愛知・名古屋MICE推進協議会が制作したこのプロモーション動画では、訪問者が業界について学ぶことができる企業の視察の様子を紹介しています。スタッフへのインタビューや実際の視察の映像を通じて、視察先の雰囲気やこの地域ならではのテクニカルビジットの魅力を体感することができます。愛知・名古屋MICE推進協議会は、愛知県、名古屋市、名古屋観光コンベンションビューロー、及びMICE関連のステークホルダーで構成されています。' where id = '4WT5ytqB3gxP6lV5vInkQ';
update content_bodies set title = 'Technical Visit & Unique Venue –Journey to Aichi-', description = 'This promotional video by the Aichi-Nagoya MICE Promotion Council showcases a company that offers tours for visitors to learn about the industry. Through interviews with staff and actual tour footage, viewers can experience the atmosphere of the inspection site and discover the unique appeal of technical visits in this region. The Aichi-Nagoya MICE Promotion Council is composed of the Aichi Prefectural Government, the City of Nagoya, the Nagoya Convention & Visitors Bureau, and various MICE-related stakeholders.' where id = '4PC5seW0ZY5F6qtpOseif';
