update content_bodies set title = 'Delicious and Cost-Effective! 6 Must-Try Gourmet Spots in Osaka Umeda', description = 'This video introduces six large-portion gourmet spots in Osaka, perfect for travelers and tourists. If you have any recommendations not mentioned in the video, please share them in the comments. The channel aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. For more travel tips and updates, you can follow their official social media accounts.' where id = 'SjNux7RO2q7zSQV7vGLgS';
update content_bodies set title = '利尻島アクティビティプロモーションムービー | 4K', description = '利尻島の美しさとアクティビティを紹介する「利尻島アクティビティプロモーションムービー」は、北海道に位置しています。この映像は、自然を取り入れた観光PR映像やトラベルビデオを得意とするEzo Explorerチームによって制作されました。キャストやクルーには多彩なカメラオペレーターやドローンパイロットが参加しており、使用されている機材には高品質なSonyカメラやDJIドローンが含まれています。制作依頼については、Ezo Explorerのメールアドレスまでお問い合わせください。' where id = 'aVFpL1WKPemFaerXCIEJC';
update content_bodies set title = 'Rishiri Activity Promotion Movie | 4K', description = 'The Rishiri Activity Promotion Movie showcases the beauty and activities of Rishiri Island, located in Hokkaido, Japan. The film is produced by the Ezo Explorer team, which specializes in creating travel videos and promotional content that highlights nature. The project features a talented cast and crew, including various camera operators and drone pilots. The equipment used includes high-quality Sony cameras and DJI drones, ensuring stunning visuals. For inquiries about production services, contact Ezo Explorer via email.' where id = 'zEkHe5foP3gzERDCkzImZ';
update content_bodies set title = '【香川絶品グルメ】うどんの聖地からお取り寄せ！讃岐うどん９選', description = '香川県への旅行や観光を考えている方に向けて、讃岐うどんのお取り寄せ情報を紹介する動画です。動画内では、9つのおすすめの讃岐うどんが紹介されており、視聴者はコメント欄で自分のおすすめをシェアすることが奨励されています。このチャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。運営メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = '2_enVcGATFo2DKkEJ2qpb';
update content_bodies set title = 'Delicious Gourmet from Kagawa: 9 Recommended Sanuki Udon for Delivery', description = 'This video serves as a guide for those traveling to Kagawa, showcasing nine recommended Sanuki udon options available for delivery. Viewers are encouraged to share their own recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and seeks to inspire viewers to discover new possibilities through their journeys. For more travel tips and updates, viewers can follow the official social media accounts.' where id = 'mtt7og-dX5AX_OM1x11HL';
update content_bodies set title = '【SAPPORO TEINE WEB Promotion Movie】', description = 'サッポロテイネスキー場のプロモーションムービーが制作されました。撮影にはGoPro HERO9とDJI Mavic AIR2が使用されています。監督は北海道を拠点に活動するクリエイターチーム「Ezo Explorer」で、観光PR映像やトラベルビデオを得意とし、自然を取り入れた映像制作を行っています。使用機材にはSony α7siii、α7iii、各種レンズ、DJI機器が含まれています。Ezo ExplorerはPR動画やWEB広告、ウエディング撮影など幅広いジャンルに対応しており、製作依頼はメールで受け付けています。' where id = 'cYreOd1aIMEKHmtQBkMbB';
update content_bodies set title = 'SAPPORO TEINE WEB Promotion Movie', description = 'This is a promotional movie for Sapporo Teine Ski Resort, filmed using GoPro HERO9 and DJI Mavic AIR2. The project was directed by Ezo Explorer, a creator team based in Hokkaido that specializes in tourism PR videos and travel films, incorporating nature into their visuals. They are equipped with various high-quality gear, including Sony α7siii, α7iii, and multiple lenses, as well as DJI equipment. Ezo Explorer handles a wide range of genres, from PR videos and web advertisements to wedding photography. For production inquiries, contact them via the provided email.' where id = 'nRq13hIKdAIJ3hlNJ9IH9';
update content_bodies set title = '【デカ盛り】規格外！埼玉のデカ盛りグルメ７選', description = '埼玉県への旅行や観光に役立つ情報を提供する動画で、特にデカ盛りグルメに焦点を当てています。紹介された料理には、バカ盛り海鮮丼やスーパージャンボカツなどがあり、各店舗の詳細も記載されています。視聴者からのオススメもコメント欄で受け付けており、旅行の達人公式LINEではお得な旅行情報を配信しています。このチャンネルは、旅行を通じて人生を豊かにすることを目指しており、観光地や店舗のPRも行っています。' where id = 'EHbOMzD4AFfA67DHK-gWw';
